import { Book } from "@/lib/types";

export const deuteronomy: Book = {
  id: "deuteronomy",
  name: "5. Mose (Deuteronomium)",
  shortName: "5. Mose",
  testament: "old",
  introduction: `Die Erneuerung des Bundes\n**Das fünfte Buch Mose** wird auch Deuteronomium, zweites Gesetz, genannt, weil in ihm aufgeschrieben ist, wie Mose am Ende seines Lebens dem Volk das ganze Gesetz noch einmal vor Augen stellt und in drei großen Reden und einer Zusammenfassung erklärt. Inzwischen war eine neue Generation herangewachsen, die im Begriff stand, das Land Kanaan zu erobern. Aus diesem Grund musste ihnen das Gesetz, das die Väter 38 Jahre vorher angenommen hatten, neu erklärt werden, damit sie sich verbindlich dazu stellten. Für das junge Israel hing alles von seiner Treue zum Gesetz ab, auch der Besitz des verheißenen Landes. Mose schrieb diese Reden kurz vor seinem Tod nieder, vermutlich im Jahr 1406 v.Chr. Nur das letzte Kapitel wurde wohl von Josua hinzugefügt. Der Aufbau des Buches entspricht dem eines altorientalischen Vasallenvertrags mit Präambel, historischer Einleitung, allgemeinem Gebot, speziellen Geboten sowie Segen und Fluch.\n****Wie die nächste Generation der Israeliten noch einmal auf den Bund mit Gott verpflichtet wird.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Folgende Worte sprach Mose zu ganz Israel, als es sich jenseits des Jordan in der Araba* befand, in der Steppe gegenüber von Suf, zwischen Paran, Tofel, Laban, Hazerot und Di-Sahab.*", heading: "1-4: Rückblick auf die Treue Gottes\nOrt und Zeit", footnotes: ["Als Araba wird der Jordangraben bezeichnet, der sich von Norden nach Süden durch ganz Israel bis nach Elat am Roten Meer zieht. Sein Boden ist zwischen 12,5 und 22,5 km breit und befindet sich fast überall unter der Höhe des Meeresspiegels, am Toten Meer 394 m unter NN.", "...Di-Sahab. Die genaue Lage dieser Orte ist unbekannt. Die Beschreibung im Ganzen verweist auf das Gebiet Moabs."] },
      { number: 2, text: "Elf Tagereisen sind es vom Berg Horeb auf dem Weg zum Gebirge Seïr* bis Kadesch-Barnea*.", footnotes: ["Das Gebirge Seïr erstreckt sich östlich der Araba vom Toten Meer bis nach Elat und wurde von Edomitern bewohnt.", "Kadesch-Barnea lag an der Südgrenze von Kanaan, etwa 80 km südwestlich von Beerscheba."] },
      { number: 3, text: "Am 1. Februar im 40. Jahr nach dem Auszug aus Ägypten* sagte Mose den Israeliten, was Jahwe ihm für sie aufgetragen hatte.", footnotes: ["nach dem Auszug aus Ägypten. Vom Übersetzer hinzugefügt. Zum Datum siehe unter \"Schaltmonat\" im Vorwort des Übersetzers. Das 40. Jahr ginge hier schon in 1405 v.Chr. über."] },
      { number: 4, text: "Vorher hatte er den Amoriterkönig Sihon besiegt, der in Heschbon* wohnte, und Og, den König von Baschan*, der in Aschtarot und Edreï lebte.", footnotes: ["Heschbon lag 25 km östlich der Jordanmündung ins Tote Meer.", "Baschan war das Gebiet östlich und nördlich vom See Gennesaret."] },
      { number: 5, text: "Dort im Land Moab, jenseits des Jordan, begann Mose das Gesetz auszulegen. Er sagte:" },
      { number: 6, text: "Jahwe, unser Gott, hat am Horeb* zu uns gesagt: \"Lange genug habt ihr euch an diesem Berg aufgehalten.", heading: "Der Aufbruch vom Horeb", footnotes: ["Horeb. Anderer Name für den Berg Sinai oder ein anderer Gipfel in derselben Bergregion. Der Sinai wird meist mit dem Dschebel Musa im Südosten der Sinai-Halbinsel identifiziert, was aber nicht sicher ist."] },
      { number: 7, text: "Macht euch auf und zieht weiter ins Bergland der Amoriter* und zu allen ihren Nachbarn in der Araba, im Gebirge, in der Schefela*, im Negev* und an der Meeresküste, zieht ins Land der Kanaaniter, zum Libanon bis an den großen Strom, den Euphrat!", footnotes: ["Amoriter kann sowohl für einen einzelnen Stamm als auch für alle Bewohner Kanaans stehen. Es waren semitische Einwanderer aus der Arabischen Wüste, die um 2000 v.Chr. ins Kulturland eindrangen.", "Schefela.Niedriges, sehr fruchtbares Hügelland, das sich in nordsüdlicher Richtung zwischen dem Gebirge und der Küstenebene des Mittelmeeres erstreckt.", "Negev. Das heiße Südland Israels, zum Teil gebirgige Wüste."] },
      { number: 8, text: "Seht, dieses Land übergebe ich euch. Zieht hinein und nehmt es in Besitz! Es ist das Land, das Jahwe euren Vorfahren Abraham, Isaak und Jakob unter Eid versprochen hat, es ihnen und ihren Nachkommen zu geben.\"" },
      { number: 9, text: "Damals sagte ich zu euch: \"Ich allein kann euch nicht tragen.", heading: "Wie Mose Richter einsetzte" },
      { number: 10, text: "Jahwe, euer Gott, hat euch zahlreich werden lassen. Und seht, ihr seid heute so zahlreich wie die Sterne am Himmel." },
      { number: 11, text: "Jahwe, der Gott eurer Vorfahren, möge euch noch tausendmal zahlreicher machen und euch segnen, wie er es euch zugesagt hat." },
      { number: 12, text: "Wie könnte ich allein die Bürde und Last eurer Streitigkeiten tragen?" },
      { number: 13, text: "Schafft weise, verständige und erfahrene Männer aus euren Stämmen herbei, die ich als Oberhäupter über euch einsetzen kann.\"" },
      { number: 14, text: "Ihr gabt mir zur Antwort: \"Ja, dein Vorschlag ist gut!\"" },
      { number: 15, text: "Ich wählte also in euren Stämmen weise und erfahrene Männer aus und setzte sie als Oberhäupter über euch ein, Obere über Tausend, Hundert, Fünfzig und Zehn, und als Verwalter für eure Stämme." },
      { number: 16, text: "Sie sollten als Richter in Streitfällen entscheiden. Ich befahl ihnen: \"Hört euren Brüdern genau zu und richtet gerecht, egal, ob ein Mann mit seinem Bruder oder einem Fremden streitet." },
      { number: 17, text: "Urteilt ohne Ansehen der Person und hört euch die kleinen Leute genauso wie die großen an. Lasst euch von keinem einschüchtern, denn beim Gericht geht es um Gottes Sache. Ist euch ein Rechtsfall zu schwer, dann legt ihn mir vor, dass ich ihn anhöre.\"" },
      { number: 18, text: "Damals habe ich euch angewiesen, all diese Dinge zu tun." },
      { number: 19, text: "Dann brachen wir vom Horeb auf und zogen durch diese ganze große und schreckliche Wüste – ihr habt sie gesehen – auf dem Weg zum Bergland der Amoriter. So hatte Jahwe, unser Gott, es uns befohlen, und wir kamen bis Kadesch-Barnea.", heading: "Die Kundschafter" },
      { number: 20, text: "Da sagte ich zu euch: \"Ihr seid bis zum Bergland der Amoriter gekommen, das Jahwe, unser Gott, uns gibt." },
      { number: 21, text: "Schau, Jahwe, dein Gott, hat das Land, das vor dir liegt, in deine Gewalt gegeben. Zieh hinauf und nimm es in Besitz, wie Jahwe, der Gott deiner Väter, es dir gesagt hat. Hab keine Angst und fürchte dich nicht!\"" },
      { number: 22, text: "Da tratet ihr alle an mich heran und sagtet: \"Lasst uns ein paar Männer vorausschicken, die das Land erkunden. Sie sollen uns sagen, welchen Weg wir am besten einschlagen und was für Städte wir dort antreffen.\"" },
      { number: 23, text: "Ich fand den Vorschlag gut und wählte zwölf Männer von euch aus, einen aus jedem Stamm." },
      { number: 24, text: "Die machten sich auf den Weg ins Bergland und erkundeten es bis ins Traubental." },
      { number: 25, text: "Als sie zurückkamen, brachten sie Früchte von dort mit und erklärten: \"Das Land ist gut, das Jahwe, unser Gott, uns gibt.\"" },
      { number: 26, text: "Aber ihr habt euch dem Befehl Jahwes, eures Gottes, widersetzt und wolltet nicht hinaufziehen." },
      { number: 27, text: "Ihr habt in euren Zelten gemurrt und gesagt: \"Weil Jahwe uns hasst, hat er uns aus Ägypten geführt, um uns den Amoritern auszuliefern, damit sie uns vernichten." },
      { number: 28, text: "Wohin sollen wir denn ziehen? Unsere Brüder haben uns allen Mut genommen, denn sie sagten: 'Ein Volk, größer und höher gewachsen als wir, große Städte mit Mauern bis an den Himmel und sogar Anakiter* haben wir dort gesehen.'\"", footnotes: ["Anakiter. Sippe von riesenhaften Menschen in der Umgebung von Hebron, siehe 4. Mose 13,33."] },
      { number: 29, text: "Da sagte ich zu euch: \"Erschreckt doch nicht und habt keine Angst vor ihnen!" },
      { number: 30, text: "Jahwe, euer Gott, der vor euch herzieht, er wird für euch kämpfen, genauso wie er es in Ägypten für euch getan hat," },
      { number: 31, text: "und in der Wüste, wo du gesehen hast, dass Jahwe, dein Gott, dich trug, wie ein Mann seinen Sohn trägt, und zwar auf dem ganzen Weg, den ihr gezogen seid, bis ihr hierher kamt.\"" },
      { number: 32, text: "Aber trotzdem hattet ihr kein Vertrauen zu Jahwe, eurem Gott," },
      { number: 33, text: "der auf dem Weg vor euch herzog, um einen Lagerplatz für euch zu suchen: bei Nacht im Feuer, damit ihr etwas sehen konntet auf dem Weg, den ihr gehen solltet, und bei Tag in einer Wolke." },
      { number: 34, text: "Jahwe hörte euer lautes Reden. Da wurde er zornig und schwor:" },
      { number: 35, text: "\"Von diesen Männern, von dieser bösen Generation, wird keiner das gute Land sehen, das ich euren Vorfahren unter Eid versprochen habe." },
      { number: 36, text: "Nur Kaleb Ben-Jefunne soll es sehen. Ihm und seinen Kindern werde ich das Land geben, das er betreten hat, weil er unbeirrt hinter mir stand.\"" },
      { number: 37, text: "Euretwegen wurde Jahwe auch über mich zornig. \"Auch du wirst nicht dort hineinkommen\", sagte er." },
      { number: 38, text: "\"Doch Josua Ben-Nun, dein Diener, er soll hineinkommen. Ermutige ihn, denn er soll Israel das Land als Erbbesitz verteilen!" },
      { number: 39, text: "Und eure kleinen Kinder, von denen ihr sagtet, sie würden zur Beute werden, und eure Kinder, die heute noch nicht wissen, was gut und böse ist, sie werden in das Land kommen. Ihnen werde ich es geben und sie sollen es in Besitz nehmen." },
      { number: 40, text: "Ihr sollt jetzt umkehren und wieder in die Wüste ziehen, Richtung Schilfmeer!\"" },
      { number: 41, text: "Da habt ihr zu mir gesagt: \"Wir haben gegen Jahwe gesündigt. Wir wollen hinaufziehen und kämpfen, wie Jahwe, unser Gott, es uns befohlen hat.\" Jeder legte seine Waffen an, und es schien euch leicht, ins Bergland hinaufzuziehen." },
      { number: 42, text: "Da sagte Jahwe zu mir: \"Sag ihnen, sie sollen nicht hinaufziehen und kämpfen, denn ich werde nicht mit euch gehen und ihr werdet von euren Feinden geschlagen werden!\"" },
      { number: 43, text: "Ich sagte euch das, aber ihr habt nicht darauf gehört. Ihr habt euch dem Befehl Jahwes widersetzt und seid in eurer Vermessenheit ins Bergland hinaufgezogen." },
      { number: 44, text: "Da stellten sich die Amoriter, die dort im Bergland wohnten, euch entgegen und verjagten euch, wie es die Bienen tun. Sie versprengten euch vom Gebirge Seïr bis nach Horma* hin.", footnotes: ["Horma war ein Ort im Umkreis von Beerscheba."] },
      { number: 45, text: "So seid ihr zurückgekommen und habt vor Jahwe geweint. Aber Jahwe hörte nicht auf euer Klagen und schenkte euch kein Gehör." },
      { number: 46, text: "So seid ihr eine lange Zeit in Kadesch geblieben, eben so lange, wie ihr dort bleiben musstet." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Dann wanderten wir wieder zurück in die Wüste auf dem Weg Richtung Schilfmeer, wie Jahwe es mir gesagt hatte. Eine lange Zeit zogen wir um das Bergland von Seïr herum.", heading: "Der Zug ins Ostjordanland" },
      { number: 2, text: "Dann sagte Jahwe zu mir:" },
      { number: 3, text: "\"Ihr seid jetzt lange genug um dieses Gebirge herumgezogen, wendet euch nun nach Norden." },
      { number: 4, text: "Befiehl dem Volk: 'Ihr zieht nun durch das Gebiet eurer Brüder, der Nachkommen Esaus, die in Seïr wohnen. Sie werden sich vor euch fürchten. Nehmt euch aber sehr in acht!" },
      { number: 5, text: "Lasst euch auf keinen Streit mit ihnen ein, denn ich werde euch von ihrem Land keinen Fußbreit geben. Denn das Bergland von Seïr habe ich für Esau zum Erbbesitz bestimmt." },
      { number: 6, text: "Wenn ihr Nahrungsmittel oder Wasser braucht, sollt ihr es ihnen bezahlen.'" },
      { number: 7, text: "Denn Jahwe, dein Gott, hat dich in all deinem Tun gesegnet. Er hat auf deine Wanderung durch diese große Wüste achtgegeben. Vierzig Jahre ist Jahwe, dein Gott, nun schon mit dir. Und es hat dir an nichts gefehlt.\"" },
      { number: 8, text: "So zogen wir von Elat und Ezjon-Geber aus an unseren Brüdern vorüber, den Nachkommen Esaus in Seïr, auf dem Weg durch die Araba und weiter auf dem Weg in die Wüste von Moab." },
      { number: 9, text: "Da sagte Jahwe zu mir: \"Greift die Moabiter* nicht an und lasst euch auf keinen Krieg mit ihnen ein. Auch von ihrem Land gebe ich euch nichts, denn Ar* habe ich den Nachkommen Lots zum Erbbesitz gegeben.", footnotes: ["Die Moabiter lebten östlich des Toten Meeres zwischen den Flüssen Arnon und Zered.", "Ar war eine wichtige moabitische Stadt."] },
      { number: 10, text: "Früher haben die Emiter dort gewohnt, ein großes, zahlreiches und hochgewachsenes Volk wie die Anakiter." },
      { number: 11, text: "Sie werden wie die Anakiter zu den Refaïtern gezählt; die Moabiter aber nennen sie Emiter." },
      { number: 12, text: "Und in Seïr wohnten früher die Horiter. Aber die Nachkommen Esaus haben sie vernichtet und ihren Besitz übernommen. Sie ließen sich an ihrer Stelle nieder, so wie es Israel mit dem Land gemacht hat, das Jahwe ihnen zum Besitz gab." },
      { number: 13, text: "Nun brecht auf und überschreitet das Tal des Sered.\" Wir taten es." },
      { number: 14, text: "Seit unserem Aufbruch von Kadesch-Barnea waren 38 Jahre vergangen. Inzwischen war die ganze Generation der kriegstüchtigen Männer des Lagers gestorben, wie Jahwe es ihnen geschworen hatte." },
      { number: 15, text: "Er hatte dafür gesorgt, dass sie vollständig aus dem Lager beseitigt wurden." },
      { number: 16, text: "Als nun alle Krieger aus dem Volk weggestorben waren," },
      { number: 17, text: "sagte Jahwe zu mir:" },
      { number: 18, text: "\"Du wirst nun durch das Gebiet von Moab und Ar ziehen" },
      { number: 19, text: "und in die Nähe der Ammoniter* kommen. Greif sie nicht an und lass dich auf keinen Streit mit ihnen ein, denn ich werde dir vom Land der Ammoniter nichts geben, weil ich es den Nachkommen Lots zum Erbbesitz gab.\"–", footnotes: ["Die Ammoniter lebten nordöstlich vom Toten Meer."] },
      { number: 20, text: "Auch dieses Gebiet gilt als Land der Refaïter. Sie hatten vorher dort gewohnt. Die Ammoniter nannten sie Samsummiter." },
      { number: 21, text: "Es war ein großes, zahlreiches und hochgewachsenes Volk wie die Anakiter. Jahwe vernichtete sie vor ihnen und sie übernahmen deren Besitz und wohnten an ihrer Stelle dort," },
      { number: 22, text: "so wie Jahwe es für die Nachkommen Esaus getan hat, die in Seïr wohnen, vor denen er die Horiter vernichtete, sodass sie deren Besitz übernahmen und sich an ihrer Stelle niederließen." },
      { number: 23, text: "Das Gleiche machten die Kaftoriter mit den Awitern, die in den Dörfern bei Gaza wohnten. Als sie aus Kaftor* kamen, vernichteten sie die Awiter und ließen sich an ihrer Stelle dort nieder. –", footnotes: ["Kaftor. Heimat der Vorfahren der Philister, vermutlich Zypern."] },
      { number: 24, text: "\"Brecht jetzt auf\", sagte Jahwe, \"und überquert den Arnonfluss. Ich habe den Amoriterkönig Sihon von Heschbon und sein Land in deine Gewalt gegeben. Fang an, nimm es in Besitz und lass dich auf einen Krieg mit ihm ein." },
      { number: 25, text: "Von heute an will ich Schrecken und Furcht vor euch über alle Völker auf der ganzen Welt bringen. Alle, die davon hören, werden vor euch zittern.\"" },
      { number: 26, text: "Da schickte ich Boten von der Wüste Kedemot zu König Sihon von Heschbon mit friedlichen Worten. Ich ließ ihm sagen:", heading: "Die Eroberung von Sihons Reich" },
      { number: 27, text: "\"Ich möchte durch dein Land ziehen. Wir werden nur die Straße benutzen und weder rechts noch links vom Weg abweichen." },
      { number: 28, text: "Was wir an Nahrungsmitteln und Wasser brauchen, werden wir bezahlen. Wir wollen weiter nichts, als durch euer Land ziehen." },
      { number: 29, text: "Auch die Nachkommen Esaus, die in Seïr wohnen, und die Moabiter von Ar haben uns das erlaubt. Ich will nur über den Jordan in das Land ziehen, das Jahwe, unser Gott, uns gibt.\"" },
      { number: 30, text: "Aber König Sihon von Heschbon wollte uns nicht bei sich durchziehen lassen, denn Jahwe, dein Gott, hatte ihn starrsinnig und hart gemacht, um ihn dir auszuliefern, wie es ja auch geschehen ist." },
      { number: 31, text: "Jahwe sagte zu mir: \"Schau, ich habe begonnen, Sihon und sein Land dir preiszugeben. Fang an, nimm es in Besitz, es soll dir gehören.\"" },
      { number: 32, text: "Sihon zog uns mit all seinen Streitkräften nach Jahaz* entgegen.", footnotes: ["Jahaz. Stadt, östlich vom Toten Meer, 15 km nordöstlich von Dibon."] },
      { number: 33, text: "Aber Jahwe, unser Gott, lieferte ihn uns aus. Wir töteten ihn, seine Söhne und sein ganzes Volk." },
      { number: 34, text: "Damals nahmen wir alle seine Städte ein und vollstreckten den Bann an ihren Bewohnern, an Männern, Frauen und Kindern. Keinen ließen wir lebend entkommen." },
      { number: 35, text: "Nur das Vieh behielten wir für uns als Beute und das Raubgut aus den Städten, die wir eingenommen hatten." },
      { number: 36, text: "Von Aroer an, das am Rand des Arnontals liegt, und von der Stadt im Flusstal bis nach Gilead* gab es keine Stadt, die uns zu stark gewesen wäre, alle lieferte Jahwe, unser Gott, uns aus.", footnotes: ["Gilead bezeichnet das mittlere, manchmal auch das ganze Ostjordanland."] },
      { number: 37, text: "Nur vom Land der Ammoniter, dem ganzen Gebiet am Fluss Jabbok, hast du dich ferngehalten, auch von den Städten im Bergland, wie Jahwe, unser Gott, es befohlen hat." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Dann zogen wir den Weg nach Baschan* hinauf. König Og von Baschan zog uns mit seinem ganzen Heer nach Edreï* zum Kampf entgegen.", heading: "Der Sieg über König Og von Baschan", footnotes: ["Baschan. Fruchtbare Bergregion östlich vom See Gennesaret.", "Edreï. Das heutige Dera, 96 km südlich von Damaskus."] },
      { number: 2, text: "Jahwe sagte zu mir: \"Hab keine Angst vor ihm, denn ich habe ihn, sein ganzes Volk und sein Land in deine Hand gegeben. Du kannst mit ihm tun, was du mit dem Amoriterkönig Sihon getan hast, der in Heschbon regierte.\"" },
      { number: 3, text: "So gab Jahwe, unser Gott, auch Og, den König von Baschan, und sein ganzes Volk in unsere Gewalt. Wir erschlugen ihn und ließen keinen von seinem Volk lebend entkommen." },
      { number: 4, text: "Damals nahmen wir alle seine Städte ein, insgesamt 60. Wir eroberten das ganze Gebiet von Argob, also das Königreich Ogs im Baschan." },
      { number: 5, text: "Alle Städte waren befestigt und mit hohen Mauern, mit Toren und Riegeln versehen. Dazu kamen noch viele Ortschaften auf dem Land." },
      { number: 6, text: "Wir vollstreckten den Bann an ihnen, wie wir es bei König Sihon von Heschbon gemacht hatten, und töteten alle Männer, Frauen und Kinder." },
      { number: 7, text: "Nur das Vieh behielten wir für uns als Beute und das Raubgut aus den Städten." },
      { number: 8, text: "So nahmen wir damals den beiden Königen der Amoriter das Land östlich des Jordan ab, vom Flusstal des Arnon bis an den Berg Hermon." },
      { number: 9, text: "– Von den Sidoniern wird der Hermon übrigens Sirjon und von den Amoritern Senir genannt. –" },
      { number: 10, text: "Wir eroberten alle Städte in der Ebene, das ganze Gilead, ganz Baschan bis nach Salcha und Edreï und alle Städte im Reich des Königs Og von Baschan." },
      { number: 11, text: "König Og war der letzte vom Geschlecht der Refaïter. Sein eisernes Bett steht ja noch in Rabba, der Hauptstadt von Ammon. Es ist viereinhalb Meter lang und zwei Meter* breit.", footnotes: ["viereinhalb ... Meter. Wörtlich: neun bzw. vier Ellen nach der Elle eines Mannes."] },
      { number: 12, text: "Dieses Land haben wir damals in Besitz genommen. Ich gab das Gebiet von Aroer im Flusstal des Arnon und die Hälfte des Gebirges Gilead mit seinen Städten den Rubeniten und Gaditen.", heading: "Die Verteilung des Ostjordanlandes" },
      { number: 13, text: "Den Rest von Gilead und das ganze Baschan, das Reich des Königs Og, gab ich dem halben Stamm Manasse, also die ganze Landschaft Argob. Das ganze Baschan heißt Land der Refaïter." },
      { number: 14, text: "Jaïr Ben-Manasse nahm die ganze Landschaft Argob bis zum Gebiet der Geschuriter und Maachiter ein und nannte sie nach seinem Namen: Zeltdörfer Jaïrs. – So heißen sie bis heute. –" },
      { number: 15, text: "Dem Machir gab ich Gilead," },
      { number: 16, text: "den Rubeniten und Gaditen gab ich das Gebiet von Gilead bis zum Arnontal – die Mitte des Flusstals war die Grenze – und bis zum Flusstal des Jabbok, das die Grenze zu den Ammonitern bildet," },
      { number: 17, text: "und die Araba mit dem Jordan als Grenze, von Kinneret* an bis zum Meer der Araba, dem Salzmeer, unterhalb der Berghänge des Pisga Richtung Osten.", footnotes: ["Kinneret. Früherer Name des Sees Gennesaret und einer Ortschaft an seinem Westufer."] },
      { number: 18, text: "\"Damals wies ich euch an: Jahwe, euer Gott, hat euch dieses Land gegeben. Ihr sollt es in Besitz nehmen. Alle Kampftüchtigen von euch sollen gerüstet vor euren israelitischen Brüdern hinüberziehen.", heading: "Vorbereitung zur Eroberung des Westjordanlandes" },
      { number: 19, text: "Nur eure Frauen, eure Kinder und euer Vieh – ich weiß, dass ihr viele Herden habt – sollen in den Städten bleiben, die ich euch gegeben habe." },
      { number: 20, text: "Erst wenn Jahwe auch euren Brüdern Ruhe verschafft hat und sie das Land auf der anderen Seite des Jordan in Besitz genommen haben, das Jahwe, euer Gott, ihnen gibt, dürft ihr wieder zu eurem Erbbesitz zurückkehren, den ich jedem von euch zuteilte.\"" },
      { number: 21, text: "Und Josua befahl ich damals: \"Du hast alles gesehen, was Jahwe, euer Gott, an diesen beiden Königen getan hat. Genau das wird Jahwe allen Königreichen antun, gegen die du ziehst." },
      { number: 22, text: "Hab keine Angst vor ihnen! Jahwe, euer Gott, wird selbst für euch kämpfen.\"" },
      { number: 23, text: "Damals flehte ich Jahwe um sein Erbarmen an.", heading: "Warum Mose das Land nicht betreten darf" },
      { number: 24, text: "\"Jahwe, mein Herr\", sagte ich, \"du hast begonnen, deinem Diener deine Größe und Macht zu zeigen. Welcher Gott im Himmel und auf der Erde könnte es deinen Werken und gewaltigen Taten gleichtun?" },
      { number: 25, text: "Lass mich doch auch hinübergehen und das gute Land auf der anderen Seite des Jordan sehen, das gute Bergland und den Libanon!\"" },
      { number: 26, text: "Doch wegen euch war Jahwe zornig über mich und hörte nicht auf mich. Er sagte: \"Genug! Kein Wort mehr davon!" },
      { number: 27, text: "Steig auf den Gipfel des Pisga* und sieh nach Westen, Norden, Süden und Osten, und schau mit deinen Augen, denn du wirst diesen Jordan nicht überschreiten!", footnotes: ["Pisga. Berg oder Bergkette, wahrscheinlich in der Nähe des Nebo, 14 km östlich vom Nordende des Toten Meeres."] },
      { number: 28, text: "Beauftrage Josua, stärke und ermutige ihn! Er soll vor dem Volk hinübergehen und ihnen das Land als Erbbesitz austeilen, das du sehen darfst.\"" },
      { number: 29, text: "So blieben wir im Tal gegenüber von Bet-Peor." },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Nun höre, Israel! Ich werde euch die Ordnungen und Rechte lehren, nach denen ihr handeln sollt. Befolgt sie, dann werdet ihr am Leben bleiben und das Land in Besitz nehmen, das Jahwe, der Gott eurer Väter, euch gibt!", heading: "Aufforderung zum Gehorsam" },
      { number: 2, text: "Ihr sollt zu dieser Anweisung nichts hinzufügen und nichts davon wegnehmen, sondern ihr sollt die Gebote Jahwes, eures Gottes, halten, wie ich sie euch sage!" },
      { number: 3, text: "Ihr habt ja gesehen, was Jahwe wegen des Baal-Peor getan hat. Jahwe, dein Gott, hat jeden, der sich mit diesem Götzen einließ, aus deiner Mitte beseitigt.*", footnotes: ["Gott hat jeden ... beseitigt. Vergleiche 4. Mose 25!"] },
      { number: 4, text: "Doch ihr habt an Jahwe, eurem Gott, festgehalten. Deshalb seid ihr alle heute noch am Leben." },
      { number: 5, text: "Seht, ich habe euch Ordnungen und Rechte gelehrt, so wie Jahwe, mein Gott, es mir befahl, damit ihr danach handelt in dem Land, das ihr in Besitz nehmen werdet." },
      { number: 6, text: "So haltet sie und handelt danach! Denn darin besteht eure Weisheit und Einsicht in den Augen der Völker. Wenn sie von diesen Ordnungen hören, werden sie sagen: \"Was für ein weises und einsichtiges Volk ist diese große Nation!\"" },
      { number: 7, text: "Denn welche große Nation hat Götter, die ihr so nahe sind wie Jahwe, unser Gott, wann immer wir zu ihm rufen?" },
      { number: 8, text: "Und wo gibt es eine große Nation, die so gerechte Ordnungen und Vorschriften hätte wie dieses Gesetz, das ich euch heute vorlege." },
      { number: 9, text: "Nur hüte dich und achte gut auf dich selbst, dass du nicht vergisst, was du mit eigenen Augen gesehen hast, dass dir diese Dinge dein ganzes Leben lang nicht aus dem Sinn kommen! Erzähle deinen Kindern und Enkeln davon!" },
      { number: 10, text: "Denk an den Tag, an dem du vor Jahwe, deinem Gott, am Horeb standest, als Jahwe zu mir sagte: \"Ruf das Volk zusammen, damit sie meine Worte hören und lernen, mich zu fürchten* ihr ganzes Leben lang, und das auch ihre Kinder lehren!\"", footnotes: ["fürchten. Das hebräische Wort bedeutet Ehrfurcht, Respekt, Erstaunen, Erzittern und Furcht."] },
      { number: 11, text: "Da kamt ihr heran und standet unten am Berg. Der Berg brannte lichterloh bis in den Himmel hinein und war von Finsternis, Wolken und Dunkel umgeben." },
      { number: 12, text: "Mitten aus dem Feuer sprach Jahwe zu euch. Ihr hörtet den Schall seiner Worte, aber ihr habt keine Gestalt gesehen, sondern nur eine Stimme gehört." },
      { number: 13, text: "Er verkündete euch seinen Bund, den er euch zu halten befahl: die zehn Gebote. Er schrieb sie auf zwei Tafeln aus Stein." },
      { number: 14, text: "Und mir befahl Jahwe damals, euch die Ordnungen und Vorschriften zu lehren, damit ihr euch in dem Land, das ihr in Besitz nehmen wollt, danach richtet." },
      { number: 15, text: "Als Jahwe am Horeb aus dem Feuer zu euch sprach, habt ihr keine Gestalt gesehen. So hütet euch um eures Lebens willen,", heading: "Warnung vor Götzendienst" },
      { number: 16, text: "dass ihr nicht in euer Verderben rennt und euch ein Gottesbild macht, das irgendetwas darstellt, eine Statue, das Abbild eines männlichen oder weiblichen Wesens," },
      { number: 17, text: "das Abbild eines Landtiers oder eines fliegenden Vogels," },
      { number: 18, text: "das Abbild eines Kriechtiers oder eines Fischs im Wasser." },
      { number: 19, text: "Und wenn ihr zum Himmel aufblickt und die Sonne, den Mond und die Sterne seht, das ganze Himmelsheer, dann lasst euch ja nicht verleiten, vor ihnen niederzufallen und sie zu verehren. Jahwe, dein Gott, hat sie doch allen Völkern auf der ganzen Welt zugeteilt." },
      { number: 20, text: "Aber euch hat Jahwe aus dem eisernen Schmelzofen Ägyptens herausgeführt, damit ihr sein eigenes Volk sein solltet, wie es heute der Fall ist." },
      { number: 21, text: "Doch wegen euch ist Jahwe über mich zornig geworden und hat geschworen, dass ich den Jordan nicht überschreiten und in das gute Land kommen darf, das Jahwe, dein Gott, dir als Erbbesitz gibt." },
      { number: 22, text: "Denn ich sterbe in diesem Land hier. Ich gehe nicht über den Jordan. Aber ihr werdet hinüberziehen und dieses gute Land in Besitz nehmen." },
      { number: 23, text: "Nehmt euch in acht! Vergesst ja nicht den Bund, den Jahwe, euer Gott, mit euch geschlossen hat, dass ihr euch ein Gottesbild macht, das irgendetwas darstellt, was Jahwe, dein Gott, dir verboten hat." },
      { number: 24, text: "Denn Jahwe, dein Gott, ist ein verzehrendes Feuer, ein eifersüchtiger Gott*!", footnotes: ["eifersüchtiger Gott. Das meint: ein leidenschaftlich liebender Gott, der nicht hinnimmt, wenn man etwas anderes als ihn verehrt. Der Vers wird im Neuen Testament zitiert: Hebräer 12,29."] },
      { number: 25, text: "Und wenn du Kinder und Enkel hast und ihr im Land heimisch geworden seid und euch dann ein Gottesbild in irgendeiner Gestalt macht und tut, was vor Jahwe, deinem Gott, böse ist und ihn reizt," },
      { number: 26, text: "so rufe ich heute den Himmel und die Erde als Zeugen gegen euch auf: Dann werdet ihr schnell wieder aus dem Land beseitigt sein, in das ihr über den Jordan zieht, um es in Besitz zu nehmen. Dann werdet ihr nicht lange darin wohnen, sondern völlig daraus entfernt werden." },
      { number: 27, text: "Dann wird Jahwe euch unter die Völker zerstreuen, und nur eine geringe Zahl von euch wird unter den Nationen übrig bleiben, zu denen Jahwe euch dann führt." },
      { number: 28, text: "Dort werdet ihr Göttern dienen, die Machwerke von Menschenhand sind, Göttern aus Holz und Stein, die nicht sehen, hören, essen oder riechen können." },
      { number: 29, text: "Und von dort aus werdet ihr Jahwe, euren Gott, suchen. Du wirst ihn finden, wenn du von ganzem Herzen und ganzer Seele nach ihm fragst." },
      { number: 30, text: "Wenn du in Not bist und all dies dich trifft am Ende der Zeit, dann wirst du zu Jahwe, deinem Gott, umkehren und auf ihn hören." },
      { number: 31, text: "Denn Jahwe, dein Gott, ist ein barmherziger Gott. Er wird dich nicht fallen lassen und dem Verderben preisgeben. Er wird den Bund mit deinen Vorfahren nicht vergessen, den er ihnen geschworen hat." },
      { number: 32, text: "Frag doch nach den früheren Zeiten, die vor dir gewesen sind, von der Zeit an, als Gott den Menschen auf der Erde schuf; frag von einem Ende des Himmels bis zum anderen, ob je so große Dinge geschehen sind oder je dergleichen gehört worden ist.", heading: "Jahwe ist Gott" },
      { number: 33, text: "Hat je ein Volk die Stimme Gottes aus dem Feuer reden hören, wie du sie gehört hast, und ist am Leben geblieben?" },
      { number: 34, text: "Hat jemals ein Gott es unternommen, sich eine Nation mitten aus einer anderen herauszuholen durch Prüfungen, Zeichen, Wunder und Krieg, mit starker Hand und ausgestrecktem Arm, mit großen und furchtbaren Taten, wie Jahwe, euer Gott, es vor deinen Augen in Ägypten für euch getan hat?" },
      { number: 35, text: "Du hast es zu sehen bekommen, damit du erkennst, dass Jahwe Gott ist und sonst keiner." },
      { number: 36, text: "Vom Himmel her hat er dich seine Stimme hören lassen, um dich zurechtzuweisen; und auf der Erde hat er dich sein großes Feuer sehen lassen. Seine Worte hast du mitten aus dem Feuer gehört." },
      { number: 37, text: "Und weil er deine Vorfahren geliebt und ihre Nachkommen erwählt hat, führte er dich in eigener Person und mit großer Kraft aus Ägypten heraus," },
      { number: 38, text: "um Nationen, größer und stärker als du, vor dir zu vertreiben, um dich herkommen zu lassen und dir ihr Land als Eigentum zu geben, wie es heute der Fall ist." },
      { number: 39, text: "So begreif es heute endlich und nimm es dir zu Herzen, dass Jahwe oben im Himmel und unten auf der Erde allein Gott ist, keiner sonst!" },
      { number: 40, text: "Halte dich an seine Ordnungen und Gebote, auf die ich dich heute verpflichte, damit es dir und deinen Nachkommen gut geht und du lange lebst in dem Land, das Jahwe, dein Gott, dir für immer gibt." },
      { number: 41, text: "Damals sonderte Mose drei Städte im Ostjordanland aus,", heading: "Die Asylstädte im Ostjordanland" },
      { number: 42, text: "damit ein Totschläger, der seinen Nächsten ohne Vorsatz totgeschlagen hat, ohne ihn schon vorher zu hassen, dorthin fliehen kann. Er soll in einer dieser Städte sein Leben retten können." },
      { number: 43, text: "Es sind Bezer im Wüstengebiet der Hochebene für Ruben, Ramot in Gilead für Gad und Golan im Baschan für Manasse." },
      { number: 44, text: "Es folgt jetzt das Gesetz, das Mose den Israeliten vorlegte,", heading: "Einleitung zum Gesetz" },
      { number: 45, text: "die Weisungen, Vorschriften und Bestimmungen, die Mose den Israeliten vortrug," },
      { number: 46, text: "als sie nach ihrem Auszug aus Ägypten in der Tiefebene des Ostjordanlands, gegenüber von Bet-Peor, angekommen waren, im Land des Amoriterkönigs Sihon, der in Heschbon regierte und den Mose und die Israeliten besiegten." },
      { number: 47, text: "Nachdem sie sein Land in Besitz genommen hatten, eroberten sie auch das Land des Königs Og von Baschan, das waren die beiden Amoriterkönige, die im Ostjordanland herrschten. Sie eroberten das ganze Gebiet" },
      { number: 48, text: "von Aroer an, das am Rand des Arnontals liegt, bis an den Berg Sion, also den Hermon," },
      { number: 49, text: "die ganze Ebene des Ostjordanlandes bis ans Tote Meer unterhalb der Hänge des Pisga." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Mose rief ganz Israel zusammen und sagte: Höre, Israel, auf die Vorschriften und Bestimmungen, die ich euch heute verkünde! Lernt sie, bewahrt sie und tut sie!", heading: "5-11: Wiederholung der Grundgebote\nDie zehn Gebote" },
      { number: 2, text: "Jahwe, unser Gott, hat am Horeb einen Bund mit uns geschlossen." },
      { number: 3, text: "Er schloss diesen Bund nicht mit unseren Vätern, sondern mit uns, die wir heute und hier am Leben sind." },
      { number: 4, text: "Auf dem Berg hat Jahwe mitten aus dem Feuer direkt mit euch geredet." },
      { number: 5, text: "Ich stand damals zwischen Jahwe und euch, um euch seine Worte weiterzugeben, denn ihr habt euch vor Jahwe gefürchtet und seid nicht auf den Berg gestiegen. Er sagte:" },
      { number: 6, text: "\"Ich bin Jahwe, dein Gott! Ich habe dich aus dem Sklavenhaus Ägyptens befreit." },
      { number: 7, text: "Du wirst* keine anderen Götter vor mich stellen!", footnotes: ["wirst.Das heißt: \"Ich habe dich befreit, deshalb sollte es undenkbar für dich sein, das zu tun.\" Es meint aber auch ein unbedingtes Verbot."] },
      { number: 8, text: "Du wirst dir kein Götterbild machen, kein Abbild von irgendetwas im Himmel, auf der Erde oder im Meer!" },
      { number: 9, text: "Wirf dich niemals vor ihnen nieder und verehre sie auf keinen Fall! Denn ich, Jahwe, ich, dein Gott, bin ein eifersüchtiger Gott. Wer mich verachtet und beiseite stellt, bei dem verfolge ich die Schuld der Väter noch bis zur dritten und vierten Generation." },
      { number: 10, text: "Doch wer mich liebt und meine Gebote hält, dem schenke ich meine Gunst auf tausend Generationen hin." },
      { number: 11, text: "Du wirst den Namen Jahwes, deines Gottes, nie missbrauchen! Denn Jahwe wird jeden bestrafen, der seinen Namen mit Nichtigkeiten in Verbindung bringt." },
      { number: 12, text: "Achte auf den Sabbattag und reserviere ihn für Gott! Denn so hat Jahwe, dein Gott, es dir befohlen." },
      { number: 13, text: "Sechs Tage hast du, um all deine Arbeit zu tun," },
      { number: 14, text: "aber der siebte Tag ist Sabbat für Jahwe, deinen Gott. An diesem Tag sollst du nicht arbeiten, weder du, noch dein Sohn oder deine Tochter, weder dein Sklave noch deine Sklavin, nicht einmal dein Rind oder Esel oder dein Vieh oder der Fremde, der in deinem Ort wohnt. Auch dein Sklave und deine Sklavin sollen ruhen wie du!" },
      { number: 15, text: "Denk daran, dass du selbst Sklave in Ägypten warst und dass Jahwe, dein Gott, dich mit starker Hand und ausgestrecktem Arm von dort herausgeführt hat! Deshalb hat Jahwe, dein Gott, dir befohlen, den Sabbat zu feiern." },
      { number: 16, text: "Ehre deinen Vater und deine Mutter, wie Jahwe, dein Gott, es dir geboten hat! Dann wirst du lange in dem Land leben, das Jahwe, dein Gott, dir gibt." },
      { number: 17, text: "Morde nicht!" },
      { number: 18, text: "Brich die Ehe nicht!" },
      { number: 19, text: "Stiehl nicht!" },
      { number: 20, text: "Sag nichts Unwahres über deinen Mitmenschen!" },
      { number: 21, text: "Begehre nicht die Frau deines Mitmenschen! Begehre auch nicht sein Haus, sein Feld, seinen Sklaven oder seine Sklavin, sein Rind oder seinen Esel oder sonst etwas, das ihm gehört!\"" },
      { number: 22, text: "Diese Worte sagte Jahwe auf dem Berg zu eurer ganzen Versammlung aus dem Feuer, den Wolken und dem Dunkel heraus mit gewaltiger Stimme und nichts weiter. Er schrieb sie auf zwei Steintafeln und gab sie mir." },
      { number: 23, text: "Als ihr die Stimme aus der Finsternis hörtet, während ihr den Berg in Flammen saht, kamt ihr zu mir. Es waren eure Stammesoberen und eure Ältesten.", heading: "Mose zwischen Gott und dem Volk" },
      { number: 24, text: "Sie sagten: \"Jahwe, unser Gott, hat uns seine Herrlichkeit und Größe gezeigt. Wir haben seine Stimme aus dem Feuer gehört. Heute haben wir gesehen, dass Gott mit den Menschen reden kann, ohne dass sie sterben müssen." },
      { number: 25, text: "Aber warum sollen wir jetzt sterben? Dieses große Feuer wird uns vernichten. Wenn wir noch länger die Stimme Jahwes, unseres Gottes, hören, werden wir sterben." },
      { number: 26, text: "Welcher sterbliche Mensch hätte wie wir die Stimme des lebendigen Gottes aus dem Feuer gehört und wäre am Leben geblieben?" },
      { number: 27, text: "Geh du allein hin und höre, was Jahwe, unser Gott, uns sagt. Du sollst uns dann alles weitergeben, was Jahwe, unser Gott, dir sagt. Und wir wollen es hören und tun.\"" },
      { number: 28, text: "Jahwe hörte euer Geschrei, als ihr auf mich eingeredet habt, und sagte zu mir: \"Ich habe das Geschrei dieses Volkes gehört. Alles, was sie gesagt haben, ist gut." },
      { number: 29, text: "Mögen sie diese Gesinnung behalten, dass sie mich allezeit fürchten und meine Gebote halten, damit es ihnen und ihren Kindern immer gut geht!" },
      { number: 30, text: "Geh und sag ihnen: 'Kehrt in eure Zelte zurück!'" },
      { number: 31, text: "Du aber bleib hier bei mir stehen! Ich will dir das ganze Gebot verkünden, die Vorschriften und Bestimmungen, die du sie lehren sollst, damit sie danach handeln in dem Land, das ich ihnen zum Besitz gebe.\"" },
      { number: 32, text: "Achtet nun darauf, es so zu tun, wie Jahwe, euer Gott, es euch befohlen hat, und weicht nicht rechts oder links davon ab." },
      { number: 33, text: "Bleibt genau auf dem Weg, den er euch mit seinen Geboten gewiesen hat, damit ihr am Leben bleibt und es euch gut geht und ihr lange in dem Land lebt, das ihr in Besitz nehmt." },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Das ist das Gesetz mit seinen Vorschriften und Bestimmungen, die Jahwe, euer Gott, geboten hat, euch zu lehren, damit ihr danach handelt, wenn ihr das Land in Besitz genommen habt, in das ihr jetzt hinüberzieht,", heading: "Gott über alles lieben" },
      { number: 2, text: "und damit du Jahwe, deinen Gott, dein Leben lang fürchtest und alle seine Vorschriften und Bestimmungen, die ich dir heute anbefehle, hältst, du, deine Kinder und deine Enkel, und damit du lange lebst." },
      { number: 3, text: "Deshalb sollst du sie hören, Israel, sie halten und tun, damit es dir gut geht und ihr überaus zahlreich werdet in einem Land, das von Milch und Honig überfließt. So hat es Jahwe, der Gott deiner Vorfahren, dir gesagt." },
      { number: 4, text: "Höre Israel: Jahwe ist unser Gott, Jahwe allein*!", footnotes: ["allein. Das hebräische echad hat die Bedeutung von allein, einer, einzig, einzigartig. Es kann also auch heißen: \"Jahwe ist unser Gott, ein unteilbarer Jahwe\", oder: \"Jahwe, unser Gott, ist der einzige Jahwe\", oder: \"Jahwe ist unser Gott, Jahwe ist einzigartig.\""] },
      { number: 5, text: "Und du sollst Jahwe, deinen Gott, mit ganzem Herzen lieben, von ganzer Seele und ganzer Kraft.*", footnotes: ["Wird im Neuen Testament von Jesus Christus zitiert: Markus 12,29-30."] },
      { number: 6, text: "Und die Worte, die ich dir heute verkünde, sollen in deinem Herzen sein." },
      { number: 7, text: "Präge sie deinen Kindern ein und rede davon, ob du in deinem Haus bist oder unterwegs, ob du dich hinlegst oder aufstehst." },
      { number: 8, text: "Du sollst sie als Zeichen auf deine Hand binden und als Merkzeichen auf deiner Stirn tragen." },
      { number: 9, text: "Du sollst sie auf die Türpfosten deines Hauses schreiben und an deine Tore." },
      { number: 10, text: "Jahwe, dein Gott, bringt dich jetzt in das Land, wie er es deinen Vorfahren Abraham, Isaak und Jakob geschworen hat. Es sind große und schöne Städte, die du nicht gebaut hast," },
      { number: 11, text: "Häuser voller Güter, die du nicht erworben hast, Zisternen, die du nicht ausgehauen hast, Weinberge und Olivenhaine, die du nicht angelegt hast. Wenn du dann davon isst und satt wirst," },
      { number: 12, text: "dann hüte dich, Jahwe, deinen Gott, zu vergessen, der dich aus Ägypten, dem Sklavenhaus, geführt hat." },
      { number: 13, text: "Jahwe, deinen Gott, sollst du fürchten, ihm sollst du dienen* und bei seinem Namen sollst du schwören.", footnotes: ["Wird im Neuen Testament von Jesus Christus dem Satan gegenüber zitiert: Matthäus 4,10; Lukas 4,8."] },
      { number: 14, text: "Lauft nicht hinter den Göttern her, die die Völker um euch herum verehren," },
      { number: 15, text: "denn Jahwe, der Gott in deiner Mitte, ist ein eifersüchtiger Gott. Sein Zorn könnte gegen dich auflodern. Dann würde er dich vom Erdboden weg vernichten." },
      { number: 16, text: "Stellt Jahwe, euren Gott, nicht auf die Probe,* wie ihr es in Massa getan habt.*", footnotes: ["Wird im Neuen Testament von Jesus Christus dem Satan gegenüber zitiert: Matthäus 4,7; Lukas 4,12.", "in Massa getan habt. Siehe 2. Mose 17,1-7."] },
      { number: 17, text: "Die Gebote, die Jahwe, euer Gott, euch gegeben hat, sollt ihr unbedingt halten, und zwar alle Gesetze und Vorschriften." },
      { number: 18, text: "Du sollst das tun, was recht und gut vor Jahwe ist. Dann wird es dir gut gehen und du wirst das gute Land in Besitz nehmen, das Jahwe deinen Vorfahren unter Eid versprochen hat." },
      { number: 19, text: "Du wirst alle deine Feinde vertreiben, so wie Jahwe es gesagt hat." },
      { number: 20, text: "Wenn dich morgen dein Sohn fragt: \"Was sind das für Gesetze, Vorschriften und Rechte, die Jahwe, unser Gott, euch geboten hat?\"," },
      { number: 21, text: "dann sollst du deinem Sohn sagen: \"Sklaven waren wir, Sklaven des Pharao in Ägypten. Doch Jahwe hat uns mit starker Hand aus Ägypten herausgeführt." },
      { number: 22, text: "Er hat vor unseren Augen gewaltige Zeichen und Wunder getan und Unheil über die Ägypter gebracht, den Pharao und seine ganze Familie." },
      { number: 23, text: "Uns hat er von dort herausgeführt, um uns das Land zu geben, wie er es unseren Vorfahren geschworen hat." },
      { number: 24, text: "Jahwe befahl uns, all diese Vorschriften zu halten und ihn, unseren Gott, zu fürchten, damit es uns immer gut geht und er uns am Leben erhält, wie es heute der Fall ist." },
      { number: 25, text: "Wenn wir darauf achten, dieses ganze Gesetz vor Jahwe, unserem Gott, zu befolgen, wird das unsere Gerechtigkeit* sein.\"", footnotes: ["unsere Gerechtigkeit.Das heißt: Dann stimmt unser Verhältnis zu Gott, und auch unter uns wird es gerecht zugehen."] },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Wenn Jahwe, dein Gott, dich in das Land bringt, in das du jetzt ziehst, um es in Besitz zu nehmen, wenn er viele Völker vor dir vertreibt – die Hetiter, Girgaschiter, Amoriter, Kanaaniter, Perisiter, Hiwiter und Jebusiter, sieben Völker, die größer und stärker sind als du –,", heading: "Israel und die Kanaaniter" },
      { number: 2, text: "wenn Jahwe, dein Gott, sie dir ausliefert und du sie schlägst, musst du unbedingt den Bann* an ihnen vollstrecken. Du darfst sie nicht verschonen und keinen Bund mit ihnen schließen.", footnotes: ["Bann. Das bedeutete die vollständige Vernichtung von Menschen, Tieren und Gütern."] },
      { number: 3, text: "Du darfst dich auf keinen Fall mit ihnen verschwägern, dass du deine Tochter einem Mann von ihnen gibst oder eine ihrer Töchter für deinen Sohn nimmst." },
      { number: 4, text: "Denn sie würden deine Kinder verführen, sich von Jahwe abzuwenden und anderen Göttern zu dienen; dann würde Jahwe zornig über euch werden und euch schnell vernichten." },
      { number: 5, text: "Für euch gibt es nur eins: Reißt ihre Altäre nieder, zerschlagt ihre Steinmale, haut ihre Aschera-Pfähle* um und verbrennt ihre Götterbilder.", footnotes: ["Die Aschera war eine Fruchtbarkeitsgöttin, die in handlichen Figuren, geweihten Bäumen oder Pfählen verehrt wurde."] },
      { number: 6, text: "Denn du bist ein Volk, das ausschließlich Jahwe gehört. Jahwe, dein Gott, hat dich aus allen Völkern der Erde ausgewählt und zu seinem Eigentum gemacht." },
      { number: 7, text: "Jahwe war euch nicht deshalb zugeneigt, weil ihr größer als alle Völker wärt – ihr seid ja das kleinste unter ihnen –," },
      { number: 8, text: "sondern weil er euch liebte und den Eid halten wollte, den er euren Vätern geschworen hat. Nur deshalb hat er euch mit starker Hand aus dem Sklavenhaus geführt, aus der Gewalt des ägyptischen Pharao." },
      { number: 9, text: "Daran sollst du erkennen, dass Jahwe, dein Gott, allein der wahre Gott ist. Er steht zu seinem Wort und erweist seine Güte an denen, die ihn lieben und seine Gebote halten auf tausend Generationen hin." },
      { number: 10, text: "Doch die, die ihn hassen, bestraft er auf der Stelle und lässt sie umkommen. Bei einem, der ihn hasst, zögert er nicht; er vergilt es ihm direkt." },
      { number: 11, text: "Darum halte das Gesetz, seine Vorschriften und Bestimmungen, die ich dir heute gebe und handle danach!" },
      { number: 12, text: "Wenn ihr auf diese Rechtsbestimmungen hört, sie haltet und danach handelt, wird Jahwe, dein Gott, den Bund halten und dir seine Güte bewahren, wie er es deinen Vorfahren geschworen hat.", heading: "Gehorsam bringt Segen" },
      { number: 13, text: "Er wird dich lieben, dich segnen und dich zahlreich werden lassen. Er wird die Frucht deines Leibes segnen und die Frucht deines Bodens, dein Korn, deinen Wein, dein Öl, die Zucht deiner Rinder und den Nachwuchs deiner Schafe in dem Land, das er euch geben wird, wie er deinen Vorfahren geschworen hat." },
      { number: 14, text: "Mehr als alle Völker wirst du gesegnet sein. Niemand wird bei dir unfruchtbar sein, kein Mann, keine Frau und kein Vieh." },
      { number: 15, text: "Vor jeder Krankheit wird Jahwe dich schützen. Keine der bösen Seuchen der Ägypter wird er über dich kommen lassen, sondern wird sie über die bringen, die dich hassen." },
      { number: 16, text: "Du wirst alle Völker vernichten, die Jahwe, dein Gott, dir preisgibt. Ihr dürft kein Mitleid mit ihnen haben und ihren Göttern auf keinen Fall dienen. Denn das wäre eine Falle für dich." },
      { number: 17, text: "Wenn du denkst: \"Diese Völker sind größer als ich; wie könnte ich sie vertreiben?\"," },
      { number: 18, text: "dann fürchte dich nicht vor ihnen. Denk daran, was Jahwe, dein Gott, dem Pharao und allen Ägyptern angetan hat." },
      { number: 19, text: "Denk an die großen Prüfungen, die du mit eigenen Augen gesehen hast, an die Zeichen und Wunder, an die starke Hand und den ausgestreckten Arm, mit denen dich Jahwe, dein Gott, herausgeführt hat. Das wird Jahwe allen Völkern antun, vor denen du dich fürchtest." },
      { number: 20, text: "Panische Angst wird er über sie kommen lassen, bis auch die Übriggebliebenen vernichtet sind und die, die sich vor dir versteckt haben." },
      { number: 21, text: "Erschrick nicht vor ihnen, denn Jahwe, dein Gott, ist in deiner Mitte, ein großer und furchtbarer Gott." },
      { number: 22, text: "Er wird diese Nationen nach und nach vor dir vertreiben. Du sollst sie nicht schnell vernichten, sonst vermehren sich die wilden Tiere zu sehr und schaden dir." },
      { number: 23, text: "Jahwe, dein Gott, wird dir die Völker im Land preisgeben; er wird sie in große Bestürzung versetzen, bis sie vernichtet sind." },
      { number: 24, text: "Er wird ihre Könige in deine Hand geben, und du wirst jede Spur von ihnen auslöschen. Keiner wird vor dir standhalten. Du wirst sie alle vernichten." },
      { number: 25, text: "Die Standbilder ihrer Götter müsst ihr ins Feuer werfen! Lass dich nicht von dem Silber oder Gold verleiten, das an ihnen ist! Das würde dir zum Fallstrick werden, denn Jahwe, dein Gott, verabscheut das." },
      { number: 26, text: "Bringe keinen solchen Gräuel in dein Haus, sonst bist du genauso wie dieser der Vernichtung verfallen. Ekel und Abscheu sollst du davor haben, denn er ist dem Untergang geweiht." },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Das ganze Gesetz, das ich dir heute verkünde, sollt ihr halten und danach tun. Dann bleibt ihr am Leben, werdet zahlreich und nehmt das Land in Besitz, wie es Jahwe euren Vorfahren geschworen hat.", heading: "Ermahnung zur Dankbarkeit" },
      { number: 2, text: "Du sollst immer daran denken, wie Jahwe, dein Gott, dich diese vierzig Jahre lang in der Wüste umherziehen ließ, um dich demütig zu machen und dich auf die Probe zu stellen. Er wollte deine Gesinnung erkennen und sehen, ob du seine Gebote halten würdest oder nicht." },
      { number: 3, text: "Er demütigte dich und ließ dich hungern. Er gab dir das Manna zu essen, das du und deine Vorfahren nicht kannten, um dir zu zeigen, dass der Mensch nicht vom Brot allein lebt, sondern von allem, was aus dem Mund Jahwes kommt.*", footnotes: ["Wird im Neuen Testament von Jesus Christus dem Satan gegenüber zitiert: Matthäus 4,4; Lukas 4,4."] },
      { number: 4, text: "In diesen vierzig Jahren ist deine Kleidung nicht verschlissen und dein Fuß nicht geschwollen." },
      { number: 5, text: "Daran kannst du erkennen, dass Jahwe, dein Gott, dich erzieht wie ein Mann seinen Sohn." },
      { number: 6, text: "Achte darum auf seine Weisungen, bleib auf seinem Weg und hab Ehrfurcht vor ihm!" },
      { number: 7, text: "Denn Jahwe, dein Gott, bringt dich in ein gutes Land, ein Land mit Bächen, Quellen und Wasser, das im Tal und aus den Bergen strömt," },
      { number: 8, text: "ein Land mit Weizen und Gerste, mit Weinstöcken, Feigen- und Granatapfelbäumen, ein Land mit Ölbäumen und Honig," },
      { number: 9, text: "ein Land, in dem du dich nicht kümmerlich ernähren musst, in dem es dir an nichts fehlen wird, ein Land, dessen Steine Eisen sind und in dessen Bergen du Kupfer gewinnst." },
      { number: 10, text: "Wenn du dich dann satt essen kannst, sollst du Jahwe, deinen Gott, für das gute Land preisen, das er dir gab." },
      { number: 11, text: "Hüte dich, ihn zu vergessen und das, was ich dir heute verkünde, zu missachten: seine Gebote, Bestimmungen und Vorschriften." },
      { number: 12, text: "Wenn du dich satt isst und schöne Häuser baust und darin wohnst," },
      { number: 13, text: "wenn deine Rinder, Schafe und Ziegen sich vermehren, wenn dein Silber und Gold sich häuft und alles, was du hast, sich mehrt," },
      { number: 14, text: "dann könntest du übermütig werden und Jahwe, deinen Gott, vergessen. Er hat dich doch aus dem Sklavenhaus Ägyptens herausgeführt;" },
      { number: 15, text: "er ließ dich durch diese große und schreckliche Wüste gehen, wo es Brandnattern und Skorpione gibt, wo alles dürr und ohne Wasser ist, und er ließ dir Wasser aus dem harten Fels hervorquellen." },
      { number: 16, text: "Er gab dir in der Wüste Manna zu essen, das deine Vorfahren nicht kannten, um dich demütig zu machen und auf die Probe zu stellen und um dir am Ende Gutes zu tun." },
      { number: 17, text: "Dann sollst du nicht denken: Diesen Reichtum habe ich mir selbst zu verdanken, der Kraft meiner Hände." },
      { number: 18, text: "Denk vielmehr an Jahwe, deinen Gott, denn er gibt dir die Kraft, Vermögen zu schaffen, weil er den Bund hält, den er deinen Vorfahren geschworen hat, wie er es heute tut." },
      { number: 19, text: "Doch wenn du Jahwe, deinen Gott, vergisst, wenn du anderen Göttern nachläufst, vor ihnen niederfällst und sie verehrst, dann sage ich euch heute: Ihr werdet unweigerlich zugrunde gehen!" },
      { number: 20, text: "Wie die Völker, die Jahwe vor euch vernichtet, so werdet auch ihr umkommen, wenn ihr nicht auf die Stimme Jahwes, eures Gottes, hört." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Höre Israel! Du stehst im Begriff, den Jordan zu überschreiten, um dort Völker zu vertreiben, die größer und stärker sind als du, und um große, himmelhoch befestigte Städte in Besitz zu nehmen.", heading: "Warnung vor Überheblichkeit" },
      { number: 2, text: "Du kommst zu einem großen und hochgewachsenen Volk, den Anakitern, von denen du weißt und oft hast sagen hören: \"Mit den Anakitern nimmt es keiner auf!\"" },
      { number: 3, text: "Aber ihr werdet sehen, dass es Jahwe, dein Gott, ist, der vor dir hergeht wie ein verzehrendes Feuer. Er wird sie vernichten, er wird sie so vor dir demütigen, dass du sie leicht besiegen und auslöschen kannst, wie Jahwe es dir versprochen hat." },
      { number: 4, text: "Wenn Jahwe, dein Gott, sie vor dir verjagt, sollst du nicht denken, dass Jahwe dich wegen deiner Gerechtigkeit hierher gebracht hat, um dieses Land in Besitz zu nehmen. Nein, er vertreibt diese Völker wegen ihrer Gottlosigkeit vor dir." },
      { number: 5, text: "Nicht wegen deiner Gerechtigkeit und Aufrichtigkeit kannst du ihr Land in Besitz nehmen, sondern wegen der Bosheit dieser Völker vertreibt Jahwe, dein Gott, sie vor dir, um wahr zu machen, was er deinen Vorfahren Abraham, Isaak und Jakob geschworen hat." },
      { number: 6, text: "Du kannst leicht einsehen, dass Jahwe, dein Gott, dir dieses gute Land nicht wegen deiner Gerechtigkeit zum Besitz gibt, denn du bist ein stures Volk." },
      { number: 7, text: "Erinnere dich und vergiss es nie, wie du Jahwe, deinen Gott, in der Wüste erzürnt hast, als du aus Ägypten gezogen bist. Bis ihr hierher gekommen seid, habt ihr euch ständig Jahwe widersetzt.", heading: "Das goldene Kalb" },
      { number: 8, text: "Am Horeb habt ihr Jahwe so sehr herausgefordert, dass er euch im Zorn vernichten wollte." },
      { number: 9, text: "Als ich auf den Berg stieg, um die Steintafeln zu empfangen, die Tafeln des Bundes, den Jahwe mit euch geschlossen hatte, blieb ich 40 Tage und Nächte dort auf dem Berg, ohne etwas zu essen und zu trinken." },
      { number: 10, text: "Da gab mir Jahwe die beiden Steintafeln, beschrieben mit dem Finger Gottes. Auf ihnen standen alle Worte, die Jahwe am Tag der Zusammenkunft auf dem Berg aus dem Feuer heraus zu euch gesprochen hatte." },
      { number: 11, text: "Nach den vierzig Tagen und Nächten gab mir Jahwe die beiden Steintafeln, die Tafeln des Bundes," },
      { number: 12, text: "und sagte zu mir: \"Los, steig schnell hinunter, weg von hier! Dein Volk, das du aus Ägypten herausgeführt hast, hat Böses getan. Sie sind schnell von dem Weg abgewichen, den ich ihnen gewiesen habe. Sie haben sich ein Götzenbild gebaut.\"" },
      { number: 13, text: "Dann sagte Jahwe zu mir: \"Ich sehe nun, was für ein stures Volk das ist!" },
      { number: 14, text: "Halte mich nicht ab, sie zu vernichten und ihren Namen unter dem Himmel auszulöschen! Dafür will ich dich zu einem Volk machen, größer und stärker als sie.\"" },
      { number: 15, text: "Da stieg ich wieder herab vom Berg, der im Feuer brannte, und hielt die beiden Tafeln des Bundes in den Händen." },
      { number: 16, text: "Dann sah ich, was geschehen war. Ihr hattet gegen Jahwe, euren Gott, gesündigt. Ihr hattet euch ein Kalb als Götzenbild gebaut. Schnell wart ihr von dem Weg abgewichen, den Jahwe euch gewiesen hatte." },
      { number: 17, text: "Da schleuderte ich die beiden Tafeln zu Boden und zerschmetterte sie vor euren Augen." },
      { number: 18, text: "Und wie das erste Mal warf ich mich wegen eurer Sünden vierzig Tage und Nächte vor Jahwe nieder, ohne zu essen und zu trinken. Ihr hattet getan, was böse vor ihm war, und ihn schwer beleidigt." },
      { number: 19, text: "Denn ich hatte Angst vor dem glühenden Zorn Jahwes.* Er war so zornig über euch, dass er euch vernichten wollte. Aber Jahwe erhörte mich auch dieses Mal.", footnotes: ["Wird im Neuen Testament zitiert: Hebräer 12,21."] },
      { number: 20, text: "Auch über Aaron war er zornig und wollte ihn töten. Ich betete damals auch für ihn." },
      { number: 21, text: "Doch das Machwerk eurer Sünde, das Stierkalb, warf ich ins Feuer. Ich schlug es in Stücke und zermalmte es zu feinem Staub. Den streute ich in den Bach, der vom Berg herabfließt." },
      { number: 22, text: "Auch in Tabera*, in Massa und in Kibrot-Taawa* habt ihr Jahwe zornig gemacht.", footnotes: ["Tabera. Siehe 4. Mose 11,1-3.", "Kibrot-Hattawa. Siehe 4. Mose 11,4-34."] },
      { number: 23, text: "Und als Jahwe, euer Gott, in Kadesch-Barnea zu euch sagte: \"Zieht los und erobert das Land, das ich euch zugesagt habe!\", da habt ihr euch seinem Befehl widersetzt. Ihr habt ihm nicht vertraut und ihm nicht gehorcht." },
      { number: 24, text: "Seit ich euch kenne, habt ihr euch Jahwe widersetzt." },
      { number: 25, text: "Ich warf mich also vor Jahwe nieder und lag vierzig Tage und Nächte vor ihm. Denn Jahwe hatte gesagt, dass er euch vernichten wollte." },
      { number: 26, text: "Ich betete zu ihm und sagte: \"Herr, Jahwe! Vernichte dieses Volk doch nicht, dein Eigentum, das du mit deiner großen Macht befreit und aus Ägypten herausgeführt hast!" },
      { number: 27, text: "Denk an deine Diener Abraham, Isaak und Jakob! Achte nicht auf die Sturheit dieses Volkes, auf seine Gottlosigkeit und Sünde," },
      { number: 28, text: "damit man in dem Land, aus dem du uns herausgeführt hast, nicht sagt: 'Weil Jahwe sie nicht in das Land bringen konnte, das er ihnen versprochen hat, und weil er sie hasste, hat er sie hinausgeführt, um sie sterben zu lassen.'" },
      { number: 29, text: "Sie sind doch dein Volk und dein Eigentum, das du mit deiner großen Kraft und deinem ausgestreckten Arm herausgeführt hast!\"" },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Damals sagte Jahwe zu mir: \"Haue dir zwei Steintafeln zurecht wie die ersten und steig zu mir auf den Berg. Fertige auch eine hölzerne Lade an.", heading: "Die Erneuerung des Bundes" },
      { number: 2, text: "Dann werde ich auf die Tafeln die Worte schreiben, die auf den ersten Tafeln standen, die du zerbrochen hast; und dann legst du sie in die Lade.\"" },
      { number: 3, text: "Ich machte eine Lade aus Akazienholz und hieb die zwei Steintafeln zurecht. Dann stieg ich mit ihnen in der Hand auf den Berg." },
      { number: 4, text: "Er schrieb auf die Tafeln dasselbe wie das erste Mal, die zehn Worte, die Jahwe am Tag der Versammlung auf dem Berg aus dem Feuer heraus zu euch gesprochen hatte. Jahwe gab sie mir." },
      { number: 5, text: "Ich stieg wieder vom Berg herab und legte die Tafeln in die Lade, die ich gemacht hatte. Und da blieben sie nach dem Wort Jahwes." },
      { number: 6, text: "Die Israeliten zogen von Beerot-Bene-Jaakan* nach Moser*. Dort starb Aaron und dort wurde er auch begraben. Nachfolger im Priesterdienst wurde sein Sohn Eleasar.", footnotes: ["Beerot-Bene-Jaakan. Dieser Lagerplatz Israels ist geografisch unbekannt.", "Moser. Ort in der Nähe des Berges Hor oder sogar damit identisch."] },
      { number: 7, text: "Die Israeliten zogen weiter nach Gudgoda und von dort nach Jotbata*, wo es reichlich Wasser gab.", footnotes: ["Jotbata. Die geografische Lage der Orte ist unbekannt."] },
      { number: 8, text: "Damals sonderte Jahwe den Stamm Levi aus. Die Leviten sollten die Lade des Bundes mit Jahwe tragen, sie sollten ihm im Heiligtum dienen und die Israeliten in seinem Namen segnen. So ist es bis heute geblieben." },
      { number: 9, text: "Deshalb fiel Levi kein Anteil am Erbbesitz bei seinen Brüdern zu. Jahwe selbst ist sein Erbbesitz, so wie es Jahwe, dein Gott, ihm versprochen hat." },
      { number: 10, text: "Ich war vierzig Tage und Nächte auf dem Berg wie beim ersten Mal. Und Jahwe erhörte mich auch diesmal und beschloss, euch nicht zu vernichten." },
      { number: 11, text: "Er sagte zu mir: \"Geh jetzt und stell dich an die Spitze des Volkes, damit sie losziehen und das Land in Besitz nehmen, denn ich habe ihren Vorfahren geschworen, dass sie es bekommen.\"" },
      { number: 12, text: "Und nun, Israel, was fordert Jahwe, dein Gott, von dir? Er will nur, dass du Ehrfurcht vor ihm hast und auf seinen Wegen gehst, dass du ihn liebst und ihm mit Herz und Seele dienst", heading: "Was Gott will" },
      { number: 13, text: "und dass du nach seinen Geboten und Vorschriften lebst, was dir ja selbst zugutekommt." },
      { number: 14, text: "Schau doch! Jahwe, deinem Gott, gehört der Himmel und das ganze Universum, die Erde und alles, was darauf ist!" },
      { number: 15, text: "Doch nur deinen Vorfahren hat er sich zugewandt und sie so geliebt, dass er euch, ihre Nachkommen, aus allen Völkern auswählte, wie es heute der Fall ist." },
      { number: 16, text: "Deshalb sollt ihr eure Herzen beschneiden und nicht mehr so stur sein," },
      { number: 17, text: "denn Jahwe, euer Gott, ist der Gott aller Götter und der Herr aller Herren. Er ist der große, mächtige und furchtbare Gott, der keinen bevorzugt und keine Bestechung annimmt," },
      { number: 18, text: "der den Waisen und Witwen zu ihrem Recht verhilft und auch den Fremden liebt, dass er ihn mit Nahrung und Kleidung versorgt." },
      { number: 19, text: "Darum sollt auch ihr die Fremden lieben, denn in Ägypten seid ihr auch Fremde gewesen." },
      { number: 20, text: "Jahwe, deinen Gott, sollst du fürchten, an ihm festhalten und bei seinem Namen schwören." },
      { number: 21, text: "Er ist dein Ruhm und er ist dein Gott, der wegen dir diese großen und furchtbaren Dinge getan hat, die du mit eigenen Augen gesehen hast." },
      { number: 22, text: "Mit siebzig Personen* sind deine Vorfahren nach Ägypten gekommen, doch jetzt hat Jahwe, dein Gott, dich zahlreich wie die Sterne am Himmel gemacht.", footnotes: ["siebzig Personen.Siehe Fußnote zu 1. Mose 46,27."] },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Darum sollst du Jahwe, deinen Gott, lieben und dich dein Leben lang an seine Vorschriften, Ordnungen, Rechtsbestimmungen und Gebote halten.", heading: "Gott hat seine Macht gezeigt" },
      { number: 2, text: "Denkt daran, die ihr jetzt vor mir steht, dass ich nicht zu euren Nachkommen rede, die die Erziehung durch Jahwe, euren Gott, nicht kennen und seine Größe nicht erfahren haben, seine starke Hand und seinen ausgestreckten Arm," },
      { number: 3, text: "seine Zeichen und Taten. Sie wissen nicht, was er mit Pharao, dem König von Ägypten, und seinem ganzen Land getan hat;" },
      { number: 4, text: "was er mit dem Heer der Ägypter machte, mit ihren Pferden und Wagen, über die er das Wasser des Schilfmeers fluten ließ, als sie euch verfolgten. Jahwe richtete sie so zu Grunde, dass niemand mehr von ihnen zu sehen war." },
      { number: 5, text: "Sie wissen nicht, was er dann in der Wüste mit euch gemacht hat, bis ihr an diesen Ort gekommen seid." },
      { number: 6, text: "Sie wissen auch nicht, was er mit Datan und Abiram, den Söhnen von Eliab Ben-Ruben, machte: Wie die Erde ihr Maul aufriss und sie mitten im Volk samt ihren Familien, ihren Zelten und allem, was ihnen gehörte, verschlang." },
      { number: 7, text: "Ich rede mit euch, die mit ihren eigenen Augen die großen Taten Jahwes gesehen haben." },
      { number: 8, text: "Beachtet also alle Gebote, die ich euch jetzt gebe, damit ihr in der Lage seid, in das Land hineinzugehen und es in Besitz zu nehmen, wozu ihr jetzt den Jordan überquert;", heading: "Segen und Fluch" },
      { number: 9, text: "und damit ihr lange lebt in diesem Land, das von Milch und Honig überfließt. Es ist das Land, von dem Jahwe euren Vorfahren geschworen hat, es ihnen und ihren Nachkommen zu geben." },
      { number: 10, text: "Denn das Land, in das du jetzt kommst, um es in Besitz zu nehmen, ist nicht wie das Land Ägypten, aus dem ihr ausgezogen seid. Die Aussaat deines Samens hast du damals mühsam bewässern müssen wie einen Gemüsegarten." },
      { number: 11, text: "Nein, das Land, in das ihr jetzt kommt, ist ein Land mit Bergen und Tälern, das vom Regen bewässert wird," },
      { number: 12, text: "ein Land, auf das Jahwe, dein Gott, achtet, auf dem seine Augen ständig ruhen, vom Anfang bis zum Ende des Jahres." },
      { number: 13, text: "Wenn ihr also auf Jahwes Gebote hört, die ich euch heute weitergebe, dass ihr ihn, euren Gott, liebt und ihm mit Herz und Seele dient," },
      { number: 14, text: "dann gibt er eurem Land Regen zur richtigen Zeit im Herbst und im Frühjahr*, und du wirst dein Korn, deinen Most und dein Öl einbringen.", footnotes: ["Herbst ... Frühjahr. Wörtlich: Früh- und Spätregen. Der Frühregen fällt Ende Oktober/Anfang November, der Spätregen Ende März/Anfang April."] },
      { number: 15, text: "Er wird dem Vieh auf deinem Land Gras geben, und du wirst dich satt essen können." },
      { number: 16, text: "Aber nehmt euch in acht! Lasst euch nicht dazu verleiten, wegzugehen, dass ihr andere Götter verehrt und euch vor ihnen niederwerft!" },
      { number: 17, text: "Dann wird nämlich Jahwes Zorn über euch kommen. Er wird den Himmel verschließen, dass kein Regen mehr fällt. Dann bringt der Boden keinen Ertrag mehr, und ihr werdet bald aus dem Land, das Jahwe euch jetzt gibt, beseitigt sein." },
      { number: 18, text: "Nehmt diese Worte also in Herz und Seele auf, bindet sie als Zeichen auf eure Hand und tragt sie als Merkzeichen auf der Stirn." },
      { number: 19, text: "Präge sie deinen Kindern ein und rede davon, ob du in deinem Haus bist oder unterwegs, ob du dich hinlegst oder aufstehst." },
      { number: 20, text: "Du sollst sie auf die Türpfosten deines Hauses schreiben und an deine Tore," },
      { number: 21, text: "dann werdet ihr und eure Kinder lange leben in dem Land, das Jahwe euch gibt, solange der Himmel über der Erde steht. So hat er es euren Vorfahren geschworen." },
      { number: 22, text: "Denn wenn ihr dieses Gebot haltet, das ich euch gebe, wenn ihr danach handelt und Jahwe, euren Gott, liebt, auf allen seinen Wegen bleibt und an ihm festhaltet," },
      { number: 23, text: "dann wird Jahwe alle diese Völker vor euch vertreiben; ja, ihr werdet Völker vertreiben, die größer und stärker sind als ihr." },
      { number: 24, text: "Jeder Ort, auf den eure Fußsohle tritt, soll euch gehören: von der Wüste bis zum Libanon und vom großen Strom, dem Euphrat, bis ans Mittelmeer soll euer Gebiet reichen." },
      { number: 25, text: "Niemand wird vor euch standhalten können, denn Jahwe, euer Gott, wird Furcht und Schrecken vor euch über das ganze Land kommen lassen, das ihr betreten werdet, wie er es euch versprochen hat." },
      { number: 26, text: "Seht, ich lege euch heute den Segen vor und den Fluch:" },
      { number: 27, text: "den Segen, wenn ihr die Gebote Jahwes, eures Gottes, die ich euch heute verkünde, befolgt;" },
      { number: 28, text: "den Fluch, wenn ihr den Geboten Jahwes, eures Gottes, nicht gehorcht und den Weg verlasst, den ich euch weise, und euch anderen Göttern zuwendet, die ihr nicht kennt." },
      { number: 29, text: "Wenn Jahwe, dein Gott, dich dann in das Land bringt, das du jetzt in Besitz nehmen willst, dann sollst du den Segen auf dem Berg Garizim erteilen und den Fluch auf dem Berg Ebal.*", footnotes: ["Garizim ... Ebal. Der Berg Ebal ist 940 m hoch und liegt nördlich von Sichem(50 km nördlich von Jerusalem). Der Berg Garizim liegt südlich vom Ebal und ist 881 m hoch."] },
      { number: 30, text: "Das sind die beiden Berge auf der anderen Seite des Jordan, hinter dem Weg nach Westen in der Landschaft der Kanaaniter, die in der Araba* bei den Terebinthen More wohnen, gegenüber von Gilgal.", footnotes: ["Araba. Siehe Fußnote zu 5. Mose 1,1."] },
      { number: 31, text: "Denn ihr werdet den Jordan überschreiten und das Land in Besitz nehmen, das Jahwe, euer Gott, euch gibt. Ja, ihr werdet es in Besitz nehmen und darin wohnen." },
      { number: 32, text: "Haltet euch dann an alle Vorschriften und Bestimmungen, die ich euch heute vorlege!" },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Das sind die Vorschriften und Bestimmungen, die ihr halten und nach denen ihr handeln sollt in dem Land, das Jahwe, der Gott eurer Vorfahren, euch zum Besitz geben wird, solange ihr auf dem Erdboden lebt.", heading: "12-26: Das Gesetz für das neue Land\nGottes Gebote für das Leben im Land" },
      { number: 2, text: "Ihr sollt all die Stätten zerstören, wo die Nationen, die ihr vertreiben sollt, ihren Göttern gedient haben: auf den hohen Bergen, auf den Hügeln und unter jedem üppig belaubten Baum." },
      { number: 3, text: "Ihr sollt ihre Altäre abreißen, ihre Steinmale zerbrechen, ihre Aschera-Pfähle verbrennen und ihre Götterbilder zerstören. Nichts darf mehr an sie erinnern." },
      { number: 4, text: "Mit Jahwe, eurem Gott, sollt ihr es anders halten." },
      { number: 5, text: "Ihr sollt nur die Stätte aufsuchen, die Jahwe, euer Gott, aus euren Stämmen zu seiner Wohnung auswählen wird, um seinen Namen dort wohnen zu lassen. Dorthin sollt ihr kommen." },
      { number: 6, text: "Und dorthin sollt ihr eure Brand- und Schlachtopfer* bringen, eure Zehnten, eure Hebopfer, was ihr gelobt habt und was ihr freiwillig gebt, und die Erstgeburten von euren Rindern, Schafen und Ziegen.", footnotes: ["Schlachtopfer. Allgemeine Bezeichnung für jedes Opfer, bei dem ein Tier geschlachtet wurde. Beim Brandopfer wurde das geschlachtete Tier vollständig auf dem Altar verbrannt."] },
      { number: 7, text: "Dort, vor Jahwe, eurem Gott, sollt ihr das Opfermahl halten und euch mit euren Familien an allem freuen, was ihr durch den Segen Jahwes erworben habt." },
      { number: 8, text: "Ihr dürft es dann nicht mehr so tun, wie es heute hier geschieht: Jeder macht es, wie es ihm gefällt." },
      { number: 9, text: "Denn ihr seid bisher noch nicht zur Ruhe gekommen, zu dem Erbbesitz, den Jahwe, euer Gott, euch gibt." },
      { number: 10, text: "Wenn ihr aber den Jordan überschritten habt und in dem Land wohnt, das Jahwe, euer Gott, euch als Erbbesitz zuteilt, wenn er euch Ruhe verschafft hat vor allen Feinden ringsum und ihr sicher wohnt," },
      { number: 11, text: "dann sollt ihr alle eure Brand- und Schlachtopfer, eure Zehnten, eure Hebopfer und die auserlesenen Gaben, die ihr Jahwe feierlich versprochen habt, ausschließlich an den Ort bringen, den Jahwe, euer Gott, auswählen wird, um seinen Namen dort wohnen zu lassen." },
      { number: 12, text: "Dort, in der Gegenwart Jahwes, sollt ihr mit euren Söhnen und Töchtern zusammen fröhlich feiern, mit euren Sklaven und Sklavinnen und dem Leviten aus eurem Ort, denn er hat ja keinen Erbbesitz unter euch." },
      { number: 13, text: "Hüte dich, deine Brandopfer an irgendeinem Ort darzubringen, der dir gerade in die Augen fällt!" },
      { number: 14, text: "Nur an dem Ort, den Jahwe aus einem deiner Stämme auswählt, sollst du deine Brandopfer darbringen und alles tun, was ich dir vorschreibe." },
      { number: 15, text: "Doch kannst du in all deinen Ortschaften nach Herzenslust schlachten und Fleisch essen, so wie Jahwe, dein Gott, dich gesegnet hat. Der Unreine* darf genauso davon essen wie der Reine, so wie ihr es bei der Gazelle und beim Hirsch* tut.", footnotes: ["Unrein. Das ist in rituellem Sinn gemeint. Unrein war man z.B. durch Berührung eines Toten oder während der Menstruation.", "Gazelle und Hirsch waren reine Tiere, die zwar nicht geopfert, wohl aber gegessen werden durften."] },
      { number: 16, text: "Nur das Blut dürft ihr nicht essen. Ihr müsst es wie Wasser auf die Erde fließen lassen." },
      { number: 17, text: "Aber Folgendes darfst du nicht in deinen Ortschaften essen: den Zehnten von deinem Korn, deinem Most und deinem Öl; die Erstgeburten deiner Rinder, Schafe und Ziegen; etwas, das du als Gelübde geben willst; deine freiwilligen Gaben und dein Hebopfer." },
      { number: 18, text: "Das sollst du vor Jahwe, deinem Gott, an dem Ort essen, den Jahwe auswählen wird. Du sollst es zusammen mit deinen Söhnen und Töchtern tun, deinen Sklaven und Sklavinnen und dem Leviten, der an deinem Ort wohnt. Und du sollst dich vor Jahwe, deinem Gott, über alles freuen, was du mit deiner Hände Arbeit schaffen konntest." },
      { number: 19, text: "Hüte dich, den Leviten zu vergessen, solange du in deinem Land lebst." },
      { number: 20, text: "Wenn Jahwe, dein Gott, dein Gebiet erweitern wird, wie er es dir versprochen hat, und du gern Fleisch essen möchtest, dann kannst du das nach Herzenslust tun." },
      { number: 21, text: "Wenn der Ort, den Jahwe auswählen wird, um seinen Namen dort wohnen zu lassen, zu weit von dir entfernt ist, darfst du dort, wo du wohnst, von deinen Rindern, Schafen und Ziegen, die Jahwe dir gegeben hat, nach Herzenslust essen, so, wie ich es angewiesen habe." },
      { number: 22, text: "Unreine und Reine dürfen davon essen wie von Gazelle und Hirsch." },
      { number: 23, text: "Achte aber unbedingt darauf, kein Blut zu essen. Denn das Blut ist das Leben. Du darfst niemals Fleisch essen, in dem noch Leben ist." },
      { number: 24, text: "Lass das Blut auf die Erde fließen wie Wasser. Du darfst es nicht essen." },
      { number: 25, text: "Und zwar deshalb nicht, damit es dir und deinen Nachkommen gut geht, weil du tust, was vor Jahwe richtig ist." },
      { number: 26, text: "Was jedoch die heiligen Gaben betrifft und die, die du als Gelübde geben willst: Mit denen sollst du zu dem Ort kommen, den Jahwe auswählen wird." },
      { number: 27, text: "Auch deine Brandopfer, das Fleisch und das Blut, sollst du auf dem Altar Jahwes zurichten. Und bei deinen Schlachtopfern muss das Blut an den Altar Jahwes gegossen werden. Das Fleisch kannst du essen." },
      { number: 28, text: "Hab acht und höre auf alles, was ich dir gebiete, damit es dir und deinen Nachkommen für immer gut geht, weil du tust, was richtig vor Jahwe, deinem Gott, ist." },
      { number: 29, text: "Wenn Jahwe, dein Gott, die Völker vernichtet, in deren Gebiet du kommst, um sie zu vertreiben, und du ihren Besitz übernimmst, wenn du dich in ihrem Land niederlässt," },
      { number: 30, text: "dann hüte dich und lass dich ja nicht verführen, es ihnen nachzumachen, nachdem sie beseitigt sind; dass du ja nicht nach ihren Göttern fragst und sagst: \"Wie haben diese Völker ihren Göttern gedient? So will ich es auch machen!\"" },
      { number: 31, text: "Jahwe, deinem Gott, sollst du so etwas nicht antun. Denn alles, was Jahwe verabscheut und hasst, haben diese Völker für ihre Götter getan. Sogar ihre Söhne und Töchter haben sie für ihre Götter verbrannt." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Haltet euch genau an die Weisungen, die ich euch gebe! Du darfst nichts hinzufügen und nichts davon weglassen." },
      { number: 2, text: "Wenn ein Prophet oder ein Traumseher in deiner Mitte auftritt und dir ein Zeichen oder Wunder ankündigt", heading: "Falsche Propheten" },
      { number: 3, text: "und dabei sagt: \"Lass uns anderen Göttern folgen und ihnen dienen!\", Göttern, die du nicht kennst; und wenn das Zeichen oder das Wunder, das er dir genannt hat, eintrifft," },
      { number: 4, text: "dann sollst du nicht auf die Worte jenes Propheten hören oder auf den, der die Träume hat. Denn Jahwe, euer Gott, prüft euch, ob ihr ihn mit Herz und Seele liebt." },
      { number: 5, text: "Ihr sollt Jahwe, eurem Gott, folgen und Ehrfurcht vor ihm haben. Seine Gebote sollt ihr halten, seinen Weisungen gehorchen, ihm dienen und ihm treu sein." },
      { number: 6, text: "Jener Prophet oder Traumseher aber muss getötet werden. Denn er wollte euch zum Abfall von Jahwe, eurem Gott, verleiten, der euch aus Ägypten herausführte und aus dem Sklavenhaus erlöste. Er wollte dich von dem Weg abbringen, auf dem Jahwe, dein Gott, dir zu gehen befohlen hat. Du sollst das Böse aus deiner Mitte beseitigen." },
      { number: 7, text: "Wenn dich dein leiblicher Bruder, dein Sohn, deine Tochter, deine Frau in deinen Armen oder dein bester Freund verführen will und sagt: \"Komm, lass uns anderen Göttern dienen!\" – Göttern, die weder du noch deine Vorfahren gekannt haben,", heading: "Verführung zum Götzendienst" },
      { number: 8, text: "Göttern der Völker, die um euch her wohnen, mögen sie nah oder fern von euch sein, von einem Ende der Erde bis zum andern –," },
      { number: 9, text: "dann sollst du ihm nicht nachgeben und nicht auf ihn hören. Du sollst ihn nicht schonen, ihn nicht schützen und kein Mitleid mit ihm haben," },
      { number: 10, text: "sondern du musst ihn unbedingt umbringen. Du sollst als Erster Hand an ihn legen, um ihn zu töten, und danach das ganze Volk." },
      { number: 11, text: "Du musst ihn zu Tode steinigen, denn er hat versucht, dich von Jahwe, deinem Gott, abzubringen, der dich doch aus dem Sklavenhaus Ägyptens herausgeführt hat." },
      { number: 12, text: "Ganz Israel soll es hören, damit sie sich fürchten und nie mehr solch eine böse Sache in deiner Mitte tun." },
      { number: 13, text: "Wenn du aus einer deiner Städte, die Jahwe, dein Gott, dir zur Wohnung gibt, die Nachricht hörst," },
      { number: 14, text: "es sei ein übles Gesindel aus deiner Mitte hervorgegangen und habe die Einwohner der Stadt verführt und gesagt: \"Kommt, lasst uns anderen Göttern dienen!\" – Göttern, die ihr nicht gekannt habt –," },
      { number: 15, text: "dann sollst du das genau untersuchen, nachforschen und nachfragen. Und wenn sich der Bericht als wahr erweist, wenn es stimmt, dass diese Schandtat in deiner Mitte verübt worden ist," },
      { number: 16, text: "dann sollst du an den Einwohnern dieser Stadt den Bann vollstrecken, du sollst sie mit dem Schwert erschlagen, auch ihr Vieh." },
      { number: 17, text: "Sämtliche Beute sollst du mitten auf dem Platz aufhäufen und dann die Stadt und ihre ganze Beute anzünden. Sie soll als Ganzopfer für Jahwe, deinen Gott, völlig verbrennen und ewig ein Schutthaufen bleiben. Niemals darf sie wieder aufgebaut werden." },
      { number: 18, text: "Von dem Gebannten darf nicht das Geringste in deiner Hand hängen bleiben, damit Jahwe von seinem glühenden Zorn ablässt und dir Barmherzigkeit schenkt; dass er sich über dich erbarmt und dich zahlreich macht, wie er es deinen Vorfahren geschworen hat;" },
      { number: 19, text: "sofern du auf Jahwe, deinen Gott, hörst und alle seine Gebote hältst, die ich dir heute gebe, dass du tust, was vor Jahwe, deinem Gott, recht ist." },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Ihr seid Kinder Jahwes, eures Gottes. Ihr dürft euch also wegen eines Toten keine Schnittwunden beibringen und euch auch nicht über der Stirn kahl scheren.", heading: "Heidnische Trauerbräuche" },
      { number: 2, text: "Denn du bist Jahwe, deinem Gott, ein heiliges Volk. Dich hat Jahwe aus allen Völkern der Erde für sich als sein eigenes Volk erwählt." },
      { number: 3, text: "Du sollst nichts Abscheuliches essen.", heading: "Reine und unreine Speisen" },
      { number: 4, text: "Folgende Tiere dürft ihr essen: Rind, Schaf, Ziege," },
      { number: 5, text: "Hirsch, Gazelle, Damhirsch, Wildziege und alle Arten von Antilopen." },
      { number: 6, text: "Alle Tiere, die deutlich gespaltene Hufe haben und ihre Nahrung wiederkäuen, dürft ihr essen." },
      { number: 7, text: "Doch folgende, die bloß wiederkäuen oder bloß gespaltene Hufe haben, sollt ihr nicht essen: das Kamel, den Hasen* und den Klippdachs, denn sie käuen zwar wieder, haben aber keine deutlich gespaltenen Hufe. Sie sollen euch als unrein gelten.", footnotes: ["Hasen werden zoologisch nicht zu den rinderartigen Wiederkäuern gerechnet, trotzdem kauen sie einen Teil ihrer Nahrung zweimal. Neben ihrem üblichen Kot scheiden sie nämlich von einem Vlies umgebene vitaminreiche Kügelchen aus, sogenannte Caecotrophe. Diese werden sofort wieder aufgenommen und an einer bestimmten Stelle des Magens, der Cardiaregion, noch einmal verdaut."] },
      { number: 8, text: "Auch das Schwein soll euch als unrein gelten, denn es hat zwar gespaltene Hufe, ist aber kein Wiederkäuer. Ihr dürft nichts vom Fleisch solcher Tiere essen und sie auch nicht berühren, wenn sie verendet sind." },
      { number: 9, text: "Von den Wassertieren dürft ihr alles essen, was Flossen und Schuppen hat." },
      { number: 10, text: "Aber alles, was keine Flossen oder Schuppen hat, soll euch als unrein gelten." },
      { number: 11, text: "Alle reinen Vögel dürft ihr essen." },
      { number: 12, text: "Doch folgende sollt ihr nicht essen: den Gänsegeier, den Lämmergeier und den Mönchsgeier," },
      { number: 13, text: "den Milan, den Habicht und alle Arten von Raubvögeln," },
      { number: 14, text: "alle Arten von Raben," },
      { number: 15, text: "den Strauß, die Schwalbe, die Möwe und alle Arten von Falken," },
      { number: 16, text: "das Käuzchen, den Uhu und die Schleiereule," },
      { number: 17, text: "die Ohreule, den Aasgeier und die Fischeule," },
      { number: 18, text: "den Storch, alle Arten von Reihern, den Wiedehopf und die Fledermaus." },
      { number: 19, text: "Alles geflügelte Kleingetier* soll euch als unrein gelten. Es darf nicht gegessen werden.", footnotes: ["Kleingetier. Wörtlich: Gewimmel. Vermutlich sind hier die verbotenen Heuschreckenarten gemeint oder andere geflügelte Insekten."] },
      { number: 20, text: "Alles reine Geflügel dürft ihr essen." },
      { number: 21, text: "Verendete Tiere dürft ihr nicht essen. Du kannst sie dem Fremden an deinem Ort zum Essen überlassen oder sie einem Ausländer verkaufen, denn du bist Jahwe, deinem Gott, ein heiliges Volk. Du sollst ein Böckchen nicht in der Milch seiner Mutter kochen.*", footnotes: ["... kochen. Einen jungen Bock in der Milch der Mutter zu kochen, war ein heidnischer Ritus, denn die Milch wurde anschließend auf die Erde gegossen, um ihre Fruchtbarkeit zu garantieren."] },
      { number: 22, text: "Vom ganzen Ertrag deiner Saat sollst du den Zehnten geben, von dem, was Jahr für Jahr auf dem Feld wächst.", heading: "Der Zehnte" },
      { number: 23, text: "Bring ihn an den Ort, den Jahwe, dein Gott, erwählen wird, um seinen Namen dort wohnen zu lassen. Dort, vor ihm, sollst du von deinem Zehnten essen, von Getreide, Most und Öl, von den Erstgeborenen deiner Rinder, Schafe und Ziegen, damit du es lernst, zu aller Zeit Ehrfurcht vor Jahwe, deinem Gott, zu haben." },
      { number: 24, text: "Es ist möglich, dass der Ort, den Jahwe, dein Gott, erwählen wird, um seinen Namen dort wohnen zu lassen, zu weit für dich ist, sodass du deinen Zehnten nicht hinbringen kannst." },
      { number: 25, text: "Dann mach den zehnten Teil von dem, womit Jahwe dich gesegnet hat zu Geld. Nimm es mit und geh an den Ort, den Jahwe, dein Gott, erwählen wird." },
      { number: 26, text: "Kauf dort für das Geld alles, worauf du Lust hast: Rinder, Schafe, Wein, Bier und was du sonst noch magst. Genieße alles dort, in der Gegenwart Jahwes, und freue dich." },
      { number: 27, text: "Vergiss aber den Leviten nicht, der an deinem Ort wohnt, denn er hat keinen Erbbesitz neben dir." },
      { number: 28, text: "Am Ende jedes dritten Jahres sollst du den Zehnten deines Einkommens von jenem Jahr in deinem Ort niederlegen." },
      { number: 29, text: "Er ist für den Leviten bestimmt, der kein eigenes Land besitzt, und für den Fremden, die Waise und die Witwe, die in deinem Ort leben. Sie sollen sich davon satt essen, damit Jahwe, dein Gott, die Arbeit deiner Hände segnet." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Am Ende jedes siebten Jahres sollst du einen Schuldenerlass gewähren.", heading: "Das Jahr des Schuldenerlasses" },
      { number: 2, text: "Das soll folgendermaßen geschehen: Jeder Gläubiger soll seinem Schuldner die Rückzahlung erlassen. Er soll seinen Nächsten und Bruder nicht zur Bezahlung anhalten, sobald das Erlassjahr Jahwes ausgerufen ist." },
      { number: 3, text: "Einen Ausländer darfst du drängen. Aber was du deinem Bruder geliehen hast, sollst du ihm überlassen." },
      { number: 4, text: "Eigentlich sollte es gar keinen Armen bei dir geben, denn Jahwe wird dich reich segnen in dem Land, das er dir zum Erbbesitz gibt." },
      { number: 5, text: "Doch nur dann, wenn du wirklich auf Jahwe, deinen Gott, hörst, wenn du das Gesetz hältst, das ich dir heute gebe, und danach lebst," },
      { number: 6, text: "wird Jahwe, dein Gott, dich segnen, wie er es versprochen hat. Dann wirst du vielen Völkern leihen, brauchst aber selbst nichts zu borgen, du wirst über viele Völker herrschen, sie aber nicht über dich." },
      { number: 7, text: "Wenn aber in dem Land, das Jahwe, dein Gott, dir gibt, in irgendeiner Ortschaft einer deiner Brüder verarmt, dann sollst du dein Herz nicht hart werden lassen und deine Hand nicht vor ihm verschließen," },
      { number: 8, text: "sondern sie ihm großzügig öffnen und ihm leihen, so viel er braucht." },
      { number: 9, text: "Hüte dich davor, dass dir der böse Gedanke in den Sinn kommt: \"Bald kommt ja das siebte Jahr, das Erlassjahr!\", und du dann deinen armen Bruder unfreundlich ansiehst und ihm nichts gibst. Wenn er Jahwe gegen dich anruft, würde es dir zur Sünde werden." },
      { number: 10, text: "Gib ihm bereitwillig und sei nicht missmutig, wenn du ihm gibst. Denn dafür wird Jahwe, dein Gott, dich segnen in all deinem Tun und in allem, was du unternimmst." },
      { number: 11, text: "Die Armen werden niemals ganz aus deinem Land verschwinden. Darum befehle ich dir: Unterstütze deinen armen und bedürftigen Bruder in deinem Land!" },
      { number: 12, text: "Wenn dein Bruder, ein Hebräer oder eine Hebräerin, sich dir verkauft, dann soll er dir sechs Jahre lang dienen. Im siebten Jahr sollst du ihn als frei entlassen.", heading: "Die Freilassung von Sklaven" },
      { number: 13, text: "Und wenn du ihn freilässt, sollst du ihn nicht mit leeren Händen ziehen lassen." },
      { number: 14, text: "Von deinem Kleinvieh, deinem Korn und Wein sollst du ihm mitgeben, was er tragen kann. Du sollst ihm von dem geben, womit Jahwe, dein Gott, dich gesegnet hat." },
      { number: 15, text: "Denk daran, dass auch du Sklave in Ägypten warst und dass Jahwe, dein Gott, dich befreit hat. Darum gebe ich dir heute dieses Gebot." },
      { number: 16, text: "Wenn dein Sklave aber sagt, dass er nicht von dir weggehen will, weil er dich und deine Familie liebt, weil es ihm gut bei dir geht," },
      { number: 17, text: "dann sollst du eine Ahle durch sein Ohr in die Tür stechen. Dann wird er für immer dein Sklave sein. Auch deine Sklavin sollst du so behandeln." },
      { number: 18, text: "Es soll dir nicht schwerfallen, wenn du ihn freilassen musst. Denn er hat dir sechs Jahre lang doppelt so viel wie ein Tagelöhner eingebracht. Und Jahwe, dein Gott, wird dich segnen in allem, was du tust." },
      { number: 19, text: "Jede männliche Erstgeburt von deinen Rindern, Schafen und Ziegen sollst du Jahwe, deinem Gott, weihen. Mit dem Erstgeborenen deines Rindes sollst du nicht arbeiten und das Erstgeborene von Schaf oder Ziege nicht scheren.", heading: "Die Heiligung der Erstgeburt" },
      { number: 20, text: "Vor Jahwe, deinem Gott, sollst du sie verzehren, du und deine Familie, und zwar jedes Jahr an dem Ort, den Jahwe auswählen wird." },
      { number: 21, text: "Wenn das Tier jedoch ein Gebrechen hat, dass es lahm oder blind ist oder sonst einen Makel aufweist, darfst du es Jahwe, deinem Gott, nicht opfern." },
      { number: 22, text: "Du kannst es wie eine Gazelle oder einen Hirsch an deinem Ort verzehren, ob du rein oder unrein bist." },
      { number: 23, text: "Nur sein Blut darfst du nicht essen. Du musst es wie Wasser auf die Erde fließen lassen." },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Beachte den Ährenmonat* und feiere das Passa* für Jahwe, deinen Gott. Denn im Ährenmonat hat Jahwe, dein Gott, dich nachts aus Ägypten herausgeführt.", heading: "Das Passafest", footnotes: ["Ährenmonat. Hebräisch: Abib. Entspricht dem April.", "Passa. Siehe 2. Mose 12-13."] },
      { number: 2, text: "Komm an den Ort, den Jahwe auswählen wird, um seinen Namen dort wohnen zu lassen. Dort sollst du für Jahwe, deinen Gott, das Passaopfer schlachten: ein Schaf, eine Ziege oder ein Rind." },
      { number: 3, text: "Du darfst aber kein Brot dazu essen, das mit Sauerteig zubereitet wurde. Sieben Tage lang sollst du ungesäuerte Brotfladen essen, Brot des Elends, – denn in angstvoller Eile bist du aus dem Land Ägypten ausgezogen – damit du dein Leben lang an den Tag deines Auszugs aus Ägypten denkst." },
      { number: 4, text: "Sieben Tage lang soll nichts, was mit Sauerteig zubereitet wurde, bei euch und in eurem ganzen Wohngebiet gesehen werden! Auch von dem Fleisch, das du am Abend des ersten Tages schlachtest, soll nichts bis zum nächsten Morgen übrig bleiben." },
      { number: 5, text: "Du darfst das Passaopfer nicht an irgendeinem deiner Orte schlachten, die Jahwe, dein Gott, dir gibt." },
      { number: 6, text: "Sondern an dem Ort, den Jahwe, dein Gott, auswählen wird, um seinen Namen dort wohnen zu lassen, dort sollst du das Passaopfer schlachten. Das soll am Abend geschehen, beim Untergang der Sonne, zur Zeit deines Auszugs aus Ägypten." },
      { number: 7, text: "Bereite das Fleisch zu und iss es an dem Ort, den Jahwe, dein Gott, auswählen wird. Am nächsten Morgen kannst du nach Hause reisen." },
      { number: 8, text: "Sechs Tage sollst du ungesäuerte Brotfladen essen. Am siebten Tag ist eine Festversammlung für Jahwe, deinen Gott. Da darfst du keinerlei Arbeit verrichten." },
      { number: 9, text: "Sieben Wochen sollst du vom Beginn der Getreideernte an abzählen.", heading: "Das Wochenfest" },
      { number: 10, text: "Dann sollst du für Jahwe, deinen Gott, das Fest der Wochen feiern. Dabei bringst du ihm eine freiwillige Gabe mit, je nachdem, wie Jahwe, dein Gott, dich gesegnet hat." },
      { number: 11, text: "Vor Jahwe, deinem Gott, sollst du mit deinen Söhnen und Töchtern zusammen fröhlich feiern, mit deinen Sklaven und Sklavinnen, dem Leviten, dem Fremden, der Waise und der Witwe in deinem Wohnort. Das soll an dem Ort geschehen, den Jahwe auswählen wird, um seinen Namen dort wohnen zu lassen." },
      { number: 12, text: "Denk daran, dass du Sklave in Ägypten warst, richte dich nach diesen Weisungen und halte sie ein." },
      { number: 13, text: "Das Laubhüttenfest sollst du sieben Tage lang feiern, wenn Getreideernte und Weinlese beendet sind.", heading: "Das Laubhüttenfest" },
      { number: 14, text: "Als Freudenfest sollst du es begehen mit deinen Söhnen und Töchtern, deinen Sklaven und Sklavinnen, dem Leviten, dem Fremden, der Waise und der Witwe in deinem Wohnort." },
      { number: 15, text: "Sieben Tage lang sollst du Jahwe, deinem Gott, das Fest feiern und zwar an dem Ort, den Jahwe auswählen wird. Denn Jahwe, dein Gott, wird dich segnen in allem Ertrag und der Arbeit deiner Hände, sodass du dich der Freude überlassen kannst." },
      { number: 16, text: "Dreimal im Jahr soll alles, was männlich ist, vor Jahwe, deinem Gott, erscheinen an dem Ort, den Jahwe auswählen wird: am Fest der ungesäuerten Brote, am Wochenfest und am Laubhüttenfest. Aber man soll nicht mit leeren Händen vor Jahwe erscheinen." },
      { number: 17, text: "Jeder bringe das mit, was er geben kann, je nachdem, wie Jahwe ihn gesegnet hat." },
      { number: 18, text: "In allen deinen Ortschaften in jedem deiner Stämme sollst du Richter und Aufseher einsetzen. Sie sollen dem Volk mit gerechtem Urteil Recht sprechen.", heading: "Richter und Aufseher" },
      { number: 19, text: "Du sollst das Recht nicht beugen, die Person nicht ansehen und kein Bestechungsgeschenk annehmen, denn Bestechung macht weise Leute blind und verdreht die Worte der Gerechten." },
      { number: 20, text: "Du sollst der Gerechtigkeit und nur der Gerechtigkeit folgen, damit du am Leben bleibst und das Land in Besitz nimmst, das Jahwe, dein Gott, dir gibt." },
      { number: 21, text: "Neben den Altar Jahwes, deines Gottes, den du dir errichten wirst, darfst du keinen Aschera-Pfahl aufstellen und auch keinen Baum pflanzen.", heading: "Reinheit des Gottesdienstes" },
      { number: 22, text: "Du darfst dir keine Gedenksteine aufrichten, denn Jahwe, dein Gott, hasst das." },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Du sollst Jahwe, deinem Gott, kein Rind oder Schaf opfern, an dem ein Makel ist, irgendetwas Schlimmes, denn das verabscheut er." },
      { number: 2, text: "Wenn sich in einer deiner Ortschaften, die Jahwe, dein Gott, dir gibt, jemand findet, ein Mann oder eine Frau, die etwas tun, was Jahwe, dein Gott, als böse ansieht, wenn jemand seinen Bund übertritt", heading: "Verfahren bei Götzendienst" },
      { number: 3, text: "und anfängt, andere Götter zu verehren und sich vor ihnen niederzuwerfen: vor der Sonne, dem Mond oder dem ganzen Heer der Sterne, was ich verboten habe," },
      { number: 4, text: "und es wird dir berichtet und du hörst davon, dann sollst du das genau untersuchen. Und wenn sich der Bericht als wahr erweist, wenn es stimmt, dass diese Schandtat in Israel verübt worden ist," },
      { number: 5, text: "dann sollst du jenen Mann oder jene Frau, die diese böse Sache getan haben, aus deinem Ort hinausführen und zu Tode steinigen." },
      { number: 6, text: "Aufgrund der Aussage von zwei oder drei Zeugen muss sterben, wer den Tod verdient. Er darf aber nicht auf die Aussage eines einzelnen Zeugen hin getötet werden." },
      { number: 7, text: "Die Zeugen müssen zuerst Hand an ihn legen, um ihn zu töten, danach das versammelte Volk. Du musst das Böse aus deiner Mitte entfernen." },
      { number: 8, text: "Wenn dir an deinem Ort ein Rechtsstreit zu schwierig ist, bei dem es um Mord und Totschlag, um Hab und Gut oder um Körperverletzung geht, dann mach dich zu dem Ort auf, den Jahwe, dein Gott, auswählen wird.", heading: "Das oberste Gericht" },
      { number: 9, text: "Dort sollst du zu den Priestern aus dem Stamm Levi gehen oder zu dem Richter, der gerade im Amt ist, und sie fragen. Dann werden sie dir sagen, wie das Urteil lautet." },
      { number: 10, text: "Du musst dich aber an ihren Spruch halten, den sie dir an dem Ort, den Jahwe auswählen wird, verkünden. Beachte genau, was sie dich lehren, und mach es so." },
      { number: 11, text: "An die Weisung, die sie dir geben, und an das Recht, das sie dir verkünden, musst du dich halten. Du darfst in keiner Hinsicht von ihrem Urteil abweichen." },
      { number: 12, text: "Wer so vermessen ist, dass er weder auf den Priester, der Jahwe, deinem Gott, dient, noch auf den Richter hört, der muss sterben. Du musst das Böse aus Israel entfernen." },
      { number: 13, text: "Das ganze Volk soll davon hören, damit alle sich fürchten und nicht wieder hochmütig sind." },
      { number: 14, text: "Wenn du in das Land kommst, das Jahwe, dein Gott, dir gibt, wenn du es in Besitz genommen und dich darin niedergelassen hast, wenn du dann auf die Idee kommst, einen König haben zu wollen wie alle anderen Völker ringsum,", heading: "Das Königsgesetz" },
      { number: 15, text: "dann sollst du nur den König über dich setzen, den Jahwe, dein Gott, auswählt. Es muss einer von deinen Brüdern sein. Einen Ausländer darfst du nicht zum König über dich setzen." },
      { number: 16, text: "Der König soll sich nicht zu viele Pferde halten, und das Volk nicht wieder nach Ägypten führen*, um viele Pferde anzuschaffen, denn Jahwe hat euch gesagt, ihr sollt diesen Weg niemals wieder betreten.", footnotes: ["nach Ägypten führen. Möglicherweise sollte hier eine Sendung von Söldnern im Austausch gegen Pferde verboten werden."] },
      { number: 17, text: "Der König soll sich auch nicht viele Frauen nehmen, damit er nicht auf Abwege gerät. Er soll sich auch nicht zu viel Gold und Silber anhäufen." },
      { number: 18, text: "Und wenn er dann auf dem Königsthron sitzt, soll er sich eine Abschrift von diesem Gesetz, das bei den Priestern und Leviten liegt, anfertigen." },
      { number: 19, text: "Diese Schriftrolle soll er stets bei sich haben und sein Leben lang täglich darin lesen, damit er es lernt, Jahwe, seinen Gott, zu fürchten, um alle Worte dieses Gesetzes und seiner Vorschriften genau einzuhalten." },
      { number: 20, text: "Das wird ihn davor bewahren, sich über seine Brüder zu erheben oder sich in irgendeiner Weise über das Gebot hinwegzusetzen. Und dann wird er mitten in Israel lange König bleiben und seine Söhne ebenso." },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Die levitischen Priester und der ganze Stamm Levi sollen keinen Teil und keinen Erbbesitz unter den Israeliten erhalten. Von den Feueropfern Jahwes und den Abgaben für ihn sollen sie ihren Unterhalt bekommen.", heading: "Die Einkünfte der Priester" },
      { number: 2, text: "Ein Levit soll keinen Erbbesitz unter seinen Brüdern haben. Jahwe ist sein Erbbesitz, wie er es ihm versprochen hat." },
      { number: 3, text: "Auf dies aber hat ein Priester Anrecht beim Volk: Wenn jemand ein Rind oder ein Schaf als Schlachtopfer bringt, gehören dem Priester das Schulterstück, die Kinnbacken und der Magen." },
      { number: 4, text: "Weiter sollst du ihm die ersten Erträge von deinem Getreide, deinem Most und deinem Öl geben und die erste Schur deiner Schafe." },
      { number: 5, text: "Denn Jahwe, dein Gott, hat ihn aus allen deinen Stämmen ausgewählt, dass er und seine Nachkommen im Namen Jahwes ihren Dienst verrichten, und zwar für immer." },
      { number: 6, text: "Ein Levit, der sich in irgendeiner Ortschaft in Israel aufhält, kann nach eigenem Belieben an die Stätte kommen, die Jahwe auswählen wird," },
      { number: 7, text: "und im Namen Jahwes, seines Gottes, Dienst tun wie alle seine levitischen Brüder, die dort vor Jahwe stehen." },
      { number: 8, text: "Er soll die gleiche Zuteilung wie sie erhalten, unabhängig vom Verkaufserlös seines Familienbesitzes." },
      { number: 9, text: "Wenn du in das Land kommst, das Jahwe, dein Gott, dir gibt, dann versuche ja nicht, so abscheuliche Dinge zu tun wie seine Bewohner.", heading: "Zauberei und Wahrsagerei" },
      { number: 10, text: "Bei dir soll keiner gefunden werden, der seinen Sohn oder seine Tochter durchs Feuer gehen* lässt, keiner, der wahrsagt, kein Zauberer, Beschwörer oder Magier,", footnotes: ["durchs Feuer gehen. Das heißt, Kinder für die Götzen lebendig verbrennen."] },
      { number: 11, text: "kein Bannsprecher oder Totenbeschwörer und keiner, der einen Totengeist oder Wahrsager befragt." },
      { number: 12, text: "Denn Jahwe verabscheut jeden, der so etwas tut. Und wegen dieser Abscheulichkeiten vertreibt Jahwe, dein Gott, sie vor dir." },
      { number: 13, text: "Du sollst dich ungeteilt an Jahwe, deinen Gott, halten." },
      { number: 14, text: "Denn diese Völker, die du vertreiben wirst, hören auf Zauberer und Wahrsager. Dir aber hat Jahwe, dein Gott, das nicht erlaubt." },
      { number: 15, text: "Einen Propheten wird Jahwe, dein Gott, aus deiner Mitte, aus deinen Brüdern, für dich erstehen lassen so wie mich. Auf ihn sollt ihr hören.*", heading: "Wahre und falsche Propheten", footnotes: ["Wird im Neuen Testament von Petrus zitiert: Apostelgeschichte 3,22."] },
      { number: 16, text: "So hast du es von Jahwe, deinem Gott, am Tag der Zusammenkunft erbeten: \"Ich möchte die Stimme Jahwes, meines Gottes, nicht mehr hören und dieses große Feuer nicht länger sehen, damit ich nicht sterben muss.\"" },
      { number: 17, text: "Da sagte Jahwe zu mir: \"Was sie gesagt haben, ist gut." },
      { number: 18, text: "Einen Propheten werde ich ihnen aus der Mitte ihrer Brüder erstehen lassen so wie dich. Durch seinen Mund werde ich zu ihnen sprechen. Er wird euch alles verkünden, was ich ihm befehle." },
      { number: 19, text: "Wer nicht befolgt, was ich durch ihn sage, den ziehe ich dafür zur Rechenschaft." },
      { number: 20, text: "Doch der Prophet, der sich anmaßt, etwas in meinem Namen zu verkünden, das ich ihm nicht aufgetragen habe, oder der im Namen anderer Götter spricht, dieser Prophet muss sterben." },
      { number: 21, text: "Wenn du aber denkst: 'Woran soll ich erkennen, welches Wort nicht von Jahwe kommt?' –" },
      { number: 22, text: "Wenn der Prophet etwas im Namen Jahwes sagt, das sich nicht erfüllt und nicht eintrifft, dann hat Jahwe nicht durch ihn gesprochen. Der Prophet hat es sich angemaßt. Du brauchst dich vor ihm nicht zu fürchten.\"" },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Wenn Jahwe, dein Gott, die Völker beseitigt, deren Land er dir geben wird, wenn du ihren Besitz übernimmst und dich in ihren Städten und Häusern niederlässt,", heading: "Die Asylstädte für Totschläger" },
      { number: 2, text: "dann sollst du drei von diesen Städten auswählen." },
      { number: 3, text: "Achte darauf, dass sie gleichmäßig über das Land verteilt sind, das Jahwe, dein Gott, dir gibt, und teile das Land dazu in drei Bezirke ein. Jeder, der zum Mörder geworden ist, soll dorthin fliehen können." },
      { number: 4, text: "Gemeint ist einer, der unabsichtlich zum Mörder wurde und seinen Nächsten nicht schon vorher hasste." },
      { number: 5, text: "Es kann zum Beispiel vorkommen, dass einer mit seinem Nachbarn in den Wald geht, um Holz zu schlagen. Da löst sich, während er mit der Axt ausholt, das Eisen vom Stiel und trifft den anderen tödlich. In diesem Fall kann der Totschläger in eine dieser Städte fliehen, um sein Leben zu retten." },
      { number: 6, text: "Der Weg dorthin darf nicht zu weit sein, damit der Bluträcher, der den Totschläger wutentbrannt verfolgt, ihn nicht einholen kann und ihn erschlägt, obwohl dieser den Tod nicht verdient, weil er die getötete Person ja nicht hasste." },
      { number: 7, text: "Darum befehle ich dir, zunächst drei Städte auszusondern." },
      { number: 8, text: "Wenn Jahwe, dein Gott, dein Gebiet erweitern wird, wie er es deinen Vorfahren geschworen hat, und dir das ganze Land gibt, das er ihnen versprochen hat –" },
      { number: 9, text: "vorausgesetzt, du hältst all diese Gebote, die ich dir heute gebe und handelst danach, indem du Jahwe, deinen Gott, liebst und allezeit auf seinen Wegen gehst –, dann sollst du noch drei weitere Asylstädte auswählen." },
      { number: 10, text: "So sollst du dafür sorgen, dass in dem Land, das Jahwe, dein Gott, dir gibt, kein unschuldiges Blut vergossen wird und keine Blutschuld auf dich kommt." },
      { number: 11, text: "Wenn aber jemand seinen Nächsten hasst, ihm auflauert, ihn überfällt und erschlägt und dann in eine dieser Städte flieht," },
      { number: 12, text: "dann müssen die Ältesten seiner Heimatstadt ihn von dort holen lassen und dem Bluträcher ausliefern." },
      { number: 13, text: "Du darfst kein Mitleid mit ihm haben. Du musst Israel vom Blut des Unschuldigen befreien, damit es dir gut geht." },
      { number: 14, text: "Wenn du das Land in Besitz genommen hast, das Jahwe, dein Gott, dir gibt, und du auf deinem Grundstück lebst, darfst du die Grenze zu deinem Nächsten, die die Vorfahren gezogen haben, nicht verändern.", heading: "Schutz der Grundstücksgrenzen" },
      { number: 15, text: "Die Aussage eines einzelnen Zeugen darf nicht ausschlaggebend sein, wenn es um ein Verbrechen, eine Sünde oder irgendeine Verfehlung geht. Auf die Aussage von zwei oder drei Zeugen hin soll eine Entscheidung getroffen werden.*", heading: "Zeugen vor Gericht", footnotes: ["Wird im Neuen Testament von Jesus und Paulus zitiert: Matthäus 18,16; 2. Korinther 13,1."] },
      { number: 16, text: "Wenn ein falscher Zeuge gegen jemand auftritt, um ihn einer Übertretung zu beschuldigen," },
      { number: 17, text: "dann sollen die beiden Männer, zwischen denen der Streit besteht, vor Jahwe treten, vor die Priester und die Richter, die zu jener Zeit da sein werden." },
      { number: 18, text: "Die Richter sollen den Fall genau untersuchen. Wenn der Zeuge wissentlich falsch gegen seinen Bruder ausgesagt hat," },
      { number: 19, text: "dann sollst du ihm antun, was er seinem Bruder zu tun gedachte. Du sollst das Böse aus deiner Mitte entfernen." },
      { number: 20, text: "Die Übrigen sollen es hören, damit sie sich fürchten und nie mehr solch eine böse Sache in deiner Mitte tun." },
      { number: 21, text: "Da sollst du kein Mitleid kennen: Leben für Leben, Auge für Auge, Zahn für Zahn, Hand für Hand, Fuß für Fuß." },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Wenn du gegen deine Feinde in den Krieg ziehst, die mit Pferden und Streitwagen ausgerüstet und zahlreicher sind als du, dann fürchte dich nicht vor ihnen, denn Jahwe, dein Gott, der dich aus Ägypten herausgeführt hat, ist mit dir.", heading: "Kriegsgesetze" },
      { number: 2, text: "Wenn ihr zum Kampf ausrückt, soll der Priester herzutreten und zum Volk sprechen." },
      { number: 3, text: "Er soll sagen: \"Höre, Israel! Ihr rückt heute zum Kampf gegen eure Feinde aus. Verliert nicht den Mut, fürchtet euch nicht, habt keine Angst und erschreckt nicht vor ihnen!" },
      { number: 4, text: "Denn es ist Jahwe, euer Gott, der mit euch zieht, um selbst gegen eure Feinde zu kämpfen und euch zu retten.\"" },
      { number: 5, text: "Anschließend sollen die Oberen zum Volk sprechen. Sie sollen sagen: \"Ist jemand hier, der ein neues Haus gebaut und noch nicht eingeweiht hat? Der kehre in sein Haus zurück, damit er nicht in der Schlacht stirbt und ein anderer sein Haus einweiht." },
      { number: 6, text: "Ist jemand da, der einen neuen Weinberg angelegt und noch nicht davon geerntet hat? Er kehre in sein Haus zurück, damit er nicht in der Schlacht stirbt und ein anderer die erste Lese* hält.", footnotes: ["erste Lese. Das konnte erst vier Jahre nach der ersten Anpflanzung geschehen(3. Mose 19,23-25)."] },
      { number: 7, text: "Ist jemand hier, der sich verlobt*, aber noch nicht geheiratet hat? Er kehre in sein Haus zurück, damit er nicht in der Schlacht stirbt und ein anderer seine Braut bekommt.\"", footnotes: ["verlobt. Er galt rechtlich bereits als verheiratet, obwohl er noch nicht mit seiner Frau zusammenlebte."] },
      { number: 8, text: "Und weiter sollen die Oberen zum Volk sagen: \"Ist jemand da, der sich fürchtet, der den Mut verloren hat? Er kehre in sein Haus zurück, damit er seinen Brüdern nicht auch noch den Mut nimmt.\"" },
      { number: 9, text: "Wenn die Oberen das alles gesagt haben, soll man Heerführer an die Spitze des Volkes stellen." },
      { number: 10, text: "Wenn du vor eine Stadt ziehst, um gegen sie zu kämpfen, sollst du ihr zunächst Frieden anbieten." },
      { number: 11, text: "Geht sie auf das Friedensangebot ein und öffnet dir ihre Tore, dann soll die Bevölkerung Zwangsarbeit verrichten und dir untertan sein." },
      { number: 12, text: "Lehnen sie das Friedensangebot ab und wollen kämpfen, dann belagere sie." },
      { number: 13, text: "Wenn Jahwe, dein Gott, sie in deine Gewalt gibt, dann bringe alles Männliche in der Stadt mit dem Schwert um." },
      { number: 14, text: "Die Frauen, die Kinder und das Vieh und alles, was sich in der Stadt plündern lässt, darfst du dir als Beute nehmen. Du darfst die Vorräte deiner Feinde, die Jahwe, dein Gott, dir ausgeliefert hat, verzehren." },
      { number: 15, text: "So sollst du es mit allen Städten machen, die weit von dir entfernt sind, nicht aber mit den Städten der Völker Kanaans." },
      { number: 16, text: "In diesen Städten, die Jahwe, dein Gott, dir als Erbbesitz gibt, sollst du nichts und niemand am Leben lassen." },
      { number: 17, text: "An allen Völkern im Land musst du unbedingt den Bann vollstrecken, wie Jahwe, dein Gott, es dir befohlen hat: an den Hetitern, Amoritern, Kanaanitern, Perisitern, Hiwitern und Jebusitern." },
      { number: 18, text: "Sonst werden sie euch dazu verführen, gegen Jahwe, euren Gott, zu sündigen und die Abscheulichkeiten nachzuahmen, die sie zu Ehren ihrer Götter begangen haben." },
      { number: 19, text: "Wenn du eine Stadt lange belagern musst, um sie zu bekämpfen, dann sollst du ihre Bäume nicht verderben, indem du die Axt gegen sie schwingst. Du kannst ja von ihren Früchten essen und sollst sie nicht abhauen. Der Baum auf dem Feld ist doch kein Mensch, den du bekämpfen musst." },
      { number: 20, text: "Nur die Bäume, von denen du weißt, dass sie nichts Essbares tragen, darfst du abhauen und mit dem Holz Belagerungsanlagen gegen die Stadt bauen, die mit dir Krieg führt, bis sie gefallen ist." },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Wenn man in dem Land, das Jahwe, dein Gott, dir zum Erbbesitz gibt, einen Erschlagenen auf dem freien Feld findet, ohne dass man weiß, wer ihn erschlagen hat,", heading: "Sühne bei unbekanntem Täter" },
      { number: 2, text: "dann sollen deine Ältesten und Richter hinausgehen und die Strecke bis zu den Städten im Umkreis abmessen." },
      { number: 3, text: "In der Stadt, die dem Erschlagenen am nächsten liegt, sollen die Ältesten eine junge Kuh heraussuchen, mit der noch nicht gearbeitet worden ist und die noch nicht am Joch gezogen hat." },
      { number: 4, text: "Die Ältesten jener Stadt sollen das Kalb zu einem immerfließenden Bach führen, an dem nichts gesät und kein Ackerbau getrieben werden kann, und ihr dort das Genick brechen." },
      { number: 5, text: "Dann sollen die Priester aus dem Stamm Levi herzutreten. Denn sie hat Jahwe, dein Gott, ausgewählt, ihm zu dienen und in seinem Namen zu segnen. Nach ihrem Spruch soll bei jedem Rechtsstreit und jeder Körperverletzung verfahren werden." },
      { number: 6, text: "In ihrer Gegenwart sollen die Ältesten der Stadt, die dem Erschlagenen am nächsten liegt, die Hände waschen, und zwar über dem Kalb, dem am Bach das Genick gebrochen wurde." },
      { number: 7, text: "Dabei sollen sie bezeugen: \"Unsere Hände haben dieses Blut nicht vergossen und unsere Augen haben es nicht gesehen. –" },
      { number: 8, text: "Jahwe, vergib deinem Volk Israel, das du erlöst hast, und lass nicht unschuldig vergossenes Blut in deinem Volk Israel bleiben.\"* Dann ist die Blutschuld für sie gesühnt.", footnotes: ["Jahwe ... bleiben. Möglicherweise sollte dieser Satz von den Priestern gesprochen werden."] },
      { number: 9, text: "So kannst du das unschuldig vergossene Blut aus deiner Mitte wegschaffen und tun, was vor Jahwe richtig ist." },
      { number: 10, text: "Wenn du gegen deine Feinde in den Krieg ziehst und Jahwe, dein Gott, sie in deine Hand gibt, kann es sein, dass du Gefangene machst.", heading: "Familiengesetze" },
      { number: 11, text: "Wenn du unter ihnen eine schöne Frau siehst, die dir gefällt, und du willst sie heiraten," },
      { number: 12, text: "dann darfst du sie mit nach Hause nehmen. Sie soll sich den Kopf scheren und ihre Nägel beschneiden." },
      { number: 13, text: "Sie soll die Kleider ablegen, die sie als Gefangene trug, und einen Monat lang um ihren Vater und ihre Mutter weinen. Dann kannst du zu ihr kommen, mit ihr schlafen und sie deine Frau sein lassen." },
      { number: 14, text: "Sollte sie dir nicht mehr gefallen, musst du sie freigeben. Du darfst sie nicht als Sklavin verkaufen oder selbst als Sklavin behalten, weil du ihr Gewalt angetan hast." },
      { number: 15, text: "Wenn ein Mann zwei Frauen hat, eine, die er liebt, und eine, die er nicht liebt, und beide ihm Söhne gebären, und wenn der erstgeborene Sohn von der ungeliebten Frau ist," },
      { number: 16, text: "dann darf er bei der Verteilung des Erbes den Sohn der geliebten Frau nicht als Erstgeborenen behandeln zum Nachteil des Sohnes der ungeliebten, der doch der Erstgeborene ist." },
      { number: 17, text: "Er muss den wirklichen Erstgeborenen, den Sohn der ungeliebten Frau, anerkennen und ihm den doppelten Anteil am Erbe geben. Denn er ist der Erstling seiner Kraft, ihm gebührt das Recht der Erstgeburt." },
      { number: 18, text: "Wenn jemand einen störrischen und widerspenstigen Sohn hat, der auf seinen Vater und seine Mutter nicht mehr hört und selbst dann nicht gehorcht, wenn sie ihn züchtigen," },
      { number: 19, text: "dann sollen seine Eltern ihn zu den Ältesten der Stadt, ans Tor ihres Ortes, bringen" },
      { number: 20, text: "und zu ihnen sagen: \"Unser Sohn hier ist störrisch und widerspenstig, er hört nicht auf uns, er ist ein Verschwender und Säufer.\"" },
      { number: 21, text: "Dann sollen ihn alle Leute der Stadt zu Tode steinigen. Du musst das Böse aus deiner Mitte entfernen. Ganz Israel soll davon hören und sich fürchten." },
      { number: 22, text: "Wenn jemand ein todeswürdiges Verbrechen begeht und hingerichtet wird und du ihn an einen Pfahl hängst," },
      { number: 23, text: "dann darf seine Leiche nicht über Nacht am Pfahl bleiben. Du musst ihn noch am selben Tag begraben. Denn ein Gehängter ist von Gott verflucht.* Du sollst das Land nicht unrein werden lassen, das Jahwe, dein Gott, dir gibt.", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Galater 3,13."] },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Wenn du siehst, dass ein Rind oder ein Schaf deines Bruders sich verirrt hat, musst du dich darum kümmern und es deinem Bruder unbedingt zurückbringen.", heading: "Nachbarschaft" },
      { number: 2, text: "Wenn dein Bruder nicht in der Nähe wohnt oder wenn du ihn nicht kennst, sollst du das Tier in dein Haus aufnehmen. Es soll bei dir bleiben, bis dein Bruder es sucht. Dann gib es ihm zurück." },
      { number: 3, text: "So sollst du es auch mit seinem Esel machen, seinem Obergewand und mit allem, was dein Bruder verliert. Du darfst das, was du findest, nicht behalten." },
      { number: 4, text: "Und wenn du siehst, dass der Esel deines Bruders oder sein Rind auf dem Weg stürzt, dann darfst du dich nicht abwenden, sondern musst deinem Bruder helfen, sie aufzurichten." },
      { number: 5, text: "Eine Frau soll keine Männersachen* tragen und ein Mann soll keine Frauenkleider anziehen, denn Jahwe, dein Gott, verabscheut jeden, der so etwas tut.*", heading: "Verschiedenes", footnotes: ["Männersachen. Das hebräische Wort ist sehr allgemein gehalten. Es schließt auch Ausrüstung und Waffen ein.", "so etwas tut. Gott verbietet hier vor allem den Transvestismus, der manchmal religiöse Züge trug. Er will, dass die Unterschiede zwischen Mann und Frau erkennbar bleiben."] },
      { number: 6, text: "Wenn du unterwegs zufällig ein Vogelnest auf einem Baum oder auf der Erde mit Jungen oder Eiern findest und die Mutter sitzt auf den Jungen oder den Eiern, dann darfst du nicht die Mutter mit den Jungen wegnehmen." },
      { number: 7, text: "Die Mutter musst du fliegen lassen, die Jungen kannst du dir nehmen. Dann wird es dir gut gehen und du wirst lange leben." },
      { number: 8, text: "Wenn du ein neues Haus baust, sollst du ein Geländer um die Dachterrasse ziehen, damit du nicht Blutschuld auf dein Haus lädst, wenn jemand herunterfällt." },
      { number: 9, text: "Du sollst deinen Weinberg nicht mit verschiedenen Gewächsen bepflanzen, sonst fällt der ganze Ertrag jener Gewächse und des ganzen Weinbergs ans Heiligtum." },
      { number: 10, text: "Du sollst nicht mit Rind und Esel zusammen pflügen." },
      { number: 11, text: "Du sollst kein Gewebe tragen, in dem Wolle und Leinen vermischt ist." },
      { number: 12, text: "Du sollst dir Quasten an den vier Zipfeln deines Mantels machen, in den du dich einhüllst." },
      { number: 13, text: "Wenn jemand eine Frau heiratet, mit ihr verkehrt, sie dann aber nicht mehr liebt", heading: "Rechtsschutz für eine verleumdete Frau" },
      { number: 14, text: "und sie deshalb in schlechten Ruf bringt, indem er öffentlich erklärt: \"Als ich mit dieser Frau die Ehe vollziehen wollte, stellte ich fest, dass sie keine Jungfrau mehr war!\"," },
      { number: 15, text: "dann sollen der Vater und die Mutter der jungen Frau das Beweisstück* ihrer Jungfräulichkeit zu den Ältesten der Stadt ans Tor bringen.", footnotes: ["Beweisstück der Jungfräulichkeit war das Betttuch der Hochzeitsnacht, gewöhnlich das letzte vorhochzeitliche Gewand der Tochter, das Blutspuren aufweisen musste."] },
      { number: 16, text: "Der Vater der jungen Frau soll zu den Ältesten dort sagen: \"Ich habe meine Tochter diesem Mann zur Frau gegeben, aber er liebt sie nicht mehr" },
      { number: 17, text: "und bringt sie in schlechten Ruf, indem er öffentlich erklärt: 'Als ich mit dieser Frau die Ehe vollziehen wollte, stellte ich fest, dass sie keine Jungfrau mehr war!' Dies hier ist das Beweisstück für die Jungfräulichkeit meiner Tochter.\" Dabei sollen sie das Tuch vor den Ältesten der Stadt ausbreiten." },
      { number: 18, text: "Dann sollen die Ältesten sich den Mann vornehmen und auspeitschen." },
      { number: 19, text: "Außerdem sollen sie ihm eine Geldbuße von 100 Silberstücken auferlegen, weil er eine Jungfrau aus Israel in schlechten Ruf gebracht hat, und diese dem Vater der jungen Frau geben. Er aber muss die Frau zeitlebens behalten und darf sie nicht verstoßen." },
      { number: 20, text: "Erweist sich die Sache aber als wahr und lassen sich keine Beweise für ihre Jungfräulichkeit beibringen," },
      { number: 21, text: "dann soll man die junge Frau vor die Tür ihres Vaterhauses führen. Dort sollen die Männer der Stadt sie zu Tode steinigen, weil sie eine Schandtat in Israel begangen und im Haus ihres Vaters gehurt hat. Du musst das Böse aus deiner Mitte entfernen." },
      { number: 22, text: "Wenn ein Mann dabei ertappt wird, dass er mit der Ehefrau eines anderen schläft, müssen alle beide sterben, der Mann, der mit der Frau geschlafen hat, und die Frau. Du musst das Böse aus Israel entfernen." },
      { number: 23, text: "Wenn ein unberührtes junges Mädchen verlobt ist, und es trifft sie ein Mann in der Stadt und schläft mit ihr," },
      { number: 24, text: "dann sollt ihr beide zum Stadttor hinausführen und dort zu Tode steinigen. Das Mädchen, weil es in der Stadt nicht um Hilfe geschrien, und den Mann, weil er der Frau* eines anderen Gewalt angetan hat. Du musst das Böse aus deiner Mitte entfernen.", footnotes: ["Frau. Eine Verlobte galt rechtlich bereits als verheiratet. Der Brautpreis war schon bezahlt."] },
      { number: 25, text: "Wenn der Mann das verlobte Mädchen aber draußen auf dem Feld trifft und sie vergewaltigt, dann muss nur er sterben." },
      { number: 26, text: "Dem Mädchen sollst du nichts tun, denn es hat keine Sünde begangen, die den Tod verdient. Denn in diesem Fall ist es so, wie wenn einer seinen Nächsten überfällt und totschlägt." },
      { number: 27, text: "Denn er traf sie draußen auf dem Feld. Das verlobte Mädchen hat vielleicht um Hilfe geschrien, aber es war niemand da, der ihr hätte helfen können." },
      { number: 28, text: "Wenn jemand ein unberührtes Mädchen vergewaltigt, das noch nicht verlobt ist, und dabei ertappt wird," },
      { number: 29, text: "dann soll der Mann, der das tat, ihrem Vater 50 Silberstücke geben, und er muss das Mädchen zur Frau nehmen, weil er sie vergewaltigt hat. Er darf sie sein Leben lang nicht verstoßen." },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Ein Mann darf nicht eine Frau seines Vaters heiraten, denn damit entehrt* er seinen Vater.", footnotes: ["entehrt. Wörtlich: die Decke seines Vaters aufdecken. Damit setzt er sich selbst an die Stelle seines Vaters."] },
      { number: 2, text: "Es darf keiner in die Gemeinde Jahwes aufgenommen werden, dessen Hoden zerquetscht oder dessen Glied abgeschnitten ist.", heading: "Wer zur Gemeinde Jahwes gehört" },
      { number: 3, text: "Es darf auch kein Mischling aufgenommen werden, selbst in der zehnten Generation darf kein Nachkomme von ihm in die Gemeinde Jahwes aufgenommen werden." },
      { number: 4, text: "Dasselbe gilt für einen Ammoniter oder Moabiter. Sie sind für immer von der Gemeinde Jahwes ausgeschlossen, selbst noch in der zehnten Generation." },
      { number: 5, text: "Denn sie haben sich geweigert, euch Brot und Wasser zu geben, als ihr von Ägypten kamt, und haben sogar Bileam Ben-Beor aus Petor in Mesopotamien gerufen, um dich zu verfluchen." },
      { number: 6, text: "Doch Jahwe, dein Gott, wollte nicht auf Bileam hören und verwandelte den Fluch in Segen für dich, denn er hatte dich lieb." },
      { number: 7, text: "Darum sollst du niemals ihr Wohl und Glück zu fördern suchen." },
      { number: 8, text: "Edomiter oder Ägypter aber sollst du nicht verabscheuen, denn ein Edomiter ist dein Bruder, und in Ägypten hast du einmal als Fremder gelebt." },
      { number: 9, text: "Ihre Kinder aus der dritten Generation dürfen in die Gemeinde Jahwes aufgenommen werden." },
      { number: 10, text: "Wenn du gegen deine Feinde in den Krieg ziehst und ein Feldlager aufschlägst, dann hüte dich vor allem Bösen.", heading: "Die Reinhaltung des Feldlagers" },
      { number: 11, text: "Wenn jemand infolge eines nächtlichen Vorfalls* nicht rein ist, muss er das Lager verlassen und sich draußen aufhalten.", footnotes: ["Vorfall. Das meint einen Samenerguss, der nach 3. Mose 15,16 unrein macht."] },
      { number: 12, text: "Gegen Abend soll er sich dann mit Wasser übergießen, und beim Untergang der Sonne darf er wieder ins Lager kommen." },
      { number: 13, text: "Außerhalb vom Lager sollst du einen Platz haben, wo du austreten kannst." },
      { number: 14, text: "Und bei deinem Gepäck musst du einen kleinen Spaten haben, damit du ein Loch graben kannst und deine Ausscheidung wieder bedeckst, wenn du dich draußen hingehockt hast." },
      { number: 15, text: "Denn Jahwe, dein Gott, hält sich mitten in deinem Lager auf, um dich zu retten und dir deine Feinde preiszugeben. Darum muss dein Lager heilig sein, damit er bei dir nichts Anstößiges sieht und sich von dir abwendet." },
      { number: 16, text: "Wenn sich ein ausländischer Sklave zu dir flüchtet, sollst du ihn seinem Herrn nicht ausliefern.", heading: "Flüchtige Sklaven" },
      { number: 17, text: "Er soll in Freiheit bei dir an einem Ort wohnen dürfen, wo es ihm gefällt. Du darfst ihn nicht unterdrücken." },
      { number: 18, text: "Unter den Frauen und Männern Israels darfst du keine Hurerei im Dienst irgendeines Gottes dulden.", heading: "Sakrale Prostitution" },
      { number: 19, text: "Auch ins Haus deines Gottes Jahwe darfst du keinen Hurenlohn und kein Hundegeld* bringen, auch nicht, um ein Gelübde damit zu erfüllen. Denn Jahwe, dein Gott, verabscheut so etwas.", footnotes: ["Hundegeld. Bezahlung männlicher Prostituierter."] },
      { number: 20, text: "Von deinem Bruder darfst du keine Zinsen nehmen, weder für Geld noch für Getreide oder sonst etwas, wofür man Zinsen nehmen kann.", heading: "Zinsen" },
      { number: 21, text: "Von einem Ausländer magst du Zinsen nehmen, nicht aber von deinem Bruder, damit Jahwe, dein Gott, dich in dem Land segnet, das du in Besitz nehmen wirst, und er deine Arbeit gelingen lässt." },
      { number: 22, text: "Wenn du Jahwe, deinem Gott, ein Gelübde ablegst, dann sollst du es ohne Verzögerung erfüllen. Denn Jahwe, dein Gott, wird es sonst von dir einfordern und es wird dir als Sünde angelastet.", heading: "Gelübde" },
      { number: 23, text: "Wenn du es unterlässt, etwas zu geloben, wird dir keine Sünde angelastet." },
      { number: 24, text: "Was über deine Lippen gegangen ist, musst du halten und tun, wie du es Jahwe, deinem Gott, freiwillig gelobt und mit deinem Mund ausgesprochen hast." },
      { number: 25, text: "Wenn du in den Weinberg deines Nächsten kommst, kannst du so viel Trauben essen, wie du willst, bis du satt bist. Aber du darfst nichts in ein Gefäß sammeln.", heading: "Erlaubter Mundraub" },
      { number: 26, text: "Wenn du in das Getreidefeld deines Nächsten kommst, darfst du mit der Hand Ähren abreißen, du darfst aber keine Sichel dabei benutzen." },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Wenn ein Mann eine Frau heiratet, sie ihm dann aber nicht mehr gefällt, weil er etwas Schändliches an ihr gefunden hat, und er ihr einen Scheidebrief ausstellt* und sie wegschickt,", heading: "Scheidung und Wiederheirat", footnotes: ["Wird im Neuen Testament von Jesus und den Pharisäern zitiert: Matthäus 5,31; 19,7."] },
      { number: 2, text: "wenn sie dann sein Haus verlässt und einen anderen Mann heiratet," },
      { number: 3, text: "und wenn auch der zweite Mann sie nicht mehr liebt, ihr einen Scheidebrief ausstellt und sie wegschickt, oder wenn dieser zweite Mann stirbt," },
      { number: 4, text: "dann darf ihr erster Mann, der sie verstoßen hat, sie nicht wieder zur Frau nehmen, nachdem sie also unrein geworden ist. Denn das verabscheut Jahwe. Du darfst das Land, das Jahwe, dein Gott, dir als Erbbesitz gibt, nicht mit Sünde beflecken." },
      { number: 5, text: "Wenn ein Mann erst kurz verheiratet ist, muss er nicht mit dem Heer ausziehen, und man soll ihm nichts auferlegen. Er soll ein Jahr für sein Haus frei sein und soll seine Frau, die er geheiratet hat, glücklich machen.", heading: "Verschiedene Schutzbestimmungen" },
      { number: 6, text: "Man darf die Handmühle oder den oberen Mühlstein nicht als Pfand nehmen, denn damit pfändet man das Leben." },
      { number: 7, text: "Findet ihr heraus, dass jemand einen anderen Israeliten, einen seiner Brüder, entführt hat und als Sklaven behandelt oder verkauft, dann muss dieser Räuber sterben. Du sollst das Böse aus deiner Mitte beseitigen." },
      { number: 8, text: "Wenn es um die Plage des Aussatzes geht, musst du sorgfältig sein und sehr genau auf das achten, was dich die levitischen Priester lehren. Denn sie tun das nach dem, was ich ihnen verordnet habe, und ihr sollt es unbedingt beachten." },
      { number: 9, text: "Denk daran, was Jahwe, dein Gott, an Mirjam getan* hat, als ihr von Ägypten hierher unterwegs wart.", footnotes: ["an Mirjam getan. Siehe 4. Mose 12,10-15."] },
      { number: 10, text: "Wenn du deinem Nächsten irgendetwas leihst, sollst du nicht zu ihm ins Haus gehen, um ihm ein Pfand abzunehmen.", heading: "Schutz der Schwachen" },
      { number: 11, text: "Draußen sollst du stehen bleiben, und der Mann, dem du leihst, soll dir das Pfand herausbringen." },
      { number: 12, text: "Wenn es ein armer Mann ist, behalte sein Pfand nicht über Nacht," },
      { number: 13, text: "sondern bringe es ihm bei Sonnenuntergang zurück, damit er sich zum Schlafen mit seinem Obergewand zudecken kann und dich dabei segnet. Das gilt als Gerechtigkeit vor Jahwe, deinem Gott." },
      { number: 14, text: "Du sollst einen armen und bedürftigen Tagelöhner nicht unterdrücken, ganz gleich, ob es einer deiner Brüder oder ein Ausländer ist, der bei dir in deinem Land lebt." },
      { number: 15, text: "Noch am selben Tag vor Sonnenuntergang sollst du ihm seinen Lohn geben. Er ist dringend darauf angewiesen. Sonst beklagt er sich bei Jahwe über dich, und du bist schuldig geworden." },
      { number: 16, text: "Die Väter sollen nicht für die Söhne und die Söhne nicht für die Väter hingerichtet werden. Jeder muss für sein eigenes Verbrechen sterben." },
      { number: 17, text: "Das Recht eines Fremden oder einer Waise darfst du nicht beugen, und den Mantel einer Witwe darfst du nicht als Pfand nehmen." },
      { number: 18, text: "Denk daran, dass du Sklave in Ägypten gewesen bist und Jahwe, dein Gott, dich von dort befreit hat. Deshalb befehle ich dir, so zu handeln." },
      { number: 19, text: "Wenn du bei der Ernte eine Garbe auf deinem Feld vergessen hast, sollst du nicht umkehren, um sie zu holen. Sie soll dem Fremden, der Waise und der Witwe gehören, damit Jahwe, dein Gott, dich in all deinem Tun segnet." },
      { number: 20, text: "Wenn du Oliven von deinem Ölbaum abklopfst, sollst du nicht anschließend noch die Zweige absuchen. Was hängen bleibt, soll dem Fremden, der Waise und der Witwe gehören." },
      { number: 21, text: "Wenn du in deinem Weinberg die Weinlese hältst, sollst du keine Nachlese halten. Dem Fremden, der Waise und der Witwe soll es gehören." },
      { number: 22, text: "Denk daran, dass du Sklave in Ägypten gewesen bist. Deshalb befehle ich dir, so zu handeln." },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Wenn Männer einen Streit miteinander haben und kommen vor Gericht, wo man ihnen Recht spricht, dann soll man dem Recht geben, der im Recht ist, und den Schuldigen verurteilen.", heading: "Begrenzung der Prügelstrafe" },
      { number: 2, text: "Hat der Schuldige Schläge verdient, soll der Richter ihn veranlassen, sich hinzulegen, und ihm nach seinem Vergehen eine bestimmte Zahl Schläge geben lassen." },
      { number: 3, text: "Vierzig Schläge darf er ihm geben lassen, nicht mehr. Dein Bruder würde vor dir entehrt werden, wenn er noch mehr Schläge bekommt." },
      { number: 4, text: "Du sollst dem Ochsen nicht das Maul verbinden, wenn er drischt*.", heading: "Tierschutz", footnotes: ["drischt. Das Tier wurde an einen Drehzapfen gebunden und drehte Runden, um das Korn zu zertreten oder einen Dreschschlitten zu ziehen. Dabei sollte es ihm erlaubt sein, zu fressen. – Der Vers wird im Neuen Testament von Paulus zitiert: 1. Korinther 9,9; 1. Timotheus 5,18."] },
      { number: 5, text: "Wenn Brüder auf demselben Grundbesitz wohnen und einer von ihnen stirbt, ohne einen Sohn zu hinterlassen, dann soll seine Witwe keinen Fremden außerhalb der Familie heiraten. Ihr Schwager soll zu ihr kommen, sie zur Frau nehmen und die Schwagerehe mit ihr vollziehen.*", heading: "Schwagerehe", footnotes: ["Wird im Neuen Testament von den Sadduzäern zitiert: Matthäus 22,24; Markus 12,19; Lukas 20,28."] },
      { number: 6, text: "Der erste Sohn, den sie dann zur Welt bringt, soll den Namen des verstorbenen Bruders weiterführen, damit dessen Name in Israel nicht untergeht." },
      { number: 7, text: "Will der Mann seine Schwägerin aber nicht heiraten, soll sie zum Versammlungsplatz am Stadttor gehen und zu den Ältesten sagen: \"Mein Schwager weigert sich, den Namen seines Bruders in Israel zu erhalten. Er will die Schwagerehe mit mir nicht eingehen.\"" },
      { number: 8, text: "Dann sollen die Ältesten der Stadt ihn rufen lassen und mit ihm reden. Doch wenn er sich hinstellt und erklärt: \"Ich habe keine Lust, sie zu heiraten!\"," },
      { number: 9, text: "dann soll seine Schwägerin ihm dort vor den Ältesten den Schuh abziehen, ihm ins Gesicht spucken und sagen: \"So behandelt man jemand, der die Familie seines Bruders nicht erhalten will!\"" },
      { number: 10, text: "In Israel wird man seine Familie dann nur noch die \"Barfüßer\" nennen." },
      { number: 11, text: "Wenn zwei Männer im Streit heftig aneinander geraten, und die Frau des einen will ihren Mann aus der Hand des Schlägers retten und packt diesen dabei an seinen Geschlechtsteilen,", heading: "Übergriff beim Streit" },
      { number: 12, text: "dann dürft ihr kein Mitleid mit ihr haben. Ihr müsst ihr die Hand abhauen." },
      { number: 13, text: "Du sollst nicht zweierlei Gewichtssteine in deinem Beutel haben, einen größeren und einen kleineren.", heading: "Rechtes Maß und Gewicht" },
      { number: 14, text: "Du sollst nicht zweierlei Hohlmaße in deinem Haus haben, ein größeres und ein kleineres." },
      { number: 15, text: "Volle und richtige Gewichte sollst du haben und ein volles und gerechtes Hohlmaß, damit du lange lebst in dem Land, das Jahwe, dein Gott, dir gibt." },
      { number: 16, text: "Denn Jahwe, dein Gott, verabscheut jeden, der so etwas tut und andere betrügt." },
      { number: 17, text: "Denk daran, was Amalek dir angetan hat, als ihr aus Ägypten zogt,", heading: "Ausrottung der Amalekiter" },
      { number: 18, text: "wie er dich überfiel und hinter dir her ohne Gottesfurcht alle Schwachen erschlug, als du erschöpft und müde warst." },
      { number: 19, text: "Wenn Jahwe, dein Gott, dir in dem Land, das er dir geben will, Ruhe verschafft hat vor all deinen Feinden ringsum, dann sollst du jede Spur von Amalek auslöschen. Vergiss es nicht!" },
    ] },
    { number: 26, verses: [
      { number: 1, text: "Wenn du in das Land kommst, das Jahwe, dein Gott, dir als Erbbesitz gibt, wenn du es dann in Besitz genommen hast und darin wohnst,", heading: "Abgabe der Erstlingsfrüchte" },
      { number: 2, text: "dann sollst du einige von den ersten Früchten deines Bodens in einen Korb legen und an den Ort bringen, an dem Jahwe, dein Gott, seinen Namen wohnen lassen wird." },
      { number: 3, text: "Du sollst zu dem Priester gehen, der zu dieser Zeit da sein wird, und ihm sagen: \"Ich bezeuge heute Jahwe, deinem Gott, dass ich in das Land gekommen bin, das Jahwe unseren Vorfahren unter Eid versprochen hat.\"" },
      { number: 4, text: "Wenn dann der Priester den Korb entgegengenommen und vor den Altar Jahwes gestellt hat," },
      { number: 5, text: "sollst du vor Jahwe, deinem Gott, sagen: \"Mein Vater war ein heimatloser Aramäer. Er zog nach Ägypten und lebte dort mit wenigen Leuten als Fremder. Aber er wurde zu einer großen, starken und zahlreichen Nation." },
      { number: 6, text: "Die Ägypter behandelten uns schlecht, unterdrückten uns und zwangen uns zu harter Arbeit." },
      { number: 7, text: "Da schrien wir zu Jahwe, dem Gott unserer Vorfahren. Er hörte uns und sah unser Elend, unsere Qualen und die Unterdrückung" },
      { number: 8, text: "und führte uns mit starker Hand und ausgestrecktem Arm aus Ägypten heraus, mit großen furchterregenden Taten, mit Zeichen und Wundern." },
      { number: 9, text: "Er brachte uns an diesen Ort und gab uns dieses Land, das von Milch und Honig überfließt." },
      { number: 10, text: "Hier bringe ich nun die ersten Früchte der Ernte, die ich in dem Land eingebracht habe, das du, Jahwe, mir gegeben hast.\" Hiermit legst du es vor Jahwe, deinem Gott, nieder und betest ihn an." },
      { number: 11, text: "Genieße voll Freude all das Gute, das Jahwe dir und deiner Familie gegeben hat zusammen mit dem Leviten und dem Fremden, der bei dir wohnt." },
      { number: 12, text: "Wenn du im dritten Jahr, dem Jahr des Zehnten, den ganzen Zehnten deines Einkommens vollständig entrichtest und ihn dem Leviten, dem Fremden, der Waise und der Witwe gegeben hast, damit sie sich in deinem Ort satt essen können,", heading: "Abgabe des Zehnten für die Armen" },
      { number: 13, text: "dann sollst du vor Jahwe, deinem Gott, erklären: \"Ich habe das Geweihte aus dem Haus weggebracht und es dem Leviten, dem Fremden, der Waise und der Witwe gegeben, wie du es mir geboten hast. Ich habe deine Gebote nicht übertreten und nicht vergessen." },
      { number: 14, text: "Ich habe nichts davon gegessen, als ich in Trauer war, nichts davon zu unreinem Gebrauch verwendet und nichts davon einem Toten gegeben*. Ich bin der Stimme Jahwes, meines Gottes, gehorsam gewesen. Ich habe alles getan, was du mir befohlen hast.", footnotes: ["einem Toten gegeben. In Ägypten war es üblich, den Toten Proviant für ihre Reise ins Jenseits mitzugeben."] },
      { number: 15, text: "Blick herab von deiner heiligen Wohnung, vom Himmel, und segne dein Volk Israel und den Boden, den du uns gegeben hast, wie du es unseren Vorfahren unter Eid versprachst: ein Land, das von Milch und Honig überfließt.\"" },
      { number: 16, text: "An diesem Tag befiehlt dir Jahwe, dein Gott, diese Vorschriften und Bestimmungen zu beachten, dass du sie mit Herz und Seele befolgst und tust.", heading: "Schlussermahnung" },
      { number: 17, text: "Du hast heute Jahwe erklären lassen, dass er dein Gott sein will und dass du auf seinen Wegen gehen, seine Vorschriften, Gebote und Bestimmungen bewahren und auf seine Stimme hören sollst." },
      { number: 18, text: "Und Jahwe hat dich heute erklären lassen, dass du sein eigenes Volk sein willst, wie er es dir versprochen hat, und dass du alle seine Gebote halten willst." },
      { number: 19, text: "Dann wird er dich zu Lob und Ruhm und zum Schmuck über alle von ihm geschaffenen Völker erhöhen, und dann wirst du ein Volk sein, das Jahwe, deinem Gott, geweiht ist. So hat er es versprochen." },
    ] },
    { number: 27, verses: [
      { number: 1, text: "Zusammen mit den Ältesten Israels befahl Mose dem Volk: \"Haltet das ganze Gebot, das ich euch heute gebe.", heading: "27-30: Die Bestätigung des Bundes\nGedenksteine mit dem Gesetz" },
      { number: 2, text: "Wenn ihr über den Jordan hinüberkommt und das Land betretet, das Jahwe, dein Gott, dir gibt, sollst du große Steine aufrichten und sie mit Kalk bestreichen." },
      { number: 3, text: "Sobald du hinübergegangen bist, sollst du alle Worte dieser Weisung darauf schreiben. So wirst du in das Land kommen, das Jahwe, dein Gott, dir gibt, das von Milch und Honig überfließt, wie es Jahwe, der Gott deiner Vorfahren, dir versprochen hat." },
      { number: 4, text: "Wenn ihr über den Jordan gezogen seid, sollt ihr diese Steine, wie ich es jetzt befehle, auf dem Berg Ebal aufrichten und mit Kalk bestreichen." },
      { number: 5, text: "Dort sollst du auch einen Altar für Jahwe, deinen Gott, bauen, einen Altar aus Steinen. Du sollst sie nicht mit Eisen bearbeiten." },
      { number: 6, text: "Aus unbehauenen Steinen sollst du den Altar für Jahwe, deinen Gott, bauen und ihm Brandopfer darauf opfern." },
      { number: 7, text: "Auch Freudenopfer sollst du dort schlachten und essen und dich vor Jahwe, deinem Gott, freuen." },
      { number: 8, text: "Und auf die Steine sollst du alle Worte dieses Gesetzes klar und deutlich schreiben.\"" },
      { number: 9, text: "Weiter sagte Mose zusammen mit den Priestern aus dem Stamm Levi zum ganzen Volk: \"Sei still und höre Israel! Heute bist du Jahwe, deinem Gott, zum Volk geworden." },
      { number: 10, text: "Höre darum auf das Wort Jahwes, deines Gottes, und richte dich nach seinen Geboten und Vorschriften, die ich dir heute gegeben habe.\"" },
      { number: 11, text: "Mose befahl dem Volk an diesem Tag:", heading: "Die Fluchworte" },
      { number: 12, text: "\"Wenn ihr über den Jordan gezogen seid, sollen die Stämme Simeon, Levi, Juda, Issachar, Josef und Benjamin auf dem Berg Garizim stehen, um das Volk zu segnen." },
      { number: 13, text: "Die Stämme Ruben, Gad, Ascher, Sebulon, Dan und Naftali sollen auf dem Berg Ebal stehen, um die Flüche auszusprechen." },
      { number: 14, text: "Die Leviten sollen mit lauter Stimme zu allen Männern Israels sprechen:" },
      { number: 15, text: "'Verflucht ist, wer ein geschnitztes oder gegossenes Bild macht, das Jahwe verabscheut, ein Werk von Künstlerhand, und es heimlich aufstellt!' Das ganze Volk soll darauf antworten und sprechen: 'Amen!'*", footnotes: ["Amen.Hebräisch: Es werde wahr!Oder: So sei es!"] },
      { number: 16, text: "'Verflucht ist, wer Vater oder Mutter verachtet!' Und das ganze Volk soll sprechen: 'Amen!'" },
      { number: 17, text: "'Verflucht ist, wer die Grenze zu seinem Nächsten verändert!' Und das ganze Volk soll sprechen: 'Amen!'" },
      { number: 18, text: "'Verflucht ist, wer einen Blinden auf den falschen Weg führt!' Und das ganze Volk soll sprechen: 'Amen!'" },
      { number: 19, text: "'Verflucht ist, wer das Recht des Fremden, der Waise oder der Witwe beugt!' Und das ganze Volk soll sprechen: 'Amen!'" },
      { number: 20, text: "'Verflucht ist, wer mit der Frau seines Vaters schläft, denn er hat seinen Vater entehrt!' Und das ganze Volk soll sprechen: 'Amen!'" },
      { number: 21, text: "'Verflucht ist, wer mit einem Tier geschlechtlich verkehrt!' Und das ganze Volk soll sprechen: 'Amen!'" },
      { number: 22, text: "'Verflucht ist, wer mit seiner Schwester schläft, der Tochter seines Vaters oder seiner Mutter!' Und das ganze Volk soll sprechen: 'Amen!'" },
      { number: 23, text: "'Verflucht ist, wer mit seiner Schwiegermutter schläft!' Und das ganze Volk soll sprechen: 'Amen!'" },
      { number: 24, text: "'Verflucht ist, wer seinen Nächsten heimlich erschlägt!' Und das ganze Volk soll sprechen: 'Amen!'" },
      { number: 25, text: "'Verflucht ist, wer Bestechung annimmt, damit ein unschuldiger Mensch getötet wird!' Und das ganze Volk soll sprechen: 'Amen!'" },
      { number: 26, text: "'Verflucht ist, wer die Worte dieser Weisung nicht annimmt, um danach zu handeln!'* Und das ganze Volk soll sprechen: 'Amen!'\"", footnotes: ["Wird im Neuen Testament von Paulus nach der LXX zitiert: Galater 3,10."] },
    ] },
    { number: 28, verses: [
      { number: 1, text: "\"Wenn du genau auf die Stimme Jahwes, deines Gottes, hörst und alle seine Gebote, die ich dir heute gebe, sorgfältig beachtest, dann wird Jahwe, dein Gott, dich hoch über alle Völker der Erde erheben.", heading: "Der Segen für Gehorsam" },
      { number: 2, text: "All diese Segnungen werden über dich kommen und dich erreichen, wenn du auf die Stimme Jahwes, deines Gottes, hörst:" },
      { number: 3, text: "Gesegnet wirst du sein in der Stadt und gesegnet auf dem Feld." },
      { number: 4, text: "Gesegnet wird sein die Frucht deines Leibes, die Frucht deines Ackerlands, die Frucht deines Viehs, die Zucht deiner Rinder und der Nachwuchs deines Kleinviehs." },
      { number: 5, text: "Gesegnet wird sein dein Korb und dein Backtrog." },
      { number: 6, text: "Gesegnet wirst du sein, wenn du heimkommst und wenn du wieder losgehst." },
      { number: 7, text: "Jahwe wird die Feinde, die sich gegen dich erheben, vor dir niederstoßen. Auf einem Weg werden sie gegen dich anrücken, und auf sieben Wegen werden sie vor dir fliehen." },
      { number: 8, text: "Auf Jahwes Befehl wird der Segen in deine Scheunen kommen und in alle Geschäfte, die du anpackst. So wirst du in dem Land, das Jahwe, dein Gott, dir gibt, lauter Segen haben." },
      { number: 9, text: "Jahwe wird dich zu einem heiligen Volk für sich erheben, wie er es dir geschworen hat, wenn du seine Gebote hältst und auf seinen Wegen gehst." },
      { number: 10, text: "Alle Völker der Erde werden sehen, dass du nach seinem Namen genannt bist, und sich vor dir fürchten." },
      { number: 11, text: "Jahwe wird dir Gutes im Überfluss geben, Frucht deines Leibes, Frucht deines Viehs, Frucht deines Ackerlandes in dem Land, das Jahwe deinen Vorfahren geschworen hat, dir zu geben." },
      { number: 12, text: "Jahwe wird dir sein Schatzhaus, den Himmel, öffnen, um deinem Land zur rechten Zeit Regen zu geben und alle Arbeit deiner Hände zu segnen. Du wirst vielen Völkern leihen können, selbst aber nicht leihen müssen." },
      { number: 13, text: "Jahwe wird dich zum Kopf machen und nicht zum Schwanz, du wirst immer die Oberhand haben und nicht unterliegen, solange du den Geboten Jahwes, deines Gottes, gehorchst, die ich dir heute zu beachten gebe," },
      { number: 14, text: "und solange du von den Worten, die ich euch heute gebiete, weder rechts noch links abweichst, um anderen Göttern nachzulaufen und ihnen zu dienen.\"" },
      { number: 15, text: "\"Wenn du aber nicht auf die Stimme Jahwes, deines Gottes, hörst und seine Gebote und Vorschriften, die ich dir heute verkünde, nicht befolgst, dann werden all diese Flüche über dich kommen und dich treffen:", heading: "Der Fluch für Ungehorsam" },
      { number: 16, text: "Verflucht wirst du sein in der Stadt und verflucht auf dem Feld." },
      { number: 17, text: "Verflucht wird sein dein Korb und dein Backtrog." },
      { number: 18, text: "Verflucht wird sein die Frucht deines Leibes, die Frucht deines Ackerlands, die Zucht deiner Rinder und der Nachwuchs deines Kleinviehs." },
      { number: 19, text: "Verflucht wirst du sein, wenn du heimkommst und wenn du wieder losgehst." },
      { number: 20, text: "Jahwe wird dir Fluch, Bestürzung und Verwünschung schicken in allen Geschäften, die du anpackst, bis du vernichtet bist, bis du schnell zugrunde gehst wegen der Bosheit deiner Taten, die zeigen, dass du mich verlassen hast." },
      { number: 21, text: "Jahwe wird dir die Pest anhängen, bis er dich wieder aus dem Land entfernt hat, das du jetzt in Besitz nehmen willst." },
      { number: 22, text: "Jahwe wird dich mit Schwindsucht, Fieberglut und Hitze schlagen, mit Entzündung, Dürre, Getreidebrand* und Vergilben des Korns. Das alles wird dich verfolgen, bis du zugrunde gehst.", footnotes: ["Getreidebrand ist eine Pilzerkrankung der Pflanze."] },
      { number: 23, text: "Der Himmel über dir wird wie aus Bronze sein und die Erde unter dir wie Eisen." },
      { number: 24, text: "Statt Regen wird Jahwe Staub und Sand vom Himmel kommen lassen, bis du umgekommen bist." },
      { number: 25, text: "Jahwe wird deinen Feinden erlauben, dich zu schlagen. Auf einem Weg wirst du gegen sie ausrücken und auf sieben Wegen vor ihnen fliehen. Zum Schreckensbild wirst du für alle Reiche der Erde." },
      { number: 26, text: "Dein Leichnam wird den Vögeln und den wilden Tieren zum Fraß, und niemand wird sie verscheuchen." },
      { number: 27, text: "Mit den Geschwüren Ägyptens wird Jahwe dich schlagen, mit Beulen, Krätze und Grind, von denen du nicht geheilt werden kannst." },
      { number: 28, text: "Mit Wahnsinn und mit Blindheit wird Jahwe dich schlagen und mit Verwirrung." },
      { number: 29, text: "Am hellen Mittag tappst du wie ein Blinder umher. Deine Wege führen nicht zum Erfolg. Dein Leben lang wirst du unterdrückt und ausgebeutet sein und niemand wird dir helfen." },
      { number: 30, text: "Du verlobst dich mit einer Frau, doch ein anderer wird sie schänden. Du baust ein Haus, wirst aber nicht darin wohnen. Du pflanzt einen Weinberg, wirst ihn aber nicht nutzen." },
      { number: 31, text: "Dein Rind wird vor deinen Augen geschlachtet, aber du wirst nichts davon essen. Dein Esel wird vor deiner Nase geraubt, und du siehst ihn nie wieder. Dein Kleinvieh wird deinen Feinden gegeben, und du hast niemand, der dir hilft." },
      { number: 32, text: "Deine Söhne und Töchter werden einem anderen Volk preisgegeben und du musst zusehen. Du wirst dich täglich nach ihnen sehnen, aber völlig machtlos sein." },
      { number: 33, text: "Die Früchte deines Ackerlands und aller deiner Arbeit werden Leute genießen, die du nicht kennst. Du wirst immerzu nur unterdrückt und misshandelt werden." },
      { number: 34, text: "Du wirst wahnsinnig werden vom Anblick dessen, was du siehst." },
      { number: 35, text: "An Knien und Schenkeln wird Jahwe dich schlagen mit bösen Geschwüren, die niemand heilen kann. Von der Sohle bis zum Scheitel wirst du krank." },
      { number: 36, text: "Jahwe wird dich und deinen König, den du über dich setzen wirst, zu einem Volk führen, das du und deine Vorfahren nicht gekannt haben. Dort wirst du anderen Göttern dienen, Göttern aus Holz und aus Stein." },
      { number: 37, text: "Du wirst zum Entsetzen werden, zum Sprichwort und zum Gespött bei allen Völkern, zu denen Jahwe dich treibt." },
      { number: 38, text: "Viel Saatgut bringst du aufs Feld, sammelst aber wenig ein, denn die Heuschrecke wird es fressen." },
      { number: 39, text: "Du wirst Weinberge anlegen und pflegen, aber den Wein weder trinken noch einkellern, denn der Wurm frisst alles kahl." },
      { number: 40, text: "Ölbäume wachsen überall in deinem Land, aber du wirst dich nicht mit Öl salben, denn die Oliven fallen ab." },
      { number: 41, text: "Söhne und Töchter wirst du zeugen, aber sie bleiben dir nicht, denn sie gehen in die Gefangenschaft." },
      { number: 42, text: "Das Ungeziefer wird all deine Bäume und die Früchte deines Ackers verderben." },
      { number: 43, text: "Der Fremde, der sich bei dir aufhält, wird sich immer mehr über dich erheben, und du wirst immer weiter herunterkommen." },
      { number: 44, text: "Er wird dir leihen, du ihm aber nicht. Er wird zum Kopf, und du wirst zum Schwanz." },
      { number: 45, text: "All diese Flüche werden über dich kommen, dich verfolgen und einholen, bis du vernichtet bist, weil du nicht auf die Stimme Jahwes, deines Gottes, gehört und seine Gebote und Vorschriften nicht gehalten hast." },
      { number: 46, text: "Diese Flüche werden als Zeichen und Beweis für immer an dir und deinen Nachkommen haften." },
      { number: 47, text: "Weil du Jahwe, deinem Gott, nicht mit Freude und fröhlichem Herzen gedient hast, als du in allem Überfluss lebtest," },
      { number: 48, text: "wirst du deinen Feinden dienen müssen, die Jahwe auf dich loslassen wird. Dabei wirst du Hunger und Durst haben, an Kleidung und allem anderen Mangel leiden. Jahwe wird ein eisernes Joch auf dich legen, bis er dich vernichtet hat." },
      { number: 49, text: "Ein Volk aus weiter Ferne, vom Ende der Erde, wird er über dich bringen. Wie ein Adler wird diese Nation auf dich herabstoßen, deren Sprache du nicht verstehst," },
      { number: 50, text: "eine Nation ohne jedes Erbarmen, die keine Rücksicht auf die Alten nimmt und für die Jungen keine Gnade kennt." },
      { number: 51, text: "Sie verzehrt alles, was dein Vieh und dein Ackerland hervorgebracht haben, bis du vernichtet bist. Sie wird dir nichts, weder Getreide noch Most oder Öl übrig lassen, weder das Jungvieh deiner Rinder noch die Zucht deines Kleinviehs, bis sie dich zugrunde gerichtet hat." },
      { number: 52, text: "Sie wird dich in allen deinen Städten belagern, bis deine hohen und festen Mauern, auf die du dich verlässt, überall im ganzen Land gefallen sind. Sie wird dich in allen deinen Städten belagern, im ganzen Land, das Jahwe, dein Gott, dir gegeben hat." },
      { number: 53, text: "In der Belagerung und Enge, in die der Feind dich treiben wird, wirst du die Frucht deines Leibes essen, das Fleisch deiner Söhne und Töchter, die Jahwe, dein Gott, dir gegeben hat." },
      { number: 54, text: "Der weichlichste und verwöhnteste deiner Männer wird begehrlich auf seinen Bruder blicken, auf seine Frau, die er liebt, und die Kinder, die ihm noch geblieben sind." },
      { number: 55, text: "Keinem wird er von dem Fleisch seiner Kinder, die er isst, etwas geben wollen, weil ihm in der Belagerung und Bedrängnis, mit der dein Feind dich in allen deinen Städten bedrängt, nichts weiter übrig geblieben ist." },
      { number: 56, text: "Die weichlichste und verwöhnteste Frau, die vor lauter Verwöhntheit und Verzärtelung noch nie versucht hat, ihren Fuß auf die Erde zu setzen, wird begehrlich auf den Mann an ihrem Busen blicken und ihrem Sohn und ihrer Tochter" },
      { number: 57, text: "die Nachgeburt missgönnen, die zwischen ihren Beinen hervorkommt, und die Kinder, die sie gebiert. Denn aus Mangel an allem wird sie das heimlich essen in der Belagerung und Bedrängnis, mit der dein Feind dich in allen deinen Städten bedrängt." },
      { number: 58, text: "Wenn du nicht alle Worte dieses Gesetzes, die in diesem Buch niedergeschrieben sind, sorgfältig beachtest, dass du Jahwe, deinen Gott, diesen furchtbaren und herrlichen Namen, fürchtest," },
      { number: 59, text: "dann wird Jahwe dich und deine Nachkommen mit außergewöhnlichen Plagen, mit bösen und hartnäckigen Krankheiten schlagen." },
      { number: 60, text: "Er wird alle Seuchen Ägyptens über dich bringen, vor denen dir graut, und sie werden an dir haften bleiben." },
      { number: 61, text: "Auch alle Krankheiten und Plagen, die in diesem Gesetzbuch nicht erwähnt werden: Jahwe wird sie über dich bringen, bis du vernichtet bist." },
      { number: 62, text: "Wenn du nicht auf die Stimme Jahwes, deines Gottes, hörst, werden nur wenige von euch übrig bleiben, statt dass ihr zahlreich seid wie die Sterne am Himmel." },
      { number: 63, text: "Und so wie Jahwe seine Freude daran hatte, euch Gutes zu tun und euch zahlreich werden zu lassen, wird er seine Freude daran haben, euch zugrunde zu richten und euch zu vernichten. Ihr werdet aus dem Erdreich herausgerissen werden, das du jetzt in Besitz nehmen willst." },
      { number: 64, text: "Jahwe wird dich unter alle Völker zerstreuen von einem Ende der Erde bis zum anderen. Dort wirst du anderen Göttern dienen, die weder du noch deine Vorfahren gekannt haben, Göttern aus Holz und Stein." },
      { number: 65, text: "Unter diesen Völkern wirst du nicht ruhig wohnen können, dein Fuß wird keine Bleibe finden. Jahwe wird dir dort ein zitterndes Herz, erlöschende Augen und eine verzweifelte Seele geben." },
      { number: 66, text: "Dein Leben wird in Gefahr schweben. Du wirst dich Tag und Nacht fürchten und deines Lebens nicht mehr sicher sein." },
      { number: 67, text: "Am Morgen wirst du sagen: 'Wäre es doch Abend!', und am Abend wirst du sagen: 'Wäre es doch Morgen!'. So voller Furcht wird dein Herz sein, und so schrecklich wird sein, was du sehen musst." },
      { number: 68, text: "Jahwe wird dich auf Schiffen wieder nach Ägypten führen auf dem Weg, von dem ich dir gesagt habe: 'Du sollst ihn nie mehr sehen.' Und dort müsst ihr euch euren Feinden als Sklaven und Sklavinnen zum Kauf anbieten, doch es wird kein Käufer da sein.\"" },
      { number: 69, text: "Das sind die Worte des Bundes, den Mose nach Jahwes Befehl mit den Israeliten im Land Moab geschlossen hat, neben dem Bund, den er am Horeb mit ihnen schloss.", heading: "Gott erneuert seinen Bund mit Israel" },
    ] },
    { number: 29, verses: [
      { number: 1, text: "Mose rief alle Israeliten zusammen und sagte zu ihnen: \"Ihr habt alles gesehen, was Jahwe in Ägypten vor euren Augen getan hat, vor dem Pharao, seinen Dienern und an seinem ganzen Land." },
      { number: 2, text: "Mit eigenen Augen habt ihr die großen Prüfungen gesehen, die großen Zeichen und Wunder." },
      { number: 3, text: "Aber Jahwe hat euch bis heute noch kein verständiges Herz gegeben, weder sehende Augen noch hörende Ohren.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 11,8."] },
      { number: 4, text: "Und ich habe euch vierzig Jahre lang in der Wüste geführt: Eure Kleidung ist nicht verschlissen und eure Schuhe haben sich nicht abgenutzt." },
      { number: 5, text: "Ihr hattet weder Brot zu essen noch Wein und Bier zu trinken, damit ihr erkennt, dass ich, Jahwe, euer Gott bin." },
      { number: 6, text: "Und als ihr an diesen Ort kamt, zogen die Könige Sihon von Heschbon und Og von Baschan gegen uns in den Krieg, doch wir konnten sie besiegen." },
      { number: 7, text: "Wir nahmen ihnen das Land weg und gaben es den Rubeniten, den Gaditen und dem halben Stamm Manasse als Erbbesitz." },
      { number: 8, text: "So haltet nun die Worte dieses Bundes und handelt danach, damit euch alles, was ihr tut, gelingt." },
      { number: 9, text: "Ihr habt euch heute alle vor Jahwe, eurem Gott, aufgestellt: eure Stammesführer, eure Ältesten, eure Aufseher, alle Männer von Israel," },
      { number: 10, text: "eure Kinder, eure Frauen und der Fremde in deinem Lager, vom Holzhauer bis zum Wasserschöpfer," },
      { number: 11, text: "um in den Bund mit Jahwe, deinem Gott, und in seine Fluchbestimmungen* einzutreten, in den Bund, den er heute mit dir schließt.", footnotes: ["Fluchbestimmungen. Siehe Kapitel 27,15-26."] },
      { number: 12, text: "Er nimmt dich heute als sein Volk an, so wie er dein Gott ist. Das hat er dir und deinen Vorfahren Abraham, Isaak und Jakob geschworen." },
      { number: 13, text: "Er schließt diesen Bund mit diesen Fluchbestimmungen aber nicht mit euch allein," },
      { number: 14, text: "sondern sowohl mit dem, der heute hier mit uns vor Jahwe, unserem Gott, steht, als auch mit dem, der heute nicht hier ist." },
      { number: 15, text: "Denn ihr wisst selbst, wie wir im Land Ägypten gewohnt haben und dann durch die verschiedenen Völker gezogen sind, die wir angetroffen haben." },
      { number: 16, text: "Da habt ihr ihre Scheusale gesehen, ihre Mistgötzen* aus Holz und Stein, Silber und Gold.", footnotes: ["Mistgötzen. Wörtlich Mistkugel, ein bewusst verächtliche Bezeichnung für die Götzenbilder."] },
      { number: 17, text: "Es soll ja niemand unter euch sein, kein Mann und keine Frau, keine Sippe und kein Stamm, dessen Herz sich heute von Jahwe, unserem Gott, abwendet, um den Göttern jener Völker zu dienen. Lasst ja keine Wurzel unter euch wachsen, die ein so giftiges und bitteres Kraut hervorbringt!" },
      { number: 18, text: "Und niemand, der die Worte dieses Eidfluches hört, soll sich in seinem Herzen segnen und sagen: \"Mir wird es gut gehen, auch wenn ich meinem sturen Herzen folge!\" Denn dann würde das bewässerte Land mitsamt dem dürren zugrunde gehen." },
      { number: 19, text: "Jahwe wird nicht bereit sein, ihm zu vergeben, sondern vor Zorn und Eifersucht schnauben. Und der ganze Fluch, der in diesem Buch niedergeschrieben ist, wird ihn treffen. Jahwe wird seinen Namen unter dem Himmel auslöschen." },
      { number: 20, text: "Er wird ihn aus allen Stämmen Israels zum Unheil herausnehmen und es werden ihn alle Eidflüche treffen, die in diesem Gesetzbuch aufgeschrieben sind." },
      { number: 21, text: "Und die zukünftige Generation, eure Kinder, die nach euch kommen werden, und der Ausländer, der aus einem fremden Land kommt: Wenn sie die Plagen dieses Landes sehen und seine Krankheiten, mit denen Jahwe es geschlagen hat," },
      { number: 22, text: "den Erdboden, eine Brandstätte voll Schwefel und Salz, die nicht besät werden kann und nichts hervorbringt, nicht einmal Unkraut aufschießen lässt wie nach der Zerstörung von Sodom und Gomorra, Adma und Zebojim, die Jahwe in Zorn und Grimm zerstört hat," },
      { number: 23, text: "dann werden sie wie alle Völker sagen: \"Warum hat Jahwe diesem Land so etwas angetan? Weshalb dieser große, glühende Zorn?\"" },
      { number: 24, text: "Man wird ihnen erwidern: \"Weil sie den Bund mit Jahwe, dem Gott ihrer Väter, verlassen haben, den er mit ihnen schloss, als er sie aus Ägypten herausführte," },
      { number: 25, text: "und weil sie anfingen, andere Götter zu verehren und sich vor ihnen niederzuwerfen, Göttern, die sie nicht kannten und die er ihnen nicht zugewiesen hatte," },
      { number: 26, text: "deshalb loderte der Zorn Jahwes gegen dieses Land auf, sodass er alle Flüche darüber kommen ließ, die in diesem Buch niedergeschrieben sind." },
      { number: 27, text: "Jahwe riss sie mit Zorn und Grimm aus ihrem Land heraus und warf sie in ein anderes Land, wie es jetzt geschehen ist.\" –" },
      { number: 28, text: "Was noch verborgen ist, steht bei Jahwe, unserem Gott. Was schon offenbar ist, geht uns und unsere Kinder an, damit wir nach allen Worten dieses Gesetzes handeln." },
    ] },
    { number: 30, verses: [
      { number: 1, text: "\"Wenn einmal all dies über dich kommt, der Segen und der Fluch, alles, was ich dir vorgelegt habe, und wenn du es dir bei den Völkern, unter die Jahwe, dein Gott, dich versprengt hat, zu Herzen nimmst", heading: "\"Du darfst zurückkehren\"" },
      { number: 2, text: "und zu Jahwe, deinem Gott, umkehrst und auf seine Stimme hörst, wie ich es dir heute sage, wenn du es zusammen mit deinen Kindern mit Herz und Seele tust," },
      { number: 3, text: "dann wird Jahwe, dein Gott, dein Geschick wenden. Er wird sich über dich erbarmen und dich wieder sammeln aus allen Völkern, unter die Jahwe, dein Gott, dich zerstreut hat." },
      { number: 4, text: "Selbst wenn du bis ans Ende der Welt versprengt wurdest, wird dich Jahwe, dein Gott, auch von dort holen und sammeln." },
      { number: 5, text: "Jahwe, dein Gott, wird dich in das Land bringen, das deine Vorfahren besessen haben, und du wirst es in Besitz nehmen. Er wird dir Gutes tun und dich zahlreicher machen, als es deine Vorfahren gewesen sind." },
      { number: 6, text: "Jahwe, dein Gott, wird dein und deiner Nachkommen Herz beschneiden, damit du Jahwe, deinen Gott, mit Herz und Seele liebst und am Leben bleibst." },
      { number: 7, text: "Und all diese Flüche wird Jahwe, dein Gott, auf deine Feinde legen, auf die, die dich hassen und dich verfolgt haben." },
      { number: 8, text: "Doch du wirst umkehren, auf die Stimme Jahwes hören und nach seinen Geboten handeln, die ich dir heute übergebe." },
      { number: 9, text: "Im Überfluss wird Jahwe, dein Gott, dir vom Ertrag deiner Arbeit geben, von der Frucht deines Leibes, der Frucht deines Viehs und der Frucht deines Ackers, und es wird dir zum Guten sein. Denn Jahwe wird sich wieder über dich freuen und dir Gutes tun, wie er sich über deine Vorfahren gefreut hat," },
      { number: 10, text: "weil du auf das Wort Jahwes, deines Gottes, hörst, um seine Gebote und Vorschriften zu halten, die in diesem Gesetzbuch aufgeschrieben sind, und weil du zu Jahwe, deinem Gott, mit Herz und Seele umkehrst.\"" },
      { number: 11, text: "\"Denn das Gesetz, das ich dir heute gebe, ist nicht zu schwer für dich und nicht zu fern.", heading: "\"Das Gesetz in deiner Nähe\"" },
      { number: 12, text: "Es ist nicht im Himmel, dass du sagen müsstest: Wer steigt für uns in den Himmel hinauf und holt es herunter und lässt es uns hören, damit wir es befolgen können?" },
      { number: 13, text: "Es ist auch nicht auf der anderen Seite des Meeres, sodass du sagen müsstest: Wer fährt für uns hinüber und holt es her und lässt es uns hören, damit wir es befolgen können?" },
      { number: 14, text: "Nein, das Wort ist dir ganz nah. Du hast es schon auf den Lippen und im Herzen, und du kannst es befolgen.\"*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 10,6-8."] },
      { number: 15, text: "\"Pass auf! Ich habe dir heute Leben und Glück vorgelegt, Tod und Unglück.", heading: "Segen und Fluch – Leben und Tod" },
      { number: 16, text: "Und ich gebiete dir heute, Jahwe, deinen Gott, zu lieben, seinen Weisungen zu folgen und dich an seine Anordnungen, Gebote und Bestimmungen zu halten! Dann wirst du leben und dich vermehren, und Jahwe, dein Gott, wird dich segnen in dem Land, das du jetzt in Besitz nimmst." },
      { number: 17, text: "Doch wenn du dein Herz abwendest und ihm nicht gehorchst, wenn du dich verführen lässt und dich vor anderen Göttern niederwirfst und sie verehrst," },
      { number: 18, text: "dann werdet ihr zugrunde gehen. Lasst es euch gesagt sein, dass ihr dann nicht lange in dem Land bleibt, das ihr jetzt in Besitz nehmen wollt, wenn ihr über den Jordan zieht." },
      { number: 19, text: "Ich rufe Himmel und Erde als Zeugen gegen euch an: Ich habe dir heute Leben und Tod vorgelegt, Segen und Fluch. Wähle das Leben, damit du am Leben bleibst, du und deine Nachkommen!" },
      { number: 20, text: "Das geschieht, indem du Jahwe, deinen Gott, liebst, ihm gehorchst und ihm treu bleibst. Denn das bedeutet Leben und hohes Alter für dich, und du wirst in dem Land wohnen bleiben, das Jahwe deinen Vorfahren Abraham, Isaak und Jakob unter Eid versprochen hat.\"" },
    ] },
    { number: 31, verses: [
      { number: 1, text: "Mose fuhr fort und sagte zum ganzen Volk Israel:", heading: "31-34: Moses Abschied und Tod\nDie Einsetzung Josuas" },
      { number: 2, text: "\"Ich bin jetzt 120 Jahre alt und kann nicht mehr euer Anführer sein. Jahwe hat mir verboten, diesen Jordan zu überschreiten." },
      { number: 3, text: "Er selbst wird aber vor dir hinüberziehen und die Nationen vor dir vernichten, sodass du ihren Besitz übernehmen kannst. Josua wird euer Anführer sein, wie Jahwe es befohlen hat." },
      { number: 4, text: "Jahwe wird mit den Völkern dieses Landes genauso umgehen wie mit den Amoriterkönigen Sihon und Og, die er vernichtet hat." },
      { number: 5, text: "Und wenn Jahwe sie euch preisgibt, sollt ihr mit ihnen so verfahren, wie ich es euch befohlen habe." },
      { number: 6, text: "Seid stark und mutig, fürchtet euch nicht und erschreckt nicht vor ihnen! Es ist Jahwe, dein Gott, der mit dir geht. Er lässt dich nicht fallen und verlässt dich nicht.*\"", footnotes: ["Wird im Neuen Testament zitiert: Hebräer 13,5."] },
      { number: 7, text: "Mose rief Josua und sagte vor allen Israeliten zu ihm: \"Sei stark und mutig! Denn du wirst mit diesem Volk in das Land kommen, das Jahwe ihren Vorfahren unter Eid zugesagt hat. Und du, du wirst es ihnen als Erbe austeilen." },
      { number: 8, text: "Jahwe selbst wird vor dir herziehen. Er wird mit dir sein, er lässt dich nicht fallen und verlässt dich nicht. Fürchte dich nicht und hab keine Angst!\"" },
      { number: 9, text: "Mose schrieb dieses ganze Gesetz auf und übergab es den Priestern, den Nachkommen Levis, die die Lade des Jahwe-Bundes trugen, und den Ältesten Israels.", heading: "Verlesung des Gesetzes im Sabbatjahr" },
      { number: 10, text: "Mose befahl ihnen: \"Alle sieben Jahre, im Erlassjahr beim Laubhüttenfest," },
      { number: 11, text: "wenn ganz Israel vor Jahwe, deinem Gott, an dem Ort erscheint, den er auswählen wird, sollt ihr dieses Gesetz öffentlich vorlesen!" },
      { number: 12, text: "Ruft dazu das ganze Volk zusammen, Männer, Frauen und Kinder, auch die Fremden an euren Orten, damit sie hören und lernen und vor Jahwe, eurem Gott, Ehrfurcht haben und damit sie alle Bestimmungen dieses Gesetzes genau beachten." },
      { number: 13, text: "Auch ihre Kinder, die dieses Gesetz noch nicht kennen, sollen zuhören, damit sie Ehrfurcht vor Jahwe, eurem Gott, haben, solange ihr in dem Land lebt, das ihr jetzt in Besitz nehmen werdet, wenn ihr über den Jordan gezogen seid.\"" },
      { number: 14, text: "Jahwe sagte dann zu Mose: \"Deine Zeit ist gekommen. Du wirst jetzt bald sterben. Rufe Josua und komm mit ihm zum Zelt der Gottesbegegnung, damit ich ihm meine Befehle erteile.\" Mose und Josua gingen hin und traten ins Zelt.", heading: "Gottes Befehl zum Schreiben des Moseliedes" },
      { number: 15, text: "Da erschien Jahwe im Zelt der Gottesbegegnung in einer Wolkensäule. Die Wolkensäule stand über dem Eingang des Zeltes." },
      { number: 16, text: "Jahwe sagte zu Mose: \"Du wirst jetzt bald mit deinen Vorfahren vereint sein. Und dieses Volk wird sich in dem Land, in das es kommt, auflehnen. Und wie eine Hure wird es sich den fremden Göttern anbieten. Es wird mich verlassen und den Bund, den ich mit ihnen geschlossen habe, brechen." },
      { number: 17, text: "Dann wird mein Zorn gegen sie losbrechen. Ich werde sie verlassen und mich vor ihnen verbergen. Sie werden anderen zum Fraß sein und von schweren Unglücksfällen und Not getroffen werden. Dann werden sie sagen: 'Hat uns nicht all das Unglück getroffen, weil unser Gott nicht mehr unter uns ist?'" },
      { number: 18, text: "Doch ich werde mich an diesem Tag völlig vor ihnen verbergen, weil sie so viel Böses getan und sich anderen Göttern zugewandt haben." },
      { number: 19, text: "Schreibt euch nun dieses Lied auf und lehrt es die Israeliten! Sie sollen es lernen, damit das Lied ein Zeuge für mich gegen die Israeliten sein wird." },
      { number: 20, text: "Denn ich werde sie in das Land bringen, das von Milch und Honig überfließt, wie ich es ihren Vorfahren geschworen habe. Sie werden sich satt essen und fett werden. Und dann werden sie sich anderen Göttern zuwenden und ihnen dienen. Mich werden sie verwerfen und meinen Bund brechen." },
      { number: 21, text: "Wenn sie dann von schweren Unglücksfällen und Not getroffen sind, soll dieses Lied als Zeuge gegen sie aussagen, denn es wird auch von ihren Nachkommen nicht vergessen werden. Ich weiß ja, wonach ihnen schon heute der Sinn steht, noch ehe ich sie in das Land gebracht habe, das ich ihnen versprach.\"" },
      { number: 22, text: "Damals schrieb Mose dieses Lied auf und brachte es den Israeliten bei." },
      { number: 23, text: "Und Jahwe sagte zu Josua Ben-Nun: \"Sei stark und mutig! Denn du wirst die Israeliten in das Land bringen, das ich ihnen unter Eid versprach. Ich werde mit dir sein!\"" },
      { number: 24, text: "Als Mose alle Worte des Gesetzes fertig aufgeschrieben hatte,", heading: "Gesetzbuch und Lied als Zeugen gegen das Volk" },
      { number: 25, text: "befahl er den Leviten, die die Lade des Bundes mit Jahwe trugen:" },
      { number: 26, text: "\"Legt dieses Buch mit dem Gesetz neben die Lade des Bundes, den Jahwe mit uns geschlossen hat, damit es ein Zeuge gegen euch Israeliten ist." },
      { number: 27, text: "Denn ich kenne euren Ungehorsam und eure Sturheit sehr wohl. Seht, heute schon, wo ich noch unter euch lebe, habt ihr euch Jahwe widersetzt, wie viel mehr nach meinem Tod?" },
      { number: 28, text: "Ruft eure Stammesführer und eure Aufseher hier vor mir zusammen, dass ich ihnen diese Worte verkünde und den Himmel und die Erde als Zeugen gegen sie aufrufe!" },
      { number: 29, text: "Denn ich weiß, dass ihr nach meinem Tod ins Verderben stürzen und von dem Weg abweichen werdet, den ich euch vorgeschrieben habe. Am Ende wird euch das Unglück treffen, weil ihr Böses vor Jahwe tun werdet und ihn durch euer Machwerk zornig macht.\"" },
      { number: 30, text: "Dann las Mose vor der ganzen Versammlung Israels folgendes Lied bis zum Ende vor:" },
    ] },
    { number: 32, verses: [
      { number: 1, text: "Höre, Himmel, ich will reden! / Die Erde höre meinen Spruch!", heading: "Das Lied Moses" },
      { number: 2, text: "Meine Lehre ströme wie Regen, / wie Tau sollen meine Worte fallen, / wie Regentropfen auf das Gras, / wie ein Guss auf welkes Kraut." },
      { number: 3, text: "Den Namen Jahwes rufe ich aus: / Gebt unserem Gott die Ehre!" },
      { number: 4, text: "Der Fels: Vollkommen ist sein Tun, / ja, alle seine Wege sind recht! / Ein treuer Gott, der niemals betrügt, / gerecht und gerade ist er!" },
      { number: 5, text: "Doch dieses Volk ist treulos und verkehrt, / sie wollten nicht mehr seine Kinder sein. / Eine Schande sind sie für sich selbst." },
      { number: 6, text: "Ist das euer Dank an Jahwe, / du dummes, verblendetes Volk? / Ist er nicht dein Vater, der dich erwarb, / der dich geformt und hingestellt hat?" },
      { number: 7, text: "Denk an die Tage der Vorzeit, / an Generationen, die nicht mehr sind! / Frag deinen Vater, dass er es dir sagt, / denn deine Alten verkünden es dir!" },
      { number: 8, text: "Als der Höchste Nationen einsetzte, / als er Adams Kinder verteilte, / bestimmte er die Grenzen der Völker / nach der Zahl der Söhne Israels*.", footnotes: ["Söhne Israels. Jüdische Ausleger beziehen das auf die 70 Nationen der Völkertafel (1. Mose 10), die den 70 Nachkommen Jakobs entsprechen (1. Mose 46,27; 2. Mose 1,5), die nach Ägypten gekommen waren."] },
      { number: 9, text: "Der Anteil Jahwes ist sein Volk, / Jakob ist sein Erbbesitz." },
      { number: 10, text: "Er hat ihn im Land der Wüste gefunden, / in der Einöde voll von grässlichem Geheul. / Er hat ihn umringt, hat auf ihn geachtet, / ihn wie seinen Augapfel beschützt." },
      { number: 11, text: "Wie der Adler sein Nest aufscheucht, / wie er über seinen Jungen schwebt, / seine Flügel unter sie breitet, / sie aufnimmt und sie auf den Schwingen trägt," },
      { number: 12, text: "so leitete Jahwe dies Volk, / kein fremder Gott war bei ihm." },
      { number: 13, text: "Er ließ es die Höhen der Erde ersteigen, / die Früchte des Ackers verzehren, / ließ es Honig aus dem Felsen saugen, / Öl aus hartem Kieselstein," },
      { number: 14, text: "Rahm von Kühen, Milch von Ziegen, / fette Lämmer, Baschans Böcke / und den besten Weizen. / Traubenblut hast du getrunken, feurigen Wein." },
      { number: 15, text: "Du wurdest fett und bockig, Jeschurun*, / ja, fett bist du geworden, dick und feist. / Und dann verließ er den Gott, der ihn schuf, / verachtete den Fels seiner Rettung.", footnotes: ["Jeschurun ist ein Ehrenname für Israel und bedeutet vielleicht: der Redliche."] },
      { number: 16, text: "Sie reizten ihn zur Eifersucht durch fremde Götter, / durch Scheusale beleidigten sie ihn." },
      { number: 17, text: "Sie opferten Dämonen, die nicht Gott sind, / Göttern, die sie früher nicht kannten, / neuen, die erst vor kurzem aufgekommen sind, / von denen eure Väter nichts wussten." },
      { number: 18, text: "Den Fels, der dich zeugte, hast du verlassen, / vergaßest Gott, der dich zur Welt gebracht." },
      { number: 19, text: "Jahwe sah es und ergrimmte, / gekränkt von seinen Söhnen und Töchtern." },
      { number: 20, text: "Er sagte: \"Ich ziehe mich von ihnen zurück, / will sehen, wohin sie das führt! / Denn sie sind ein verkehrtes Geschlecht, / Kinder, die Treue nicht kennen." },
      { number: 21, text: "Mich haben sie mit Ungöttern gereizt, / mit Nichtsen haben sie mich gekränkt. / So reize ich sie durch ein Unvolk, / kränke sie durch Menschen, die nichts von mir wissen.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 10,19."] },
      { number: 22, text: "Der helle Zorn hat mich gepackt, / ein Feuer, das bis ins Totenreich brennt, / es frisst den Boden und was darauf wächst, / entzündet die Grundfesten der Berge." },
      { number: 23, text: "Ich will Unglück über Unglück auf sie häufen, / all meine Pfeile schieße ich auf sie." },
      { number: 24, text: "Sind sie vor Hunger verschmachtet, / aufgezehrt von Fieber und giftiger Pest, / dann lasse ich die Raubtierzähne auf sie los / und das Gift der im Staube Kriechenden." },
      { number: 25, text: "Draußen rafft das Schwert sie dahin / und drinnen die Todesangst, / den jungen Mann, die junge Frau, / den Säugling und den Greis." },
      { number: 26, text: "Ich dachte: 'Ich will sie vernichten, / ich lösche ihr Andenken unter den Menschen!'" },
      { number: 27, text: "Doch ich scheute die Kränkung durch den Feind, / die Gegner würden die Wahrheit verdrehen. / Sie würden sagen: 'Unsere Macht war groß! / Jahwe hat das nicht getan.'" },
      { number: 28, text: "Sie sind ein Volk, dem jeder Rat fehlt, / Einsicht haben sie nicht." },
      { number: 29, text: "Wären sie weise, würden sie es verstehen, / dann würden sie ihre Zukunft bedenken." },
      { number: 30, text: "Wie könnte einer Tausend jagen / und zwei Zehntausend vertreiben, / wenn ihr Fels sie nicht verkauft, / wenn Jahwe sie nicht preisgegeben hat?" },
      { number: 31, text: "Ihr Fels ist nicht wie unser Fels, / so urteilen selbst unsere Feinde." },
      { number: 32, text: "Sie sind ein Weinstock, der von Sodom stammt, / und von den Terrassen Gomorras.* / Ihre Beeren sind von giftiger Art, / es sind ja vergiftete Trauben.", footnotes: ["Sodom ... Gomorra. Städte im Tal Siddim, die wegen der Sünde ihrer Bewohner von Gott vernichtet wurden, heute vermutlich unter dem Toten Meer; siehe 1. Mose 13,10-13 und 1. Mose 19."] },
      { number: 33, text: "Drachenspucke ist ihr Wein, / grausame Galle von Ottern." },
      { number: 34, text: "Liegt dies nicht bei mir verborgen, / bei meinen Schätzen versiegelt?" },
      { number: 35, text: "Mein ist die Rache und das Vergelten* / zu der Zeit, wenn ihr Fuß wankt. / Denn ihr Unglückstag wird kommen, / ihre Zukunft eilt herbei.", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 12,19."] },
      { number: 36, text: "Wenn Jahwe seinem Volk zu Hilfe kommt, / wenn er sich über seine Diener erbarmt, / wenn er sieht, dass alle Kraft geschwunden ist, / dass es aus ist mit Sklaven und Freien," },
      { number: 37, text: "dann wird er sagen: \"Wo sind nun ihre Götter, / der Fels, der ihre Zuflucht war?" },
      { number: 38, text: "Wo sind, die das Fett ihrer Schlachtopfer aßen / und den Wein ihrer Trankopfer tranken? / Sollen sie doch aufstehen und euch helfen, / sollen sie ein Schirm über euch sein!" },
      { number: 39, text: "Seht ihr nun, dass ich es bin, / ich und kein Gott neben mir? / Ich bin es, der tötet, / und ich, ich mache lebendig! / Ich, ich habe verwundet / und ich bin es, der wieder heilt! / Aus meiner Hand rettet euch keiner!" },
      { number: 40, text: "Ich hebe meine Hand zum Himmel empor / und sage: 'So wahr ich ewig lebe!'" },
      { number: 41, text: "Habe ich erst mein Schwert geschliffen / und nehme das Recht in die Hand, / dann übe ich Rache an meinen Gegnern, / vergelte es denen, die mich verachten." },
      { number: 42, text: "Meine Pfeile mache ich berauscht von Blut, / und mein Schwert frisst sich ins Fleisch, / betrunken vom Blut derer, die erschlagen und gefangen sind, / vom zerschmetterten Schädel des Feindes.\"" },
      { number: 43, text: "Ihr Nationen, preist glücklich sein Volk!* / Denn er rächt das Blut seiner Diener, / nimmt Rache an seinen Feinden, / und nimmt den Fluch von Land und Volk.", footnotes: ["Wird im Neuen Testament von Paulus nach der LXX zitiert: Römer 15,10."] },
      { number: 44, text: "Zusammen mit Josua trug Mose dem Volk das Lied im vollen Wortlaut vor.", heading: "Moses letzte Ermahnung" },
      { number: 45, text: "Als Mose damit zu Ende war," },
      { number: 46, text: "sagte er zu ganz Israel: \"Nehmt euch die Worte zu Herzen, mit denen ich euch heute ermahne! Verpflichtet eure Kinder darauf, dass sie sich an dieses Gesetz halten und nach diesem Wort handeln!" },
      { number: 47, text: "Es ist kein leeres Wort für euch, sondern es ist euer Leben. Durch dieses Wort könnt ihr lange in dem Land bleiben, wohin ihr jetzt über den Jordan zieht, um es in Besitz zu nehmen.\"" },
      { number: 48, text: "An diesem Tag sagte Jahwe zu Mose:", heading: "Moses Vorbereitung auf den Tod" },
      { number: 49, text: "\"Steig auf das Gebirge Abarim hier, auf den Berg Nebo*, der in Moab liegt, gegenüber von Jericho und betrachte das Land Kanaan, das ich den Israeliten zum Besitz geben will!", footnotes: ["Nebo.Berg in der Nähe der gleichnamigen Stadt, 15 km östlich vom Nordende des Toten Meeres. Er ist 808 m hoch und bietet eine Aussicht über das Jordantal bis nach Israel hinein."] },
      { number: 50, text: "Dann wirst du sterben auf dem Berg, den du besteigst, und wirst mit deinen Vorfahren vereint, so wie auch dein Bruder Aaron gestorben ist und mit seinen Vorfahren vereint wurde." },
      { number: 51, text: "Denn ihr habt euch mitten unter den Israeliten gegen mich vergangen an der Quelle von Meriba bei Kadesch in der Wüste Zin, und ihr habt mich nicht als den Heiligen geehrt* mitten unter den Israeliten.", footnotes: ["mich nicht ... geehrt. Vergleiche 4. Mose 20,12-13."] },
      { number: 52, text: "Du darfst das Land sehen, das dir gegenüberliegt, du wirst aber nicht in das Land hineinkommen, das ich den Israeliten gebe.\"" },
    ] },
    { number: 33, verses: [
      { number: 1, text: "Folgenden Segen sprach Mose, der Mann Gottes, vor seinem Tod über die Israeliten aus:", heading: "Der Segen Moses" },
      { number: 2, text: "\"Jahwe kam vom Sinai her / und leuchtete ihnen von Seïr auf. / Er strahlte aus dem Bergland Paran hervor, / trat aus Millionen Engeln heraus, / ein flammendes Gesetz in der Hand.*", footnotes: ["trat ... Hand. Der hebräische Text ist in den letzten beiden Satzteilen nicht sicher zu deuten."] },
      { number: 3, text: "Ja, du bist es, der die Völker liebt, / alle Geheiligten gehören dir. / Sie haben sich dir zu Füßen geworfen / und jeder achtet auf dein Wort." },
      { number: 4, text: "Ein Gesetz hat uns Mose gegeben, / der Versammlung Jakobs einen Besitz." },
      { number: 5, text: "Da wurde er König über Jeschurun, / als sich die Führer des Volkes versammelten, / die Stämme Israels gesamt.\"" },
      { number: 6, text: "\"Lass Ruben leben und nicht untergehen, / dass seine Anzahl ihm erhalten bleibt.\"" },
      { number: 7, text: "Über Juda sagte er:\"Hör, Jahwe, die Stimme Judas, / führ ihn heim zu seinem Volk! / Seine Macht sei ihm genug, / sei du ihm Hilfe gegen den Feind!\"" },
      { number: 8, text: "Über Levi sagte er:\"Seine Urim und Tummim* sollen deinem Getreuen gehören, / den du erprobt hast in Massa, / mit dem du gestritten hast am Wasser von Meriba*,", footnotes: ["Urim und Tummim waren die heiligen Lose, die bei schwierigen Entscheidungen den Schiedsspruch herbeiführten. Die Bedeutung der hebräischen Begriffe ist unsicher. Nach der LXX bedeuteten sie Licht und Recht.", "Meriba. Vergleiche 2. Mose 17,1-7."] },
      { number: 9, text: "der von Vater und Mutter sagte: / 'Ich habe sie nicht gesehen!', der seine Brüder nicht ansah, / seine Kinder nicht kannte.* / Denn sie haben dein Wort geachtet / und hielten treu zu deinem Bund.", footnotes: ["nicht kannte. Vergleiche 2. Mose 32,26-29."] },
      { number: 10, text: "Sie lehren Jakob deine Rechte / und Israel dein Gesetz. / Sie lassen Weihrauchdüfte zu dir kommen, / legen Ganzopfer auf deinen Altar." },
      { number: 11, text: "Segne, Jahwe, seine Kraft / und lass dir sein Tun gefallen. / Zerschlag seinen Feinden die Hüften, / lass die, die ihn hassen, / nie mehr gegen ihn stehn!\"" },
      { number: 12, text: "Über Benjamin sagte er:\"Er ist der Liebling Jahwes. / Durch ihn wohnt er in Sicherheit. / Er beschirmt ihn jeden Tag, / den, der zwischen seinen Berghängen* wohnt.\"", footnotes: ["Berghängen.Wörtlich: Schultern. Gemeint ist: in Gottes Schutz."] },
      { number: 13, text: "Über Josef sagte er:\"Sein Land ist von Jahwe gesegnet / mit Segen vom Himmel, mit Tau, / mit Wasser aus den Speichern der Tiefe," },
      { number: 14, text: "mit Köstlichkeiten, in der Sonne gereift, / mit Früchten aus dem ganzen Jahr," },
      { number: 15, text: "mit dem Besten der uralten Berge, / dem Köstlichsten der ewigen Hügel," },
      { number: 16, text: "mit den Köstlichkeiten eines gesegneten Landes / und der Gnade dessen, der im Dornbusch erschien.* / Das alles sei Josef geschenkt, / dem Erwählten unter seinen Brüdern.", footnotes: ["im Dornbusch erschien. 2. Mose 3,1-6."] },
      { number: 17, text: "Er ist herrlich wie ein erstgeborener Stier, / seine Hörner wie die eines Wildstiers. / Mit ihnen durchbohrt er die Völker, / selbst die am Ende der Welt. / Das sind die Zehntausende von Efraïm / und die Tausende des Stammes Manasse*.\"", footnotes: ["Efraïm und Manasse waren die beiden Söhne Josefs."] },
      { number: 18, text: "Über Sebulon sagte er:\"Freu dich, Sebulon, wenn die Schifffahrt beginnt, / und du, Issachar, über deine Zelte!" },
      { number: 19, text: "Völker laden sie ein auf den Berg, / gerechte Opfer bringen sie dort. / Denn sie nähren sich vom Reichtum des Meeres / und den verborgenen Schätzen des Sandes.\"" },
      { number: 20, text: "Über Gad sagte er:\"Gesegnet sei, wer Raum schafft für Gad! / Wie eine Löwin legte er sich hin, / Arm und Kopf reißt er seiner Beute ab." },
      { number: 21, text: "Das erste Stück hat er sich ausgesucht, / denn wo der Anteil des Anführers war, / sammelten sich die Häupter des Volkes. / Er vollstreckte die Gerechtigkeit Jahwes, / zusammen mit Israel seine Gerichte.\"" },
      { number: 22, text: "Über Dan sagte er:\"Dan ist wie ein junger Löwe, / der aus dem Baschan hervorspringt.\"" },
      { number: 23, text: "Über Naftali sagte er:\"Naftali ist mit Gnade gesättigt, / erfüllt mit dem Segen Jahwes. / Westen und Süden nimmt er in Besitz.\"" },
      { number: 24, text: "Über Ascher sagte er:\"Auf Ascher blicken liebevoll die Brüder, / er ist noch mehr gesegnet als sie. / In Öl taucht er seinen Fuß." },
      { number: 25, text: "Deine Riegel seien aus Eisen und Erz, / und deine Kraft möge dir lebenslang bleiben.\"" },
      { number: 26, text: "\"Niemand ist so wie Jeschuruns Gott, / der in den Himmel steigt, um dir zu helfen, / in seiner erhabenen Macht in die Wolken.", heading: "Schluss" },
      { number: 27, text: "Der Gott der Urzeit ist deine Zuflucht / und darunter sind ewige Arme. / Er vertrieb deine Feinde / und sagte: 'Vernichte!'" },
      { number: 28, text: "So wohnt Israel in Sicherheit, / abgesondert Jakobs Quell, / in einem Land voll Korn und Most, / dessen Himmel von Tau nur so trieft." },
      { number: 29, text: "Wie glücklich bist du, Israel! / Wer ist dir gleich, / du Volk, durch Jahwe gerettet, / den Schild, der dich schirmt, / das Schwert, das dich erhöht. / Deine Feinde schmeicheln dir, / du schreitest auf ihren Höhen einher.\"" },
    ] },
    { number: 34, verses: [
      { number: 1, text: "Vom Steppengebiet Moabs aus stieg Mose auf den Berg Nebo und zwar auf den Pisga-Gipfel, der Jericho gegenüber liegt. Dort zeigte ihm Jahwe das ganze Land von Gilead bis Dan*,", heading: "Moses Tod", footnotes: ["Die Stadt Dan lag an der Nordgrenze Israels, am Fuß des Berges Hermon."] },
      { number: 2, text: "das ganze Gebiet des Stammes Naftali, das Gebiet der Stämme Efraïm und Manasse, das ganze Gebiet des Stammes Juda bis zum westlichen Meer," },
      { number: 3, text: "den Negev und die Tiefebene des Jordan von der Palmenstadt Jericho bis nach Zoar*.", footnotes: ["Zoar. Stadt am Südende des Toten Meeres, die beim Gericht über Sodom und Gomorra verschont wurde."] },
      { number: 4, text: "Dann sagte Jahwe zu ihm: \"Das ist das Land, das ich Abraham, Isaak und Jakob unter Eid versprochen habe. Ich hatte gesagt: 'Deinen Nachkommen werde ich es geben.' Ich habe es dich jetzt mit eigenen Augen sehen lassen, aber betreten darfst du es nicht.\"" },
      { number: 5, text: "So starb Mose, der Diener Jahwes, im Land Moab, wie Jahwe es gesagt hatte," },
      { number: 6, text: "und er begrub ihn dort im Tal gegenüber von Bet-Peor*. Bis heute weiß niemand, wo sein Grab ist.", footnotes: ["Bet-Peor. Ort im Steppengebiet Moabs. Die genaue Lage ist unbekannt."] },
      { number: 7, text: "Mose war 120 Jahre alt geworden. Sein Sehvermögen hatte nicht nachgelassen und seine Kraft war nicht geschwunden." },
      { number: 8, text: "Dreißig Tage lang hielt das ganze Volk im Steppengebiet Moabs Totenklage für ihn." },
      { number: 9, text: "Aber auch Josua Ben-Nun war mit dem Geist der Weisheit erfüllt, denn Mose hatte ihm die Hände aufgelegt. Die Israeliten gehorchten ihm, wie Jahwe ihnen das durch Mose befohlen hatte.*", footnotes: ["durch Mose befohlen hatte. Vergleiche 4. Mose 27,18-23."] },
      { number: 10, text: "In Israel stand kein Prophet mehr auf wie Mose, dem Jahwe so persönlich begegnet ist" },
      { number: 11, text: "und den er solche Zeichen und Wunder am Pharao tun ließ, an seinen Beamten und dem ganzen Land Ägypten," },
      { number: 12, text: "und der Israel mit so starker Hand geführt und all die großen und furchterregenden Dinge vor den Augen des ganzen Volkes getan hat." },
    ] },
  ],
};